/* ÇEVİRİ en · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("en","olay",{
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Vânî Mehmed Efendi appointed preacher of the Yeni Cami and tutor of the sultan", "7ea6aaae"], "d": ["According to the TDV Encyclopaedia of Islam article on Mehmed Efendi, Vânî, Vânî Mehmed Efendi, who was summoned to Istanbul when Köprülüzade Fazıl Ahmed Pasha became grand vizier and presented to Mehmed IV, quickly won the sultan's close interest. In 1665 he was appointed preacher of the Yeni Cami and tutor of the sultan and became one of the most influential men of religion in the palace.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Merzifonlu Kara Mustafa Pasha appointed grand vizier", "3d1e836c"], "d": ["According to the TDV Encyclopaedia of Islam article on Merzifonlu Kara Mustafa Pasha, upon the death of Fazıl Ahmed Pasha he was made grand vizier on 28 Sha'ban 1087 (5 November 1676). As a son-in-law and protégé of the Köprülü family, with long experience in the administration of the state, Merzifonlu became one of the most powerful and influential grand viziers of Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Vânî Mehmed Efendi's death in exile", "cda714aa"], "d": ["According to the TDV Encyclopaedia of Islam article on Mehmed Efendi, Vânî, Vânî Mehmed Efendi, counted among the principal figures who had the sultan accept the Vienna campaign, was disgraced under public pressure after the campaign ended in a debacle and was exiled to the town of Kestel in Bursa. He died there on 14 Dhu al-Qa'da 1096 (12 October 1685) and was buried at the entrance of the mosque he had had built.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Köprülüzade Fazıl Mustafa Pasha appointed grand vizier and his financial reforms", "b048570e"], "d": ["According to the TDV Encyclopaedia of Islam article on Köprülüzade Fazıl Mustafa Pasha, Fazıl Mustafa Pasha, who was made grand vizier on 11 Muharram 1101 (25 October 1689), reorganised the collection of the cizye according to sharia principles, fought the mangır inflation and strengthened the treasury by transferring resources from palace institutions. He also reinforced provincial administration with reliable officials and had local councils similar to the central divan established.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["The malikâne system came into force", "316b8426"], "d": ["According to the TDV Encyclopaedia of Islam article on Mâlikâne, in the last quarter of the 17th century the increase in war expenses and the decline of revenues through territorial losses plunged the treasury into a heavy financial crisis. In the malikâne system, which came into force in 1106 (1695), tax farmers were granted a lifelong fixed right to taxes, and an incentive to protect production was introduced in place of short-term exploitation.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["The accession of Mustafa II", "b53656c7"], "d": ["According to the TDV Encyclopaedia of Islam article on Mustafa II, Mustafa II, who ascended the throne at the age of thirty-one, proclaimed his sultanate without waiting for the approval of the grand vizier and the şeyhülislam; the sword-girding ceremony was held a few days later at the Eski Cami. The sultan, who came to the throne at a time when multi-front wars were continuing after the Vienna debacle, became the last Ottoman sultan to go on campaign in person.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Feyzullah Efendi's second appointment to the şeyhülislamate", "1cf14cff"], "d": ["According to the TDV Encyclopaedia of Islam article on Feyzullah Efendi, Seyyid, following the accession of Mustafa II he was made şeyhülislam for the second time on 11 Shawwal 1106 (25 May 1695). His influence over the sultan grew steadily during this term of office, which lasted more than eight years.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi's placing his sons in high offices and the accumulated reaction", "a6398280"], "d": ["According to the TDV Encyclopaedia of Islam article on Feyzullah Efendi, Seyyid, the şeyhülislam obtained from Mustafa II an unprecedented decree that his son Fethullah Efendi would become şeyhülislam after him, and placed his relatives in high offices at a young age. These practices created wide discontent among the ilmiye class, the soldiers and the people of Istanbul; combined with rumours that the capital would be moved to Edirne, they prepared the ground for the Edirne Incident of 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["The Edirne Incident began", "5a106458"], "d": ["According to the TDV article on the 'Edirne Vak'ası', the movement, which began with the rising of soldiers who could not receive their ulufes, quickly turned into a wide rebellion in which Janissaries, madrasa students, tradesmen and the people took part. The real target of the rebellion was Şeyhülislam Feyzullah Efendi, who was alleged to interfere excessively in the affairs of state. A crowd of about 60,000 people marched from Istanbul to Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["The grand vizierate of Nevşehirli Damad Ibrahim Pasha", "8d627a6f"], "d": ["According to the TDV article on 'Damad İbrâhim Paşa, Nevşehirli', during the ongoing peace negotiations with Austria he was brought to the office of grand vizier on 8 Jumada al-Akhira 1130 (9 May 1718) and, as soon as he was appointed, turned to the negotiations that would end the war; two months later the Treaty of Passarowitz was signed (21 July 1718). In the TDV's words, 'he wished to deal with social and financial matters and longed for a period of peace that would make people forget the wars that had ended in defeat for many years'. By making reforms in finance, he reduced the soldiers' pay and created a significant surplus in the state treasury. His grand vizierate, which would last twelve years, formed the political framework of the period that bears his name (the Tulip Period).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["The founding of the Tulumbacı Ocağı", "f58b0d97"], "d": ["According to the TDV article on 'Tulumbacı', following the success shown with the tulumba (fire pump) in Istanbul fires by Gerçek Dâvud, who had returned from the 1715 Morea campaign, Grand Vizier Nevşehirli Damad Ibrahim Pasha charged him with establishing an official fire-fighting corps. The corps, founded in the Acemi Oğlanları Barracks with six officers and fifty men, reached 150 persons in 1724 and 461 in 1755. Dâvud remained at the head of the corps until his death in 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Mehmed Efendi's reception by Louis XV", "0ff5b174"], "d": ["According to the TDV article on 'Yirmisekiz Çelebi Mehmed Efendi', the ambassador was officially received at the Tuileries Palace by Louis XV, King of France, and presented the gifts and the letter of Ahmed III. During his visit he toured the palaces of Versailles, Trianon and Marly, hospitals, observatories and workshops, and recorded what he saw with drawings.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Mehmed Efendi's return to Istanbul", "a09a8bba"], "d": ["According to the TDV article on 'Yirmisekiz Çelebi Mehmed Efendi', the observations of the ambassador, returning from his one-year embassy in Paris, influenced the architectural taste of the Tulip Period. His son's later working together with Ibrahim Müteferrika prepared the ground for the founding of the first Turkish printing press, the embassy's most lasting legacy.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["The construction of the Sa'dabad Pavilion", "aec9c65e"], "d": ["According to the TDV article on 'Sâdâbâd', on the bank of the Kağıthane stream a large entertainment and promenade complex consisting of a pavilion, canals, fountains and kiosks inspired by French palace architecture was built. Sa'dabad, which became the most fashionable entertainment place of the period, was immortalised in the poems of the poet Nedim. The complex was largely destroyed during the Patrona Halil Rebellion of 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Russian forces' capture of Derbend: Peter I's Caspian campaign", "c2b269f9"], "d": ["While the Safavid State was being dragged into internal disorder by the Afghan invasion, the Russian Tsar Peter I set out on a campaign to seize the Iranian lands on the Caspian shore; the coastal city of Derbend surrendered to the Russian forces without any notable resistance. According to the Derbend entry of the TDV İslâm Ansiklopedisi, this occupation was the beginning of a temporary Russian rule that would last thirteen years; the Ottoman State, too, taking advantage of the same disorder, turned toward the western part of the Caucasus. The army had gone ashore from Astrakhan by sea in the Agrakhan gulf, and from there had marched overland along the coast via Tarku; the shamkhal of Tarku hosted Peter and entered Russian allegiance.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Abolition of the Tarku shamkhalate: direct Russian administration", "b0f029c6"], "d": ["The shamkhal of Tarku, Adil-Girey, who had hosted Peter in 1722 and entered Russian allegiance, rebelled in 1725; Yeropkin destroyed Tarku in the autumn of 1725, the shamkhal was arrested and exiled in mid-May 1726, and the shamkhalate was abolished. Tarku and its surroundings remained under direct Russian administration until the Treaty of Ganja in 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Permission granted to Ibrahim Müteferrika to found a printing press", "0659dd0a"], "d": ["According to the TDV article on 'İbrâhim Müteferrika', with the firman of Ahmed III and the fatwa of Şeyhülislam Yenişehirli Abdullah Efendi, permission was given for the founding of the first Turkish printing press. The press began operation in Istanbul's Yavuzselim quarter. Until his death in 1747 Müteferrika printed seventeen works in twenty-three volumes.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Completion of the first printed book, the Vankulu Dictionary", "684700e8"], "d": ["According to the TDV article on 'İbrâhim Müteferrika', the Turkish translation of the Sihah al-Jawhari (the Vankulu Dictionary), the press's first work, was completed in early 1729. This was the first book printed in Arabic letters in Ottoman lands and is regarded as the beginning of the history of Turkish printing.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["The execution of Nevşehirli Damad Ibrahim Pasha", "50c64341"], "d": ["According to the TDV article on 'Damad İbrâhim Paşa, Nevşehirli', the body of the grand vizier, who was killed in the palace during the Patrona Halil Rebellion, was dragged through the streets of Istanbul and abandoned near the Fountain of Ahmed III in the Sultanahmet Square. His twelve-year grand vizierate and the Tulip Period thus ended in a bloody manner.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["The abdication of Ahmed III, the accession of Mahmud I", "a43f5d40"], "d": ["According to the TDV article on 'Mahmud I', in the face of the pressure of the rebels Ahmed III abdicated after obtaining guarantees for himself and his children and himself placed his nephew Prince Mahmud on the throne. Mahmud I, who sat on the throne with his uncle's advice 'take the affairs of state into your own hands, trust no one', set about as his first task breaking the influence of the group of rebels who had put him on the throne.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Humbaracı Ahmed Pasha's reform of the artillery corps", "ea3a7c64"], "d": ["According to the TDV article on 'Humbaracı', Ahmed Pasha, an officer of French origin who had converted to Islam, undertook in the time of Grand Vizier Hekimoğlu Ali Pasha the reform of the salaried bombardier organisation in the European manner. He established a new structure of 601 men, directly attached to the grand vizier, 300 salaried and 301 with timars. With the technology of the time he had 100 mortars and 50,000 cannonballs produced.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["The founding of the Hendesehane (the first example of an engineering school)", "a77ed1f3"], "d": ["According to the TDV article on 'Mahmud I', Humbaracı Ahmed Pasha, by founding at Üsküdar the Hendesehane, also called the Humbarahane, gave military education based on mathematics and geometry to students he selected from among palace servants and bostancıs. This institution is regarded as the first example of the engineering schools that would develop in the following period.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Treaty of Ganja: return of Derbend and Baku to Iran", "ff19d531"], "d": ["Seeking an alliance with Iran against the Ottoman threat, Russia returned the Caspian coastal cities it had held for thirteen years, by the Treaty of Ganja, to Iran under the command of Nadir Khan (who had not yet taken the title of shah). According to the Derbend entry of the TDV İslâm Ansiklopedisi, this withdrawal resulted from Russia's unwillingness to struggle on two fronts at once in the south (Ottoman and Iranian), and it consolidated Nadir's military prestige, which paved the way for his accession to the throne a few years later. Tarki (Tarku), under Russian administration, also reverted to the Iranian side with this withdrawal (the day of Ganja is used on the map).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Nadir Shah's accession on the Mughan Plain: the de facto end of the Safavid dynasty", "4f640979"], "d": ["According to the Nadir Shah entry of the TDV İslâm Ansiklopedisi, the assembly of about twenty thousand people gathered on the Mughan Plain insistently asked him to take charge of Iran; Nadir accepted this offer on the condition that the extreme Shiite doctrine that had caused the wars between the Safavids and the Ottomans be abandoned and the moderate Ja'fari school adopted, and he ascended the throne on 24 Shawwal 1148 (8 March 1736) with the title of Nadir Shah. This meant the de facto end of the two-century-old Safavid dynasty and the founding of the Afsharid dynasty.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["The start of the plague epidemic in Istanbul", "9fa82b56"], "d": ["According to the TDV article on 'Tâun', the plague epidemic that was effective in the Islamic geography between 1739 and 1743 struck Istanbul as well in this period. The article notes that the epidemics of the 18th century ran a comparatively milder course than those of the previous centuries. The years 1713, 1719, 1728-1729 and 1759-1765 are also counted among the epidemic periods.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["The Hocapaşa fire", "321c7d0d"], "d": ["According to the TDV article on the 'Fatma Sultan Mosque', the Hocapaşa fire, which broke out at night, devastated the Sublime Porte and its surroundings; it is estimated that the Fatma Sultan Mosque in the district was also damaged in this fire. This disaster, one of the great fires that struck Istanbul in the time of Osman III, caused heavy destruction in the commercial and administrative centre of the city.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["The grand vizierate of Koca Ragıp Mehmed Pasha", "a1846910"], "d": ["Ragıp Pasha, known as a poet and diplomat, was brought to the office of grand vizier by Osman III (he continued in office upon the death of Osman III in October 1757, taking a new seal from Mustafa III). While the Seven Years' War continued, he followed a balanced foreign policy that kept the Ottoman State out of the conflicts in Europe. During his grand vizierate, which would last six years, he also gave importance to cultural activities such as founding libraries.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["The death of Ragıp Pasha", "6bc19323"], "d": ["Ragıp Pasha died after his six-year grand vizierate. With his death the longest-lasting and most balanced grand vizierate of the time of Mustafa III came to an end.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["The great Istanbul earthquake and the collapse of the Fatih Mosque", "2475b4dc"], "d": ["According to the TDV article on the 'Fâtih Mosque and Complex', in the great earthquake of 1766 the main dome of the mosque collapsed completely and its walls were damaged beyond repair. The reconstruction, begun in 1767 by order of Mustafa III under the architects Sarım Ibrahim Efendi and İzzet Mehmed Bey, was completed in 1771 with a new design different from the old plan.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["A short-lived artillery school attempt led by Baron de Tott", "4192260c"], "d": ["According to the TDV article on the 'Mühendishâne-i Bahrî-i Hümâyun', the failures of the Ottoman-Russian War of 1768 laid bare the need for technical military education; the short-lived artillery school opened with the contribution of the French officer Baron de Tott began operation in October 1772 but remained ineffective. This attempt is regarded as the forerunner of the Mühendishâne-i Bahrî-i Hümâyun to be founded in 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III acceded to the throne", "00d046d9"], "d": ["Upon the death of Abdülhamid I, his nephew Selim III came to the throne. According to the TDV Encyclopaedia of Islam article on Selim III, the new sultan, who had been interested in the reform of European armies since his princedom, soon after his accession began to have a radical programme of renewal prepared. This programme would within a few years be known by the name Nizam-ı Cedid.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["The preparation of the Nizam-ı Cedid reform programme began", "eff78a68"], "d": ["Selim III had a comprehensive programme of renewal prepared in line with the memoranda he requested from statesmen and foreign experts. According to the TDV Encyclopaedia of Islam article on Nizâm-ı Cedîd, this programme was not limited to founding a new army; it turned into a wide reform movement also covering finance, provincial administration and diplomacy. The programme would find both supporters and opponents over the following fifteen years.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Permanent embassies were established in the European capitals", "2e9dc8a1"], "d": ["Selim III, for the first time in Ottoman history, sent permanent ambassadors to serve continuously in the major European centres. According to the TDV Encyclopaedia of Islam article on Elçi, this step gave a lasting organisation to Ottoman diplomacy, which until then had been conducted only with temporary, one-off missions. The main duty of the new embassies was to report regularly to Istanbul the political and military developments in Europe.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["The Irad-ı Cedid treasury was established", "ae5c8ce2"], "d": ["A separate treasury was established to meet the expenses of the Nizam-ı Cedid army and the reform programme. According to the TDV Encyclopaedia of Islam article on Esham, the revenues of the new treasury included the direct operation of certain mukataas by the state and the bringing of esham sales under control. This arrangement was an attempt to create a new resource outside the traditional financial system.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["The Kabakçı Mustafa rebellion began", "b98eee17"], "d": ["The discontent accumulated against the Nizam-ı Cedid broke out with the rising of the yamak soldiers under Kabakçı Mustafa. According to the TDV Encyclopaedia of Islam article on the Kabakçı Rebellion, the rebels quickly seized control in Istanbul and demanded the heads of the statesmen in favour of the Nizam-ı Cedid. The uprising resulted within a few days in the deposition of Selim III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III was deposed", "ff2c30ec"], "d": ["Under the pressure of the Kabakçı Mustafa rebellion, Selim III was deposed with a fatwa obtained from the şeyhülislam. According to the TDV Encyclopaedia of Islam article on Selim III, this decision was the moment when the reform period of eighteen years effectively ended; the Nizam-ı Cedid army was also abolished within a short time. Selim began to be held under guard in Topkapı Palace.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV acceded to the throne", "8f1ac86c"], "d": ["Immediately after the deposition of Selim III, his nephew Mustafa IV was proclaimed sultan. According to the TDV Encyclopaedia of Islam article on Mustafa IV, the new sultan began his reign under the influence of the anti-Nizam-ı Cedid circles that had supported the rebellion. This short period was a phase of instability in which central authority weakened considerably.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pasha entered Istanbul with his army", "0cad3dea"], "d": ["Alemdar Mustafa Pasha, the ayan of Rusçuk, came before Istanbul with his army with the aim of restoring Selim III to the throne. According to the TDV Encyclopaedia of Islam article on Alemdar Mustafa Pasha, his entry into the city was received by Mustafa IV himself; however, within a few days the balance of power within the palace would change completely. This entry began the chain of events that resulted both in Selim's death and in a new accession.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III was killed", "e452f5f6"], "d": ["On the day Alemdar Mustafa Pasha seized the Sublime Porte, Selim III was killed in the palace on the order of Mustafa IV. According to the TDV Encyclopaedia of Islam article on Selim III, this was a decision taken in order to prevent an attempt to restore a deposed sultan to the throne. Selim's death resulted in the accession of Mahmud the same day.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II acceded to the throne", "661c1974"], "d": ["After the killing of Selim III, Mahmud, who remained the only male member of the dynasty, came to the throne with the support of Alemdar Mustafa Pasha. According to the TDV Encyclopaedia of Islam article on Mahmud II, the new sultan spent the first months of his reign under the tutelage of Alemdar, who had put him on the throne, and in an effort to re-establish the balance between the ayans and the centre. This period was the beginning of the radical reform process of the following twenty years.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["The Sekban-ı Cedid army was established", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasha had a new army equipped in the European manner established in place of the abolished Nizam-ı Cedid. According to the TDV Encyclopaedia of Islam article on Sekbân-ı Cedîd, this force, made up of three regiments, was regarded by the Janissaries as a direct threat and was eliminated in a Janissary uprising only a few months after its founding.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["The fall of Ibrail — the first great breach in the Danube line", "ee519321"], "d": ["In the Russian war that began in 1806, the fortress of Ibrail on the northern bank of the Danube was besieged and bombarded by Russian forces under Count Kamensky. Inside were 4100 infantry, 1100 cavalry and 260 cannon; the fortress surrendered to General Essen because of a shortage of food. The northern end of the Danube defence line was thus opened.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["The surrender of Rusçuk — the southern bank of the Danube also being lost", "084062e8"], "d": ["Rusçuk resisted the long and bloody siege of the Russian army under Count Kamensky; it surrendered on condition that the garrison and the civilian population leave the city in safety. The fall of the strongest fortress-city on the southern bank of the Danube turned the course of the war in Russia's favour.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["The Eşkinci Corps was established", "67c56759"], "d": ["Mahmud II had a new unit established, to be drilled in the European manner with soldiers selected from within the Janissary corps. According to the TDV Encyclopaedia of Islam article on the Eşkinci Ocağı, the unit began drill on 12 June 1826, but the Janissaries saw this as the end of their own corps. The rebellion that broke out three days later also ended the short life of the Eşkinci Ocağı.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["The Asakir-i Mansure-i Muhammediye was established", "14b84a7e"], "d": ["Immediately after the abolition of the Janissary Corps, Mahmud II had a new regular army trained in the European manner established in its place. According to the TDV Encyclopaedia of Islam article on the Asâkir-i Mansûre-i Muhammediyye, this army, unlike the earlier attempts, became a lasting institution with its rank order, training programme and pay system. In the following years the army would turn into the Nizamiye army of the Tanzimat period.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["The Bektashi order was closed down", "f7d9a367"], "d": ["Simultaneously with the abolition of the Janissary Corps, the Bektashi order, known for its religious ties with the corps, was also banned. According to the TDV Encyclopaedia of Islam article on Bektaşîlik, while some sheikhs of minor lodges were executed, the sheikh of the Hacı Bektaş lodge was exiled to Amasya and the lodges were handed over to Naqshbandi administration. The order, despite this heavy blow, continued its organisation secretly.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["The fan incident — the pretext for the occupation", "e949001e"], "d": ["In the negotiations that grew tense over France's unpaid old grain debt to Algiers, Dey Hussein struck the French consul Deval with the fan in his hand. This incident, arising from a debt dispute, was made the official pretext of the occupation that would begin three years later.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["The French blockade of the Algerian coast — the three-year siege", "d0ba97a5"], "d": ["After the fan incident, France put the Algerian coast under blockade. The blockade lasted three years; the ocak's maritime trade and sources of revenue were dried up, and its capacity to resist was eroded before the occupation began.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Treaty of Turkmenchay: Erivan and Talysh pass to Russia", "abffcfdb"], "d": ["When the Russo-Persian War of 1826-1828 ended in a heavy defeat for Iran, by the treaty signed at Turkmenchay the khanates of Erivan and Nakhchivan and the Talysh region on the Caspian shore (Lankaran, Astara) were ceded to Russia; a heavy war indemnity was also imposed. According to the Revan entry of the TDV İslâm Ansiklopedisi, this loss is the moment when the Russo-Iranian border in the Caucasus was drawn in a way that would remain largely valid to the present day, and it also triggered the migration of the Armenian population to Erivan.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["The second fall of Ibrail — Tsar Nicholas before the fortress", "eb6a8741"], "d": ["Ibrail, which had been returned to the Ottomans in 1812 and re-fortified in 1817-1818, was besieged in April with 4000 guards and 278 cannon inside. Its commander Ebubekir Pasha set up a new defence line; Tsar Nicholas I himself came before the fortress at the end of May. The city came under Russian occupation, but would be returned with the Treaty of Edirne and left to the principality of Wallachia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["The fez was declared the official headgear", "f55be4eb"], "d": ["Mahmud II, making a radical change in the dress of officials and soldiers, declared the fez the official headgear in place of the turban. According to the TDV Encyclopaedia of Islam article on Fes, this decision was announced by a hatt-ı hümâyun and put into practice together with the Western-style reforms of the Asâkir-i Mansûre-i Muhammediyye. The change also meant the end of the traditional hierarchy of dress.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["The cession of Akhaltsikhe to Russia — the centre of the province of Çıldır being lost", "e2e00b2a"], "d": ["Akhaltsikhe, which had been under Ottoman administration since the Battle of Çıldır in 1578 and had served as the centre of the province of Çıldır, was ceded to Russia by the Treaty of Edirne, signed at the end of the war of 1828-1829. The loss of the city created deep sorrow among the people and became the subject of many lamentations.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["The landing at Sidi Ferruch — the French army on Algerian soil", "33327553"], "d": ["After the three-year blockade, the French landing army under the command of Comte de Bourmont landed troops in the bay of Sidi Ferruch in the west of Algiers. The forces advancing toward the city broke the defence line within three weeks; on 4 July the Emperor Fort dominating the city fell, and the next day Dey Hussein surrendered.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["The exile of Dey Hussein — the effective end of the Algiers ocak", "e122403b"], "d": ["Under the terms of surrender, the last dey of Algiers, Hussein, together with his family and treasure, was taken out of the city and sent to Naples. The administration of the ocak, which had been attached to Selim II in 1519 and for three hundred years had been the most powerful Ottoman naval base in the Mediterranean, thus came to an end.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Withdrawal of the Russian army from Wallachia and Moldavia: the end of a six-year occupation", "efdb0275"], "d": ["In the Ottoman-Russian war of 1828-1829 the Russians had occupied Wallachia and Moldavia, and after the Treaty of Edirne they had not withdrawn until the war indemnity was paid. When the indemnity was reduced to five million in January 1834, the Russian forces evacuated the Danubian Principalities and new voivodes were appointed to the two principalities. Ottoman suzerainty returned on paper, but Russia retained the influence it had established through the Règlement Organique.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["The Redif-i Asakir-i Mansure organisation was established", "15947493"], "d": ["The Redif organisation, as a reserve force to support the Asâkir-i Mansûre-i Muhammediyye, was established by the regulation dated 8 July 1834. According to the TDV Encyclopaedia of Islam article on Redif, under Serasker Koca Hüsrev Pasha, battalions of about fourteen hundred men each were formed in the provincial kazas. The organisation was designed so as also to support local security without being taken into continuous service.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["The Ministry of Foreign Affairs was established", "750c6c7d"], "d": ["Mahmud II abolished the office of Reisülküttab, which conducted foreign affairs, and established the Ministry of Foreign Affairs in its place. According to the TDV Encyclopaedia of Islam article on Hariciye Nezâreti, Mehmed Akif Pasha was appointed the first minister of the new ministry, and the organisation began operation in the mansion of Rıfat Bey, the ambassador to Vienna. This arrangement was the beginning of the conduct of Ottoman foreign policy on the basis of a modern ministry.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["The Meclis-i Vala-yı Ahkam-ı Adliye was established", "69db056e"], "d": ["Mahmud II had the Meclis-i Vâlâ-yı Ahkâm-ı Adliyye established as a high-level council in which the laws and regulations to be prepared would be discussed. According to the TDV Encyclopaedia of Islam article on the Meclis-i Vâlâ-yı Ahkâm-ı Adliyye, the council actually began work on 31 March 1838, and nearly all the subsequent Tanzimat reforms were prepared and supervised through this body. The institution became one of the most important centres of the modern Ottoman bureaucracy.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["The Sinop Raid", "5947e93f"], "d": ["The Russian Black Sea fleet, under the command of Admiral Nakhimov, raided the Ottoman fleet anchored in the port of Sinop without a declaration of war; twelve ships sank, more than two thousand soldiers fell as martyrs, and the fleet commander Osman Pasha was taken prisoner. According to the TDV Encyclopaedia of Islam article on Sinop, in the raid seven mosques, two schools, 247 houses and 170 shops in the town also burned, and sixteen civilians, five of them Muslim and eleven Christian, lost their lives. The event, which echoed in European public opinion as the 'Sinop disaster', was the direct trigger of Britain and France's entering the war on the Ottoman side within a few months.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Tasvir-i Efkar was published", "506c98e2"], "d": ["Tasvir-i Efkâr, issued by Şinasi, began publication as the fourth Turkish newspaper after Takvîm-i Vekāyi', Cerîde-i Havâdis and Tercüman-ı Ahvâl. According to the TDV article on 'Tasvîr-i Efkâr', the newspaper became the mouthpiece of the Young Ottomans movement in the period of Namık Kemal, who later took over its editorship.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["The Young Ottomans Society was founded", "335fb02d"], "d": ["Ottoman intellectuals who fled to Europe under the leadership of Mustafa Fazıl Pasha organised, with a thirteen-article regulation, under the name Young Turkey. According to the TDV article on the 'Yeni Osmanlılar Cemiyeti', the group spread its demand for constitutional government by issuing newspapers such as Muhbir and Hürriyet in Paris, London and Geneva.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["The Council of State (Şura-yı Devlet) was established", "b863b306"], "d": ["The Meclis-i Ahkâm-ı Adliyye was divided in two, and the Şûrâ-yı Devlet, handling administrative affairs, and the Dîvân-ı Ahkâm-ı Adliyye, dealing with judicial affairs, were established. According to the TDV article on 'Şûrâ-yı Devlet', Midhat Pasha was appointed to the first presidency of the institution, modelled on the French Conseil d'État; the aim was the separation of the legislative, executive and judiciary from one another.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["The decree for the founding of the Darülfünun was issued", "513704bf"], "d": ["The Darülfünun was officially founded by an irade prepared by Grand Vizier Ali Pasha and Minister of Education Safvet Pasha; the first lectures, however, had begun earlier, in 1863. According to the TDV article on 'Darülfünun', the institution actually began teaching in February 1870 under the directorship of Hoca Tahsin Efendi, with departments of philosophy and literature, science and law.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Work on the Mecelle-i Ahkam-ı Adliye began", "8abdcbee"], "d": ["The Mecelle Society, formed under the presidency of Ahmed Cevdet Pasha, head of the Dîvân-ı Ahkâm-ı Adliyye, set about preparing a civil code based on Hanafi jurisprudence. According to the TDV article on the 'Mecelle-i Ahkâm-ı Adliyye', the last part of the work, consisting of sixteen books and 1851 articles, was completed on 15 September 1876 and came into force; it is regarded as the first codified form of Islamic law.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["'Vatan yahut Silistre' was staged, Namık Kemal was sent into exile", "3861284c"], "d": ["When Namık Kemal's patriotic play was staged at the Gedikpaşa Theatre, the audience poured into the streets shouting 'Long live the homeland, long live Kemal'. According to the TDV article on 'Nâmık Kemal', the government, alarmed by this demonstration, closed the newspaper İbret and on 6 April 1873 sent Namık Kemal into exile in Cyprus (Famagusta) without trial.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz died in suspicious circumstances", "85816692"], "d": ["Abdülaziz, who after being deposed was moved at his own request to the Feriye Palace (1 June 1876), was found on 4 June in his room with his wrist veins cut. A committee of nineteen doctors, including embassy physicians, prepared an ambiguously worded report; his death was announced in the newspapers on 6 June as a suicide. The investigation opened by Abdülhamid II, however, reached the conclusion that the death was not suicide but murder, and the accused were tried in 1881 at the Yıldız Court; the matter is still disputed in historiography today.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["The dismissal and exile of Midhat Pasha from the grand vizierate", "b5247b06"], "d": ["Grand Vizier Midhat Pasha, the architect of the Kanun-i Esasi, six weeks after its proclamation was dismissed by Abdülhamid II and exiled abroad within one night. According to the TDV Encyclopaedia of Islam article on Midhat Pasha, the dismissal is linked to the sultan's discomfort with the provisions in the constitution restricting his own powers. The pasha went first to Naples, then to various cities of Europe.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abdulaziz b. Saud's recapture of Riyadh from the Rashidis", "75eb8830"], "d": ["Abdulaziz, a young member of the House of Saud who had gone into exile in Kuwait ten years earlier, raided Riyadh with a small detachment and seized the city by killing the deputy governor of the Al Rashid (Shammar). According to the Riyadh entry of the TDV İslâm Ansiklopedisi, the progressive weakening of the Rashidis and their inability to send reinforcements to the city facilitated the success of this raid; the event is regarded as the founding moment of the Second Saudi State, which over the next thirty years would form the core of present-day Saudi Arabia.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["The entry of the Action Army into Istanbul", "41c8304c"], "d": ["The Action Army, which set out from Salonica and was made up mostly of units loyal to the Committee of Union and Progress, entered Istanbul to suppress the 31 March incident. According to the TDV Encyclopaedia of Islam article on the Hareket Ordusu, command was assumed by Mahmud Şevket Pasha and the chief of staff was Captain Mustafa Kemal. After brief clashes, order was restored in the city.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["The dissolution of the last Ottoman Chamber of Deputies", "2b709269"], "d": ["After the official occupation of Istanbul by the Allied forces and the arrest of many deputies, the Chamber of Deputies became unable to work and was officially dissolved by the will of Mehmed VI. According to the TDV Encyclopaedia of Islam article on Meclis-i Mebusan, this dissolution symbolised the effective end of the Ottoman constitutional parliamentary tradition. The closure strengthened the need for a new national assembly to convene in Ankara.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["The opening of the Grand National Assembly of Turkey", "6eab539d"], "d": ["After the dissolution of the Chamber of Deputies in Istanbul, the deputies gathered in Ankara and opened the Grand National Assembly of Turkey, and Mustafa Kemal Pasha was elected president of the assembly. According to the TDV Encyclopaedia of Islam article on the Türkiye Büyük Millet Meclisi, the assembly had an extraordinary character, gathering both legislative and executive power in itself. This opening was the turning point at which the political and institutional centre of the national struggle moved to Ankara.", "805871d7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Conquest of the fortress of Izvornik (Zvornik)", "657c465a"], "d": ["The fortress of Izvornik on the Drina was conquered by the Ottomans in 1460. According to the TDV İslâm Ansiklopedisi, because of its favorable position administratively and militarily, it was first made a kaza center, in 1480 it became the center of the sancak bearing the same name, and in 1491 it was fortified with stone walls and, with its six mosques, eight tekkes and baths, turned into an important administrative and commercial center.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Death of Qasim Khan, accession of Daniyar Khan (Qasim Khanate)", "522fd0fd"], "d": ["With the death of Qasim Khan, the founder of the khanate, in 873/1468, his son Daniyar succeeded him; Daniyar reigned until 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Naval Battle of Diu: Portuguese supremacy in the Indian Ocean", "1778d347"], "d": ["The Mamluk-backed fleet of Malik Ayaz, who governed the region on behalf of the Gujarat Sultanate, suffered a heavy defeat off Diu against the fleet of the Portuguese governor-general Francisco de Almeida, who was trying to establish supply bases on these coasts. This defeat gave Portugal lasting naval supremacy in the Indian Ocean and broke Mamluk-Gujarati naval power; it is regarded as the beginning of the imbalance of power that forms the background of the Red Sea-Indian Ocean struggle which the Ottomans took over after 1517 (the defense of Jeddah, the 1538 siege of Diu).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Kalender Shah rebellion", "f60f6ca4"], "d": ["Owing to financial hardships in Anatolia, discontent with new administrative arrangements, and the influence of Safavid propaganda, large Turkmen tribes such as the Çiçekli, Akça Koyunlu, Masadlı and Bozoklu, together with groups left over from the earlier Baba Zunnun rebellion, gathered around Kalender Shah and reached a force of about thirty thousand. The rebels first defeated the Beylerbeyi of Rum; when Grand Vizier Makbul Ibrahim Pasha raised troops and promised them their rights, Kalender's support melted away and the rebellion was suppressed around Elbistan; Kalender Shah and Veli Dündar were killed in June 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Conquest of Shahrizor: the capture of the fortress of Zalm", "4320d9b8"], "d": ["During Süleyman the Lawgiver's Nakhchivan campaign, the Beylerbeyi of Baghdad Osman Pasha had been charged with seizing the Shahrizor region; Baltacı Mehmed Pasha, who became beylerbeyi of Baghdad upon his death, besieged Zalm, the central fortress of the region, and took it on 22 August 1554 (23 Ramadan 961). Thus the Shahrizor basin on the western slope of the Zagros came under Ottoman administration and the connection between Baghdad and Kurdistan was secured; the region was first made a sancak and given to Murad Beg. In 1563 Beylerbeyi Muzaffer Pasha built the fortress of Gülanber as the new provincial center; the fortress would be demolished in 1623 on Shah Abbas's order and rebuilt in 1638 in the time of Hüsrev Pasha.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Conversion of the ruler of the Qasim Khanate to Christianity and his removal from the khanate", "a1a8eeb9"], "d": ["The ruler at the head of the khanate took the name 'Simeon' and became a Christian; the Russians, taking into account the reaction of the Muslim subjects, removed him from the khanate. This person was soon afterward declared nominal ruler in Moscow by Ivan the Terrible with the title 'grand prince of the tsar and of Russia' (1575) — the most striking intersection between the Qasim Khanate and the throne of Moscow.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Attachment of the sancak of Fezzan to Tripoli: Murzuk and the Saharan caravan junction", "2e6554a4"], "d": ["As a result of pressure from the beylerbeyilik of Tripoli, Fezzan, the caravan junction of the Sahara, accepted Ottoman allegiance, with Murzuk as its center. According to the Fezzan entry of the TDV İslâm Ansiklopedisi, the Awlad Muhammad dynasty that ruled the region was left free in its internal affairs on condition of paying regular taxes; Fezzan was organized as a sancak attached to the province of Tripoli, taken in 1551. Thus the trade in slaves, gold and camels along the Tripoli-Murzuk-Bornu route came under Ottoman control. This indirect administration would pass to the Karamanlis in 1711 and in 1842 to a direct kaza organization.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Nakhchivan and Ordubad come under Ottoman administration", "24d939b3"], "d": ["After Erivan was taken in 1583 and made a beylerbeyilik center, the forces that descended southeast along the Aras valley brought Nakhchivan and Ordubad under Ottoman administration; the two cities became sancaks of the newly established province of Erivan. According to the Nakhchivan entry of the TDV İslâm Ansiklopedisi, lasting Ottoman administration was established in the city for the first time during this war — in the Nakhchivan campaign of 1553 the city had been taken but merely plundered and abandoned. Thus the army road between Erivan and Tabriz was opened, and in September of the same year Tabriz could be entered. Shah Abbas would retake Nakhchivan in 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Revolt of Deli Hasan Pasha and his pacification with the beylerbeyilik of Bosnia", "144f3f2d"], "d": ["After the death in 1602 of the Jelali leader Karayazıcı Abdülhalim, his brother Deli Hasan, who took over the movement, took advantage of the freedom of movement that the ongoing Austrian wars afforded the Jelali groups, invaded Kütahya and marched on Afyonkarahisar. In this period when the state was dealing with the Austrian and Iranian fronts at the same time, the matter was resolved 'amicably': Deli Hasan was given the rank of pasha and the beylerbeyilik of Bosnia, and the rebel movement was officially ended in 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Russian forces' capture of the city of Qasim, Uraz Muhammad Khan", "b3f0bd34"], "d": ["As a reflection of the Time of Troubles (Smuta) in Russia, Russian forces besieged and captured the city of Qasim and put most of its people to the sword. Uraz Muhammad, at the head of the khanate, had been targeted because he supported the Second False Dmitry; the following year (1610) he himself was killed in a plot.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Loss of the Fortress of Azak to the Don Cossacks", "ba068b2f"], "d": ["The Don Cossacks took the Fortress of Azak, which they had besieged on 21 April 1637, two months later; the fortress, which was the northeastern gate of the Black Sea and the lock of the Don trade, left Ottoman hands for the first time. According to the Azak entry of the TDV İslâm Ansiklopedisi, the Cossacks took the fortress in 1637, withstood in 1641 a great three-month siege under the command of Deli Hüseyin Pasha, and evacuated the fortress only in 1642 with the arrival of the Crimean Khan Mehmed Giray. The state was at that time preoccupied with the Baghdad front; the failure to hold the fortress for five years is the first crack in the Black Sea's character as an 'Ottoman lake.'", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Recapture of Lemnos and Samothrace", "c445553b"], "d": ["After the liberation of Tenedos on 31 August 1657, Köprülü Mehmed Pasha directed the fleet northward and recaptured Lemnos and Samothrace, which Venice had held for sixteen months. According to the Lemnos entry of the TDV İslâm Ansiklopedisi, the island had passed into Venetian hands in July 1656 and was retaken in November 1657. Thus the Venetian blockade at the mouth of the Dardanelles was completely broken and Istanbul's grain route was secured again; this is the most concrete gain of the first year of the grand vizier's tenure with extraordinary powers.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Loss of Knin to Venice: the 166-year-old Dalmatian frontier fortress fell", "252406b7"], "d": ["In the multi-front war opened after the Vienna defeat of 1683, Venetian forces advanced into the interior of Dalmatia. Knin, besieged by the Dalmatian general Girolamo Cornaro, was surrendered by Beylerbeyi Mehmed Pasha after a twelve-day siege. Knin was the key fortress of the Dalmatian frontier line, which Gazi Hüsrev Beg had conquered in 1522 and which had remained in Ottoman hands for 166 years; its loss largely opened the region to Venice.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Recovery of Basra from the Iranian occupation", "5b10c5c1"], "d": ["Basra, which Sadiq Khan, brother of Karim Khan Zand, had seized in 1776, was evacuated when a struggle for the throne began in Iran after Karim Khan's death on 2 March 1779; Sadiq Khan returned to Iran with a claim to the sultanate. The city remained for a short time in the hands of the Muntafiq tribe and then came under Ottoman administration again. The former mutesellim Süleyman Agha, who had returned from Shiraz, asked for the governorship of Basra and, under the name Büyük Süleyman Pasha, became governor of Basra, Baghdad and Shahrizor. Gulf trade returned to Ottoman control; during the years of occupation part of the trade had shifted to Kuwait, and from 1778 the desert post had also been dispatched from Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Death of Timur Shah, accession of Zaman Shah (Durrani State)", "c3effdb2"], "d": ["With the death of Timur Shah, who had spent more than twenty years consolidating the country internally, his three sons, the governors of Kandahar, Herat and Kabul, contended for the throne; Zaman Shah, the governor of Kabul, who held the capital, became shah on 20 May 1793. This succession crisis is the de facto beginning of the dynasty's process of fragmentation.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa: the end of the traditional kapu system in Hawaii", "0b10e1d8"], "d": ["Six months after the death of Kamehameha I, the new king Liholiho, with the support of his mother Kaʻahumanu, deliberately broke the prohibition on men and women eating together (ʻaikapu). This act, known as 'ʻAi Noa' (free eating), formally ended the traditional kapu religio-legal system; the old temples (heiau) on the islands were soon torn down. It is the greatest religious and political rupture before the arrival of Western missionaries (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["London Protocol: recognition of Greek independence", "4c7b4b72"], "d": ["The protocol signed in London by Britain, France and Russia went beyond the autonomy envisaged by the Treaty of Edirne and recognized Greece as an INDEPENDENT state. Provisions: the Morea peninsula, Attica and Euboea, together with the Cyclades islands, were left to the new state; the border was drawn on the Arta-Volos line; payment of an indemnity to the Ottoman State was decided; the form of government of the state was determined as an 'independent monarchy.' This is the FIRST independent state to break away from the empire and it set the legal precedent for the later Balkan independences.", "e8fc6290"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah b. Rashid seized the emirate of Ha'il: the founding of the Shammar (Rashidi) dynasty", "fb513b8a"], "d": ["With the fall of Diriyah to the forces of Mehmed Ali Pasha in 1818, the Jabal Shammar region left Saudi rule and the emirate remained in the hands of the Ibn Ali family. Abdullah b. Rashid, who supported the re-establishment of Ottoman rule, together with his brother Ubayd won the struggle he waged against the Ibn Ali family in 1835, seized the emirate of Ha'il and established the rule of the Rashidi dynasty.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Hawaii's first written constitution was proclaimed", "401a8a1d"], "d": ["The kingdom's first full written constitution was proclaimed; this document, which limited the king's authority and established a representative legislature, turned Hawaii into a constitutional monarchy.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Bayonet Constitution: King Kalākaua's powers curtailed", "4953363b"], "d": ["An armed militia group threatened King Kalākaua and forced him to sign a new constitution that largely curtailed the powers of the kingdom; the document is known as the 'Bayonet Constitution' and placed the throne effectively under the control of the white settler elite.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Death of George Tupou I, accession of George Tupou II (Tonga)", "b56e2b32"], "d": ["With the death of the founding king George Tupou I, his great-grandson George Tupou II took the throne; the coronation ceremony was held at Nukuʻalofa on 17 March 1893.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["New Zealand became the first self-governing country to grant women the vote", "0d277cde"], "d": ["With the new Electoral Act signed by the Governor, Lord Glasgow, New Zealand became the world's first self-governing country to grant women the right to vote in parliamentary elections.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Republic of Hawaii proclaimed", "4346bd5d"], "d": ["The conspirators who overthrew Queen Liliuokalani in 1893 turned the provisional government into a formal republic; Sanford Dole was proclaimed president. This interim regime lasted until the American annexation of 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["New Zealand's boundaries extended to include the Cook Islands and Niue", "d0370a33"], "d": ["New Zealand's boundaries were extended to include the Cook Islands (Rarotonga, Aitutaki and the southern islands, and the northern Cook Islands) and Niue; these islands became territory attached to New Zealand.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Death of George Tupou II, accession of Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II died of tuberculosis; his 18-year-old daughter Sālote was proclaimed queen the next day, and the coronation ceremony was held on 11 October 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Khwarazm People's Republic proclaimed", "0a6b79f9"], "d": ["After the overthrow of the Khan of Khiva following the October Revolution of 1917, the Khwarazm People's Republic was proclaimed.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Treaty of Sèvres: the text of the partition of the empire", "64980d7b"], "d": ["The text that the Ottoman government signed with the Allied powers and that effectively liquidated the empire. Provisions: Eastern Thrace and the region of Izmir to Greece; an independent Armenia and an autonomous Kurdistan envisaged in Eastern Anatolia; Syria left to France, and Iraq and Palestine to Britain, as mandates; the Straits handed over to an international commission; the army reduced to 50,700 men, the capitulations restored, finances placed under Allied control. The Grand National Assembly in Ankara did NOT RECOGNIZE the treaty AT ALL and declared its signatories traitors to the homeland; the text did not enter into force and was replaced in 1923 by Lausanne. This is the reason it has no counterpart on the map — Sèvres was never legally implemented.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Red Army entered the city of Bukhara: the last emir Alim Khan removed from the throne", "f8f5bfcf"], "d": ["The Red Army entered the city of Bukhara on 2 September 1920 and the last Manghit emir Alim Khan was removed from the throne. The emir withdrew to the east of the country, to Dushanbe, and for half a year directed the struggle against the Soviets from there; the Red Army took Dushanbe on 21 February 1921, and the emir passed farther east and from there to Afghanistan. The khanate was formally abolished on 6 October 1920 (see the Bukharan People's Soviet Republic).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Bukharan People's Soviet Republic proclaimed", "ef579627"], "d": ["After the Red Army overthrew the Emirate of Bukhara on 28-31 August 1920 and drove Emir Alim Khan to Eastern Bukhara, the Bukharan People's Soviet Republic was proclaimed under the chairmanship of Faizullah Khojaev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["People's Republic of Tannu Tuva declared its independence", "8710ea3d"], "d": ["Independence was proclaimed under the leadership of the Tuvan People's Revolutionary Party; the first article of the first constitution stated that the state acted 'in international relations under the protection of Soviet Russia.'", "3c6cec2c"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["New constitution of the Bukharan People's Soviet Republic adopted", "fb17bf39"], "d": ["A new constitution was adopted which, unlike the Russian constitution of 1918, permitted private ownership of land and production and granted the vote also to non-proletarians (except the relatives of the deposed emir and large landowners).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Transformation into the Khwarazm Soviet Socialist Republic", "14a1d26f"], "d": ["The country changed its name and status and became the Khwarazm Soviet Socialist Republic; the administrative and legal structure was reorganized according to the Soviet system.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["The government of Tannu Tuva de facto took office", "22ea1516"], "d": ["The government formed after the first party meeting in February 1922 de facto took office.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["The first Great Khural of Tannu Tuva convened", "80fe15f2"], "d": ["The country's first Great Khural (People's Assembly) convened; this is the first major representative meeting in the process of the institutionalization of the state.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["End of the Khwarazm SSR and the Bukharan People's Soviet Republic through national delimitation: founding of the Uzbek and Turkmen SSRs", "e8c8ab4f"], "d": ["By the Soviet decision of 'national delimitation' (natsionalno-territorialnoe razmezhevanie), the Khwarazm Soviet Socialist Republic and the Bukharan People's Soviet Republic were abolished; their territories were divided between the newly established Uzbek and Turkmen Soviet Socialist Republics (the east of Khiva to Uzbekistan, the west to Turkmenistan). The TDV `harizm` entry: '1924’te Hîve Hanlığı’nın doğu kesimleri Özbekistan Sovyet Sosyalist Cumhuriyeti’ne, batı tarafı da Türkmenistan Sovyet Sosyalist Cumhuriyeti’ne bırakıldı.' — it gives only the year.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Sale of Alanya to the Mamluk Sultan Barsbay", "c8bd35f2"], "d": ["Alanya, which Karamanoğlu Mecdüddin Mahmud Beg had seized in 1293, had become a separate principality governed by a branch of the Karamanids; Ibn Battuta records in 1333 that the administration was in the hands of Karamanoğlu Yusuf Beg. In 1427 Karaman b. Savcı Beg sold the city to the Mamluk Sultan Barsbay for five thousand gold pieces, and Alanya came under Mamluk administration. This key port of the Mediterranean thus became a Mamluk-held obstacle on the Ottoman road opening to the south; when Gedik Ahmed Pasha besieged it in 1471, the last bey, Kılıçarslan, surrendered the city.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Taking of Tabarka from the Genoese: end of the Lomellini coral concession", "b1f33eb5"], "d": ["After Charles V's agreement of 1544 with the Bey of Tunis, the Genoese Lomellini family had settled on the island of Tabarka and for two hundred years held the coral concession; the island had remained a Christian trading outpost in the middle of Ottoman Tunisia. Ali Pasha of the Husainid dynasty, learning of the family's attempt to dispose of the island, sent forces and seized it on 12 June 1741; about fifteen hundred Christians were transferred to Tunis. After this date Tabarka came under the administration of the Tunisian ocak.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Battle of the Pyramids and the French capture of Cairo", "3ddd6b96"], "d": ["Napoleon marched south along the Nile from Alexandria and on 21 July 1798 met Murad Bey's Mamluk cavalry at Imbaba, opposite Giza. The French infantry in square formation broke the cavalry charges; the Mamluk army dispersed and Cairo surrendered without resistance two days later. Murad Bey withdrew to Upper Egypt and Ibrahim Bey to Syria. The French set up a divan in Cairo and tried to run the administration through the ulema; two great Cairo uprisings broke out in October 1798 and March 1800.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Napoleon's siege of Acre: halting of the Syrian campaign", "d2a947ad"], "d": ["Wishing to disperse the forces the Ottomans were preparing to retake Egypt, Napoleon marched into Syria in early 1799; he took El Arish on 18 February and Jaffa in March, and besieged Acre on 18 March 1799. The defense of Cezzar Ahmed Pasha and the support of the British admiral Sidney Smith from the sea broke the siege over two months; because the siege guns had been captured at sea, the walls could not be breached. Napoleon withdrew in May, and this defeat marked the farthest point of the French occupation.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Founding of Emir Abd al-Qadir's state: centralization of the resistance in western Algeria", "9e482383"], "d": ["The resistance that had dispersed after the fall of Algiers gathered around the young Abd al-Qadir, son of the Qadiri sheikh Muhyiddin; on 22 November 1832, near Mascara, the tribal chiefs pledged allegiance to him with the title 'commander of the faithful.' The structure he established was not a tribal alliance but a regular state: it had a mint, a gunpowder workshop, a tax system and a capital at Tagdempt. France formally recognized his sovereignty by the Treaty of Tafna of 1837. Abd al-Qadir took refuge not with the Ottomans but under the suzerainty of the Moroccan sultan Abd al-Rahman; that is, these lands were not under Ottoman allegiance after 1832. He surrendered on 23 December 1847, and the Ottoman State declared in the same year that its rights over Algeria had ended.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Fall of Constantine: end of the eastern Algerian beylik", "159fed36"], "d": ["After the fall of Algiers in 1830 the eastern beylerbeyilik did not dissolve: the last bey, Ahmed, continued his own administration in Constantine and declared that he was acting in the name of the Ottomans. The first French expedition of 1836 ended in a rout; the second expedition besieged the city on 6 October 1837, the commander Damrémont was killed by cannon fire on 12 October, and on 13 October the walls were breached and the city was taken street by street. Ahmed Bey withdrew to the mountains and surrendered only in 1848. This date is the de facto end of three hundred years of Ottoman-Turkish rule in eastern Algeria.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Conquest of the Taka region and founding of Kassala", "cc3e0631"], "d": ["The governor of the Sudan, Ahmed Pasha Abu Widan, brought the Taka region between the Atbara and Gash rivers under Egyptian administration in 1840 and founded the city of Kassala as a military headquarters. The city became the center of a mudiriyya controlling the caravan route between Sennar and Suakin and the Abyssinian border belt.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["French occupation of Muaskar (Mascara): loss of Abd al-Qadir's capital", "bd363c05"], "d": ["With Bugeaud's arrival as governor in 1841, French strategy changed: instead of clinging to the coast, to occupy the interior cities one by one. Mobile columns setting out from Oran, Mostaganem and Médéa took the centers of Abd al-Qadir's regular state; Mascara, a true capital with its mint, gunpowder workshop and granaries, was the most important of them. The emir thereafter gave up establishing a fixed center and turned his army into a nomadic camp called the 'smala.'", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Occupation of the Chelif valley and Tenes: founding of Orléansville", "e1eeeb68"], "d": ["In order to pursue Abd al-Qadir, the French founded in April 1843 a new city named Orléansville in the middle of the Chelif valley; in the same year the coastal port of Tenes was also occupied. Thus the interior corridor between Algiers and Oran came under French control and the resistance in the Dahra mountains was encircled. On 16 May of the same year Abd al-Qadir's nomadic camp, the 'smala,' was found by chance and dispersed.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Founding of the fortified camp of Sidi Bel Abbès", "fb33ec29"], "d": ["On 12 June 1843 Bugeaud ordered General Bedeau to establish a fortified camp with a ditch and walls at Sidi Bel Abbès; construction began on 18 June and in November of the same year a battalion of the Foreign Legion settled there. The camp became a permanent base controlling the interior plain between Oran and Tlemcen.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Passage of Nedroma and the Moroccan border belt to French control", "61d821f3"], "d": ["After Abd al-Qadir withdrew to Morocco in 1843, Nedroma and the Traras coast northwest of Tlemcen came under French control. The Battle of Isly on 14 August 1844 routed the Moroccan army, and the border between the two countries was drawn by the Convention of Lalla Maghnia of 18 March 1845; Nedroma remained on the Algerian side of this line.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Fall of Laghouat: the opening of the gate to the Sahara", "b161b32c"], "d": ["General Pélissier besieged Laghouat with a force of six thousand men on 21 November 1852, and on 4 December the city fell to a bloody assault. Laghouat was the oasis town holding the passage between the Tell and the Sahara; its fall opened the French advance to the desert caravan routes and prepared the way for the Mzab confederation to be bound to taxation within a year.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Annexation of the Bogos (Keren) region to Egypt", "b2ab83ce"], "d": ["Werner Munzinger Pasha, governor of the province of 'Eastern Sudan and the Red Sea Coast' that Khedive Ismail had established on the western shore of the Red Sea, attached in 1872 the Bogos region, inhabited by the Bilen people, with its center Keren, to Egypt. This was Egypt's most lasting advance onto the edge of the Abyssinian plateau and began a border dispute with Abyssinia that lasted twelve years.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Annexation of the Sultanate of Darfur to Egypt: Zubayr Pasha entered El Fasher", "f41268ed"], "d": ["Zubayr Rahma Pasha, who had grown powerful through the ivory and slave trade, scattered the Fur army at Manawashi on 25 October 1874 with forces equipped with Remington rifles; Sultan Ibrahim died in the battle. Zubayr entered El Fasher without a fight on 2 November, and the rule of the Keira dynasty, which had lasted since 1603, effectively ended. Darfur was thus added to the Sudanese provinces of the Egypt of Mehmed Ali; but the resistance of the Keira family in the mountains continued until 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Annexation of the Mzab oases (Ghardaia)", "9372959f"], "d": ["The Ibadi towns of the Mzab had agreed in 1852 to pay tribute to France but had kept their internal administration; thirty years later, in 1882, the region was directly annexed to French territory and Ghardaia was placed under military administration. Thus the last autonomous belt of the northern Sahara also legally came to an end.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Bombardment of Alexandria and the British landing", "18d57bf8"], "d": ["When the officers' movement led by Urabi Pasha brought the khedive under its control, Britain intervened on the pretext of the security of the Suez route. Admiral Seymour's fleet bombarded the coastal batteries of Alexandria on 11-12 July 1882; after the fire and looting in the city, British troops landed on 15 July. The Ottoman State could not prevent this operation in a province over which it was legally sovereign, and it also left unanswered the call to take part in the intervention. Thus the first step of an occupation that would last thirty-two years was taken.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Battle of Tel el-Kebir: dispersal of Urabi's army", "8e38fecf"], "d": ["Wolseley landed his forces at Ismailia via the Suez Canal and, marching through the desert, raided the Egyptian entrenchments at Tel el-Kebir at dawn on 13 September 1882; the battle was over in an hour. Urabi surrendered the next day and the British cavalry entered Cairo the same day. After this date Egypt's financial, military and foreign affairs passed de facto under British control; Ottoman sovereignty, however, continued legally until 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Convention of La Marsa: completion of the Tunisian protectorate", "71338640"], "d": ["The Treaty of Bardo (Qasr al-Said) of 12 May 1881 had left Tunisia's foreign affairs to France but the internal administration to the bey; two years later the Convention of La Marsa, signed on 8 June 1883, also placed financial and administrative reforms under French control and completed the protectorate. The Ottoman State maintained its claim of sovereignty over Tunisia and never recognized the occupation, but could take no actual counter-step. Thus Tunisia, an Ottoman ocak since 1574, formally came under French protection.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Disaster at Shaykan: destruction of Hicks Pasha's army", "a0e08986"], "d": ["Hicks Pasha, a retired British officer who commanded an Egyptian force of about ten thousand men sent from Cairo, was surrounded by the Mahdist forces at Shaykan on 5 November 1883 while advancing in the Kordofan desert without water or guides, and the army was almost completely annihilated. This disaster broke the backbone of Egyptian rule in the Sudan: within a month Darfur and Bahr al-Ghazal surrendered and all of Kordofan passed to the Mahdi. The road to the fall of Khartoum begins here.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Passage of Darfur to the Mahdist forces: surrender of Slatin Pasha", "6d8992d4"], "d": ["The governor-general of Darfur, Slatin Pasha, had since 1882 been dealing with the Mahdist uprising of the Rizeigat tribe; thinking that his soldiers attributed their defeats to his being a Christian, he openly became a Muslim in 1883 and took the name Abd al-Qadir. After the destruction of Hicks Pasha's army in Kordofan in November 1883, resistance lost its meaning, and he surrendered to Emir Madibbo on 23 December 1883. The small Egyptian posts in Darfur soon followed the same course; ten years of Turco-Egyptian administration came to an end.", "85dcfe97"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Passage of Zeila and the Somali coast to British administration", "1d649502"], "d": ["When the Mahdist uprising collapsed Egypt's garrisons in the Sudan and on the Red Sea, Cairo was forced to evacuate its remote posts on the Abyssinian coast. The British administration in Aden landed troops at Zeila and Berbera in 1884; the following year protectorate treaties were signed with the Somali tribal chiefs and British Somaliland was established. Zeila, which had been attached to the province of Habesh since 1559, was thus lost.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Surrender of the El Fasher garrison to the Mahdists", "68f0760d"], "d": ["Even after Slatin's surrender on 23 December 1883, the Egyptian garrison in the fortress of El Fasher continued to resist. The garrison, having lost its wells in a seven-day siege, surrendered on 15 January 1884; the arms were laid down and the fortress passed to the Mahdists.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Hewett (Adwa) Treaty: Bogos ceded to Abyssinia", "0de1b701"], "d": ["When the Mahdist uprising besieged the Egyptian garrisons in the Sudan, Britain, in order to obtain Abyssinia's help, signed a treaty with Yohannes IV at Adwa on 3 June 1884. The second article of the treaty gave Bogos back to Abyssinia, in return for which Abyssinia would facilitate the evacuation of the besieged garrisons via Massawa. Keren thus left twelve years of Egyptian administration; five years later the region would be joined to Italian Eritrea.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Recapture of Dongola: beginning of the Nile campaign", "f63aa14f"], "d": ["After the Italians were defeated at Adwa, Britain marched the Egyptian army south along the Nile under Kitchener's command. As the railway advanced through the desert the supply problem was solved, and the province of Dongola was recaptured on 23 September 1896. Eleven years of Mahdist rule ended here; the campaign would continue for two more years and reach Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Battle of Omdurman: the fall of the Mahdist state", "28dff7b2"], "d": ["Kitchener's Anglo-Egyptian army, equipped with artillery and machine guns, scattered the forces of Khalifa Abdullahi al-Ta'aishi before Omdurman in a few hours on 2 September 1898. Khartoum was entered the next day and the flag was raised at the palace where Gordon had been killed thirteen years earlier. The capital of the Mahdist state fell; the Khalifa was killed at the end of 1899 in a pursuit operation. Actual sovereignty changed hands on this date — 19 January 1899 is the agreement that established the legal framework of the administration.", "ae944d9d"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Condominium Agreement: Anglo-Egyptian joint administration of the Sudan", "8033c688"], "d": ["The agreement signed in Cairo four months after Omdurman placed the Sudan, under the name 'Anglo-Egyptian Sudan,' under the joint administration of the two states: the two flags would be raised together, and the governor-general would be appointed by the khedive with Britain's consent. In practice the administration was entirely in British hands. The Ottoman State, claiming that its rights over the Sudan belonged to it through Egypt, was not a party to the agreement and did not recognize it; but it remained de facto outside.", "c642933f"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Italian landing at Tobruk: first occupation in Tripolitania", "44780018"], "d": ["Italy declared war on 29 September 1911 and its fleet blockaded the coast on 25-26 September. The first land operation was made at Tobruk on 8 October: the small Ottoman garrison withdrew to the interior and the port was occupied without a fight. Tobruk was the Ottoman port closest to the Egyptian border; its fall opened the eastern flank of Cyrenaica and made it easier for Italian forces to march westward along the coast.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Surrender of the city of Tripoli to the Italians", "785091ad"], "d": ["Tripoli surrendered on 9 October 1911 after three days of bombardment. Instead of defending the city, the Ottoman forces chose to withdraw to Aziziya and Gharyan and organize resistance in the interior; this resistance, in which Enver and Mustafa Kemal Beys took part, confined the Italians to the coastal strip until the end of the war. That is, although the city fell, the interior of the province remained under Ottoman control.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Loss of Derna through the Italian landing", "f014c741"], "d": ["After Tobruk it was the turn of Derna, the second port of Cyrenaica; the city was occupied on 16 October 1911. The plateau around Derna was the area where the Sanusiyya order was strongest, and the mujahids gathered by Sheikh Ahmed Sharif's call to jihad kept the Italians besieged around the port. The occupation remained limited to the city and could never spread to its hinterland.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Italian landing at Benghazi: loss of the center of the sancak of Cyrenaica", "f9183c40"], "d": ["Benghazi, the center of Cyrenaica, was occupied on 21 October 1911 in the fourth and most important landing on the coast. Thus, three weeks after the declaration of war, Italy held all the major ports of the province of Tripolitania (Tripoli, Tobruk, Derna, Benghazi); but it could not enter the hinterland of any of them. The remaining year of the war was spent in inconclusive thrusts inland from these four points on the coast.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Italy's unilateral annexation decree", "cfe3f9c2"], "d": ["While the war was going on, Italy issued a decree on 5 November 1911 and declared that it had annexed Tripolitania and Cyrenaica. The Ottoman State did not recognize this and the war continued for another year; the annexation gained legal validity only with the Treaty of Ouchy of 18 October 1912. For this reason the decree does not change the Ottoman color on the map — legal ownership remains with the Ottomans until 1912, and Italian control is shown as a hatched occupation.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Capture of Köprühisar and preparation for the foundation of Yenişehir", "39abff03"], "d": ["By bringing down the pass fortresses between Bursa and Iznik, the foundation was laid of the forward headquarters that would place the two cities under encirclement.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Foundation of Yenişehir", "d3275837"], "d": ["The first regular Ottoman garrison settlement was established to conduct the sieges of Bursa and Iznik; Orhan Gazi was born here.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["First siege of Iznik and conquest of Marmaracık", "cdca2349"], "d": ["Iznik was besieged for the first time but could not be brought down (the definitive conquest being in 1331); the nearby fortress of Marmaracık was taken at this time.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Anatolian expedition of the Catalan units", "4fd940d5"], "d": ["The Catalan company hired by Byzantium to halt the Turkish advance won temporary successes but could not endure; with their withdrawal the advance of the frontier principalities accelerated.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal converts to Islam and joins the Ottomans", "ca0d86e1"], "d": ["Köse Mihal, the tekfur of Harmankaya, converted to Islam and joined Osman Gazi together with his fortress and his men; he became the first Byzantine-born Ottoman commander.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey takes over the de facto administration", "6dadbefc"], "d": ["Because of Osman Gazi's old age and illness, the de facto command and administration of the siege of Bursa and of the campaigns passed to his son Orhan Bey (his formal accession to the throne is in 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-01-01:0":{"b": ["Blockade of the harbour of Mudanya", "9aa4520c"], "d": ["By cutting off the harbour that fed Bursa from the sea, the last act of the long siege was opened.", "97d6f814"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Capture of Mudanya", "0a623368"], "d": ["With the capture of Mudanya, the harbour of Bursa, the city's connection with the sea was cut; the siege of Bursa entered the stage of strangulation.", "c13020d5"]},
"OLAYLAR_EK:1323-01-01:0":{"b": ["Annexation of Yalova and Karamürsel", "133cb07a"], "d": ["The harbour towns on the southern shore of the gulf were seized in order to complete the siege of Bursa.", "6588050d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquest of Akyazı and the Island of İmralı", "d041b0c8"], "d": ["Akyazı, north of the Sakarya, was taken; with the seizure of the Island of İmralı the Ottomans became for the first time neighbours of Marmara Island.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquest of Gemlik (Kios) and Armutlu", "682d3bac"], "d": ["With Bursa's last sea connection also cut, the city was made ready for the surrender of 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca seized Kandıra and its surroundings", "341bb97e"], "d": ["Akça Koca, one of the frontier lords of Orhan Gazi, while raiding the region of Izmit from his headquarters west of Lake Sapanca, seized Kandıra and its surroundings towards 1326. Izmit was still in Byzantine hands; the city would fall only in 1337.", "ed042ad1"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca took Aydos and the fort of Samandıra", "ce4daa8a"], "d": ["After the capture of Kandıra, Akça Koca, together with Konuralp and Gazi Abdurrahman, took the fortress of Aydos near Kartal, and then the fort of Samandıra to its north; the region of Samandıra was given to him as property. Akça Koca died near Kandıra in 1328; the frontier lordship of the region was given to Prince Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Ottoman-Aydın-Saruhan alliance", "9df6bb74"], "d": ["The three principalities acted jointly against Byzantium; the fleet of Umur Bey of the Aydınids wore down Byzantium on a second front with its raids on the coasts of Thrace.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Marriage of Orhan Gazi and Theodora: the Byzantine alliance", "9b67a590"], "d": ["Orhan Gazi, who supported Kantakouzenos in the Byzantine struggle for the throne, married his daughter Theodora; this alliance enabled the Ottoman forces to become closely acquainted with Rumelia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Capture of Ankara", "49bf1f6d"], "d": ["Ankara, under Ahi rule, came under Ottoman administration; the road to Central Anatolia was opened. Other places annexed on the same date: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Advance in Thrace in the time of Süleyman Pasha: Malkara, İpsala and Tekirdağ", "fb31cf02"], "d": ["After a bridgehead was established at Gallipoli, Süleyman Pasha moved north out of the peninsula and took the plain between the Marmara coast and the mouth of the Maritsa step by step. Malkara, İpsala and Rodosçuk (Tekirdağ) thus formed an uninterrupted corridor linking Gallipoli and the Maritsa valley. It was not possible to march on Edirne without this corridor; the advance, halted by the prince's sudden death in 1357, would be continued by Lala Şahin and Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Abduction of Prince Halil", "b52ac3d7"], "d": ["Halil, the younger son of Orhan Gazi, was abducted by pirates of Phocaea (Foça); the ransom crisis occupied Ottoman-Byzantine relations for years.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Cutting of Edirne's relief routes: the fortresses of Çorlu, Lüleburgaz, Babaeski and Keşan", "8e8ad485"], "d": ["Prince Murad, who resumed the campaign of conquest after the rescue of Halil, sent the raiders (akıncı) as far as the approaches to Constantinople in order to isolate Edirne from help that might come from outside. The fortresses of Çorlu, Lüleburgaz and Babaeski on the Constantinople-Edirne road, and Keşan at the road junction of Southern Thrace, were seized. The surrender of Edirne came after this ring of siege had been completed.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Capture of Dimetoka — opening of the Maritsa valley", "b59aee83"], "d": ["Dimetoka (Didymoteicho), the key fortress of the Maritsa valley, was taken; the road to the conquest of Edirne was thus opened. It was not possible to march on Edirne before the corridor extending north from Gallipoli had been completed; for this reason the fortress comes before Edirne in the sequence of the Rumelian conquests. The city became for a time the Rumelian headquarters of the sultans. The forces that took Dimetoka then brought the whole of the Middle Maritsa region under control together with small fortresses such as Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Loss of Gallipoli (Savoyard Crusade)", "00e7e415"], "d": ["The fleet of Amadeus of Savoy, cousin of the Byzantine emperor, took Gallipoli and handed it over to Byzantium; the Ottoman bridgehead in Rumelia was for ten years governed from across the strait. Other settlements lost on the same date: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Battle of Çirmen — control of the Maritsa valley", "cd738d8d"], "d": ["The army of the Serbian lords was scattered in a night attack; the local Serbian and Bulgarian lords in Macedonia and the Rhodopes began, one by one, to pay tribute to the Ottomans — the beginning not of a direct conquest but of a wave of vassalization. In the Ottoman tradition this battle is also recounted under the name 'Sırpsındığı' and in the year 1364, as the night attack of Hacı İlbey on the Crusader army that had come to retake Edirne; the TDV states that this date is wrong and that the two accounts belong to the same battle.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquest of Filibe and Stara Zagora", "e780c9ae"], "d": ["Filibe, upstream on the Maritsa valley, and Stara Zagora (Eski Zağra) to its north were taken; the Bulgarian tsardom was subjected to tribute. The route of Tatarpazarcığı and İhtiman between Filibe and Sofia remained in the hands of the local lords who became vassals after Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Vassal Byzantium: John V in the army of Murad I (consequence of the 1371 victory of Çirmen)", "13ffe568"], "d": ["According to the TDV, after the victory of Çirmen (Maritsa) on 26 September 1371, the Byzantine Empire had recognized Ottoman dominion and, by accepting to pay tribute and to serve in the Ottoman army, had fallen into the position of a vassal state. Emperor John V, with this obligation, joined the army of Murad I in 1373; his son Andronikos IV, whom he had left behind in Constantinople at that time, rebelled against their fathers together with Prince Savcı Bey in Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Recovery of Gallipoli", "5f96c0a5"], "d": ["Andronikos IV, who obtained Ottoman support in the Byzantine struggle for the throne, returned Gallipoli in exchange; the bridge between Rumelia and Anatolia was established anew. Other places annexed on the same date: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["The Germiyan dowry: annexation of Kütahya", "d6a6fe61"], "d": ["On the marriage of Devletşah Hatun, daughter of Süleyman Shah of the Germiyanids, to Bayezid the Thunderbolt, Kütahya, Simav, Tavşanlı and Eğrigöz passed to the Ottomans as a dowry — the classic example of expansion without war. Other places annexed on the same date: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Purchase of the Hamid province: annexation of Isparta", "4a1b6047"], "d": ["Hüseyin Bey of the Hamidids sold part of his principality (Akşehir-Beyşehir-Isparta) to Murad I for cash; the remainder of the Hamid province would be annexed by the Thunderbolt in 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquest of Serres", "d4d28b60"], "d": ["Serres, the key to Eastern Macedonia, was taken; Thessaloniki came within the ring of siege. The Köstendil-Petriç-Nevrokop-Drama line between Sofia and Serres had not yet been directly annexed at this date; it passed successively to vassal status in the 1370s–1383 and to direct administration after 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquest of Sofia", "96d5f01f"], "d": ["The western passes of the Balkan mountains were brought under control; since at this date Serres had already been held since 1383, the lands of Thrace and Macedonia formed an uninterrupted whole.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquest of Niš", "77f5d632"], "d": ["With the capture of Niš, the lock of the Morava valley, the Serbian despotate came under direct threat.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["First surrender of Thessaloniki", "96010ee9"], "d": ["After a long blockade the city surrendered (it would be given back to Byzantium in 1403 and definitively conquered in 1430). Other places annexed on the same date: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ottoman-Genoese ahidname — renewal of the 1352 treaty", "be11d17a"], "d": ["With Genoese envoys from Pera, the 1352 commercial agreement dating from the time of Orhan Gazi was renewed; taxes between the two states, the treatment of captives and free trade were fixed anew. This is regarded as the first officially known ahidname of friendship and trade between the Ottomans and the Genoese — not a military alliance but an entirely commercial agreement.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Çandarlı Ali Pasha's Bulgarian campaign: capture of Şumnu and Rusçuk", "2781c3a9"], "d": ["The fortresses of the Bulgarian Tsardom along the Danube were taken over in a single campaign; it should not be confused with the defeat suffered at Bileća in Bosnia in the same year — that was a simultaneous success on a separate front. Tırnova and Vidin were the last Bulgarian centres still held.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Defeat at Bileća", "89ba0a64"], "d": ["The raiding force that advanced on Bosnia was ambushed and destroyed at Bileća; this first great Balkan setback encouraged the alliance that led to Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annexation of the western Anatolian principalities: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Three principalities were annexed in a single campaign: the centre of the Saruhanids, Manisa; the centre of the Aydınids, Aydın (including the upper fortress of Izmir, but the harbour/lower fortress still with the Knights of St. John — until 1402); the centre of the Menteşeids, Muğla-Milas, including the coastal strip of Datça-Bodrum-Marmaris-Fethiye. The Aegean coasts were united in a single hand for the first time. Other places annexed on the same date: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1391-10-01:0":{"b": ["First blockade of Constantinople began", "4441a9e7"], "d": ["Bayezid the Thunderbolt kept Constantinople under blockade, with intervals, for ten years; the city was saved only thanks to the approach of Timur.", "504fcb33"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annexation of the Teke province: annexation of Antalya", "fdbeee5c"], "d": ["The Teke province on the Mediterranean coast was annexed to Ottoman lands. The Tekeids are a branch separated from the Hamidids: Feleküddin Dündar Bey had left Antalya, which he had conquered, to his brother Yûnus Bey, and around 1321 a separate principality had arisen. For this reason Antalya and its surroundings are shown on the map after 1321 not in the colour of the Hamidids but in that of the Tekeids. The principality was re-established after the Battle of Ankara and was definitively liquidated only in 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquest of Skopje", "9e5a1af5"], "d": ["The centre of Vardar Macedonia was taken; Skopje became one of the principal frontier centres of Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annexation of Kastamonu", "876330ba"], "d": ["The Kastamonu branch of the Candarids was liquidated; the Sinop branch continued as a vassal. Other places annexed on the same date: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Fall of Tırnova — annexation of Bulgaria", "ff666977"], "d": ["The capital of the Bulgarian tsardom fell; Bulgaria came under direct Ottoman administration. Other places annexed on the same date: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Fortress of Lofça (Lovech) passed to the Ottomans", "a55e87a0"], "d": ["Lofça, one of the fortresses of the Bulgarian tsar Ivan Shishman, was annexed to Ottoman lands together with Shishman's other provinces in the campaign of 1393 in which Tırnova fell. The source does not speak definitively: it is 'thought' that the conquest was in this year.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Annexation of Dobruja", "478e36f2"], "d": ["The lands of Dobruja extending to the Danube delta were annexed. Other places annexed on the same date: Silistra, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Descent into Thessaly", "8bec60dd"], "d": ["The plain of Thessaly, centred on Yenişehir (Larissa), was taken under Ottoman administration. Other places annexed on the same date: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquest of Nicopolis", "b9791717"], "d": ["After the battle of Rovine in 1395 against the Wallachians, Bayezid the Thunderbolt took the fortress of Nicopolis on the bank of the Danube; some anonymous Bulgarian chronicles state that the conquest took place on 3 June 1395. The date of the conquest is not uniform in the sources: the entry on the Battle of Nicopolis in the TDV İslâm Ansiklopedisi writes that Bayezid took Silistra and Nicopolis in a Danube campaign in 1394. The fortress would be besieged in the famous Crusade of 1396, but would not fall. Other places annexed on the same date: Ohrid.", "bc450a9f"]},
"OLAYLAR_EK:1395-05-17:0":{"b": ["Battle of Rovine — the Wallachian campaign", "343ae7a9"], "d": ["After the bloody battle fought with Mircea, voivode of Wallachia, whose result is disputed, Wallachia accepted to pay tribute to the Ottomans; the order of vassalage north of the Danube was established.", "dd69200f"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Construction of Anadolu Hisarı", "aa259b00"], "d": ["To support the blockade of Constantinople, Güzelcehisar (Anadolu Hisarı) was built on the Anatolian side of the Bosphorus — the first permanent step in the control of the strait.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annexation of Vidin", "ee1ae44b"], "d": ["After the victory of Nicopolis, Vidin, the last Bulgarian principality, was also annexed.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["First annexation of Karaman", "3cf07876"], "d": ["With the victory of Akçay, the lands of the Karamanids were annexed to the Ottomans for the first time (they would be re-established during the Interregnum).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Annexation of the Canik coasts: Samsun", "af9c40fa"], "d": ["In the vacuum created by the capture of Kadı Burhâneddin by the Aqquyunlu Karayülük Osman Bey, Bayezid the Thunderbolt first attached the Canik region on the Black Sea coast to Ottoman administration. Samsun and its surroundings thus became the dynasty's first Black Sea port. The Sivas-Tokat-Kayseri line in the interior would be annexed two weeks later, with the effective dissolution of the State of Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Capture of Malatya", "7cb6ae16"], "d": ["Malatya on the Mamluk frontier was seized — one of the steps that heightened tension with Timur.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur took Malatya and left it to Karayülük Osman — when Timur withdrew, the Dulkadirids retook it", "ad2ce7d8"], "d": ["Bayezid the Thunderbolt had returned to Bursa, leaving Malatya, which he had taken in 1399, to Nasreddin Mehmed of the Dulkadirids. Timur, who entered Anatolia in 1400, took first Sivas and Elbistan, then Malatya; the city and its surroundings were plundered and its administration was left to Karayülük Osman, who was with Timur. When Timur left the region, the Dulkadirids again came to dominate Malatya; Ottoman dominion thus ended before Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Süleyman Çelebi – Byzantine treaty: return of Thessaloniki", "cc503cc2"], "d": ["Süleyman Çelebi, who ruled Rumelia during the Interregnum, by agreement with Byzantium and the Latin states ceded Thessaloniki and the Black Sea coasts as far as Mesembria to Byzantium (TDV fetret-devri: Treaty of Gallipoli, February 1403) — on the map İğneada, Rezve and Ahtapolu pass to Byzantium; on the map Thessaloniki leaves the Ottomans at this date.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Naval defeat at Gallipoli (Venice)", "b71d4d68"], "d": ["The Venetian fleet inflicted a heavy defeat on the Ottoman fleet before Gallipoli; the event showed the limits of early Ottoman seafaring.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Uprising of Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, who claimed to be a son of the Thunderbolt, proclaimed a sultanate in Rumelia with Byzantine support; Murad II suppressed the uprising in 1422 and had his rival executed.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Siege of Constantinople by Murad II", "4b9d9fba"], "d": ["In response to Byzantium's support of Düzmece Mustafa, Murad II besieged Constantinople; the siege was lifted when his brother Küçük Mustafa was incited to rebel in Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Transfer of Thessaloniki to Venice", "bfa6c4a0"], "d": ["The Byzantine governor, under Ottoman pressure, transferred the city to Venice; the Ottoman-Venetian contest that would last seven years began.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Renewed annexation of the western Anatolian principalities: Menteşe and Aydın", "aca30a48"], "d": ["The two Aegean principalities re-established during the Interregnum were definitively annexed to Ottoman lands in the time of Murad II. According to the TDV entry on the Menteşeids, Murad II took the Menteşe province in 827 (1424) and had the two brothers at the head of the principality imprisoned. According to the entry on the Aydınids, Hamza Bey, the Beylerbeyi of Anatolia, had Cüneyd Bey, who had again withdrawn his obedience, seized and executed together with his family (829/1425-26), and the Aydın province passed to the Ottomans. The Knights of St. John, who had held the harbour fortress of Izmir since 1344, had lost it to Timur in 1402, and the region had returned to Aydınid control; with this annexation it too was joined to the Ottomans. The Teke province (Antalya) is not the subject of this entry: the Tekeids had been liquidated separately in 1423. Germiyan, on the other hand, would be annexed by testament in 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Annexation of Germiyan by testament", "9eb86b77"], "d": ["Yakub II, bey of Germiyan, who died childless, left his country to the Ottomans by testament — the textbook example of annexation without war. Other places annexed on the same date: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Definitive conquest of Thessaloniki", "bc021768"], "d": ["The city, under Venetian rule, was taken by assault; the second great port of Rumelia definitively became Ottoman. Other places annexed on the same date: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Surrender of Ioannina", "ee45cb52"], "d": ["Ioannina, the centre of Epirus, surrendered by treaty.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["First capture of Smederevo", "c11ca17d"], "d": ["With a three-month siege the capital of the Serbian despotate was taken and Serbia was annexed for the first time (it would be returned by the Treaty of Edirne-Szeged in 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Siege of Belgrade (unsuccessful)", "3e05f425"], "d": ["The first great siege of Belgrade, lasting six months, produced no result; the fortress remained for eighty years a lock before the Ottoman advance.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Rout at Zlatica — the 'Long Campaign'", "97df1466"], "d": ["The army that Hunyadi led into the Balkans in midwinter passed Niš and Sofia and pressed up to Zlatica; the Ottoman defence held with difficulty. This atmosphere of rout brought the Peace of Edirne-Szeged to the table.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Treaty of Edirne-Szeged", "0aa4e0de"], "d": ["A ten-year peace: the Serbian despotate was restored and the Danube was accepted as the border. The breaking of the treaty within months at the instigation of the papacy led to the disaster of Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Return of Smederevo and the Serbian fortresses to Serbia", "cda3cf9e"], "d": ["The provision of the Treaty of Edirne-Szeged was put into effect: on 15 August 1444 Murad II gave Smederevo back to Đurađ Branković together with its twenty-four important fortresses and the other Serbian lands under occupation (TDV semendire); Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) and Priština (TDV pristine) were also left to the Serbs. Vidin, not being Serbian land, did not enter the return — this is the source of the northwestern loss of territory seen on the map around the victory of Varna; a few months later, with the rout of Varna, the treaty would in any case become void.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisarı completed — the 'Strait-Cutter' (Boğazkesen)", "480e8a76"], "d": ["With the fortress completed, according to the sources, in an extraordinarily swift construction lasting four to five months, control of the Bosphorus passed entirely to the Ottomans; the route of aid from the Black Sea to Constantinople was closed. It is regarded as the de facto first step of the siege.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Siege of Constantinople began", "8af50742"], "d": ["The army took up position before the walls; in the siege that would last 54 days, giant cannon were used for the first time systematically against the walls of a capital.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Ships lowered overland into the Golden Horn", "4f2ba07c"], "d": ["About 70 ships of the fleet, which could not enter the Golden Horn closed by a chain, were hauled over the ridges of Galata on greased slipways and lowered into the Golden Horn in a single night; the defence was divided into two fronts.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquest of Athens", "4f0f1bb2"], "d": ["The Duchy of Athens came to an end; the Ottoman banner was raised on the Acropolis. Other places annexed on the same date: İstefe (Thebes), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annexation of Serbia (fall of Smederevo)", "75fd0a62"], "d": ["Smederevo, the capital of the Serbian despotate, surrendered; Serbia became an Ottoman sancak.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquest of the Morea", "7d5a3c18"], "d": ["The despotate of the Morea was liquidated; the peninsula (except the Venetian fortresses) came under Ottoman administration.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Annexation of Sinop", "e03c2739"], "d": ["The Candarid surrendered Sinop without war; the way to the Trebizond campaign was opened. Other places annexed on the same date: Kastamonu, Bartın, Safranbolu.", "4fa22834"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Fall of the Kingdom of Bosnia — the Conqueror's Bosnian campaign", "5362e3f2"], "d": ["When the last Bosnian king, Stjepan Tomašević (1461-1463), relying on Western support, refused to pay tribute, he was deemed to have ceased to be a vassal ruler, and the army under the Conqueror, Sultan Mehmed, liquidated the Kingdom of Bosnia in a single campaign. The king was captured and executed, the kingdom disappeared and the sancak of Bosnia was established in the region. But the fall of the kingdom is not the same thing as the conquest of Bosnia. Ottoman administration had already existed in the plain for fifteen years — Hodidjed and the plain of Saray had been taken in 1448, and the frontier lordship of Îsâ Bey had been established in the middle of the kingdom. The conquest did not end in 1463 either: Foča was taken in 1465, Livno in 1469, the Duchy of Herzegovina in 1483, the banate of Srebrenik in 1512, and Jajce and Banja Luka in the north only in 1528 after Mohács — the Hungarians had established a banate in northern Bosnia that held out for sixty-five years after 1463. The place that changed hands directly on this date is Travnik; Jajce passed on this date not to the Ottomans but to Hungary.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Definitive annexation of Karaman", "f1dcecaa"], "d": ["The core lands of the Karamanids were definitively annexed; internal strife continued until the 1470s. Other places annexed on the same date: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquest of Negroponte", "5c97daf3"], "d": ["Negroponte (Eğriboz), Venice's main base in the Aegean, fell.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annexation of Alanya, Anamur and Silifke (İçel)", "a0b9d461"], "d": ["The İçel coastal strip dependent on the Karamanids (the whole of the Mediterranean between Antalya and Mersin) was annexed by the naval campaign of Gedik Ahmed Pasha; Alanya was important with its strategic shipyard dating from the Seljuk period.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Treaty of Istanbul — Albania and Shkodër", "b09652f7"], "d": ["The 16-year Ottoman-Venetian war ended; Shkodër and the Albanian coasts remained with the Ottomans. Other places annexed on the same date: Lemnos, Samos, Bozbaba (Agios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Landing at Otranto", "7916b89d"], "d": ["Ottoman forces landing on the Calabrian coast besieged and took the fortress of Otranto; since the city was entered by fighting, some of the notables who resisted were executed and some were taken captive. The church tradition commemorates the dead as the roughly 800 'Martyrs of Otranto'; the TDV attributes the exaggeration of this number to church propaganda. Only the fortress at the tip of the Salento peninsula and its narrow surroundings were held; the remaining lands of the Kingdom of Naples along the Taranto-Brindisi-Lecce line were not lost — this bridgehead opened to Italy would last one year.", "f60d286a"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuation of Otranto", "37371bb0"], "d": ["The garrison of Otranto, with no hope of fresh reinforcement upon the death of Mehmed the Conqueror (3 May 1481), evacuated the fortress by agreement in the face of the siege of Alfonso, heir of Naples; the only Ottoman bridgehead in Italy was thus lost after one year.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquest of Modon and Koron", "38b608c4"], "d": ["Modon and Koron, the 'two eyes' of Venice in the Morea, were taken.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquest of Durrës", "1f231b98"], "d": ["During the Ottoman-Venetian war of 1499-1503, forces under the command of Mehmed Bey took Durrës (Draç), Venice's last great Albanian port on the Adriatic. After Shkodër (1479) and Vlorë (1417), with this conquest the Albanian coastal strip came entirely under Ottoman control.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Annexation of Eastern Anatolia", "e0cb8f8f"], "d": ["After Chaldiran, Diyarbakır and its surroundings were annexed; the Kurdish principalities were attached to the Ottomans through the agency of İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquest of the Fortress of Varadin (Petrovaradin)", "abf392a5"], "d": ["The army setting out on the Mohács campaign crossed from Belgrade into Hungarian lands; first the outer quarters of Varadin were taken, and after a fourteen-day siege the fortress too fell. The Lawgiver ordered that the villages on the road not be burned, because these were now regarded as Ottoman land.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Surrender of Buda after Mohács — two kings for the Hungarian throne", "9d3568a0"], "d": ["The keys of the city were presented to the sultan on 11 September 1526 by the Ottoman army marching on Buda after the victory of Mohács; however, the Lawgiver did not hold Buda and withdrew his army. In Hungary, left without a king, the nobles elected two separate kings: János Szapolyai on 10 November 1526, and the Habsburg Ferdinand I on 17 December 1526. Ferdinand took Buda in August 1527. Szapolyai's settling in Buda as a king under Ottoman protection would come with the campaign of 1529 (see the 1529 entry), and direct Ottoman administration would be established in 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai elected king of Hungary — the Ottomans recognized his kingdom on condition of his being a vassal", "32bc6baf"], "d": ["To the Hungarian throne left vacant by the death of the king at Mohács, part of the nobles elected János Szapolyai, voivode of Transylvania; Szapolyai was crowned at Székesfehérvár. The Ottomans, who had evacuated Buda, recognized Szapolyai's kingdom on condition that it be subordinate to themselves, in order to keep the region as a buffer. On the map, places dependent on Szapolyai appear as subordinate to the Ottomans from this date.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I proclaimed king of Hungary — western and northern Hungary under the Habsburg crown", "b3910a2f"], "d": ["The Habsburg Archduke Ferdinand, basing himself on his sister's marriage to Louis II, claimed the Hungarian throne and was proclaimed king by a portion of the nobles. Hungary was thus divided between two kings; its western and northern parts recognized Ferdinand. The Croatian nobles elected him separately in early 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Contest of the two kings: Esztergom under Habsburg protection, Szeged with Szapolyai", "da92dee5"], "d": ["Esztergom, which had changed hands between the two kings since 1526, came under Habsburg protection after the archbishop moved north with his archive and treasury. From the same year until 1541, Szeged remained under the sovereignty of Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["The people of Pécs went over to Szapolyai's side", "3fc4e7f2"], "d": ["Pécs, which had received a privilege from Ferdinand in 1528, shortly afterwards went over to Szapolyai's side; King János stayed in the city for a time in 1533. With the fall of Buda in 1541, the city returned again to Ferdinand's side.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquest of Tripoli", "8c659986"], "d": ["Tripoli was taken from the Knights of St. John; the central coast of North Africa became Ottoman. Other places annexed on the same date: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquest of Temesvár", "e9fd4995"], "d": ["The Banat region was taken and the Beylerbeylik of Temesvár was established.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Definitive conquest of Tunis", "7bbd11bc"], "d": ["Tunis, under Spanish-Hafsid control, definitively came under Ottoman administration; the North African line was completed. Other places annexed on the same date: Kairouan, Gabès, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquest of Kanije", "0c7b6aa3"], "d": ["Kanije was taken in the Long War; the following year Tiryâki Hasan Pasha's defence became an epic.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["The Uyvar campaign began — Fâzıl Ahmed Pasha marched from Edirne against Austria", "306a86db"], "d": ["After Austria attacked Transylvania and took the fortresses of Székelyhíd and Kolozsvár, Istanbul decided on a campaign against the Habsburgs. Grand Vizier Köprülüzâde Fâzıl Ahmed Pasha set out from Edirne on 13 April 1663. At Belgrade an Austrian request for peace arrived, but in the two meetings at Osijek the Ottoman terms were rejected. At the council in Buda the objective was also set as Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquest of Uyvar", "ce289470"], "d": ["Uyvar (Nové Zámky), the key fortress of northern Hungary, was taken; the expression 'as strong as a Turk before Uyvar' passed into European languages. After Uyvar, Nitra and Léva also surrendered after brief resistance; De Souches retook both in the spring of 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Recovery of the Morea", "9b6460f1"], "d": ["The Morea, which had been left to Venice at Karlowitz, was recovered in a single campaign. Other places annexed on the same date: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Second loss of Belgrade — siege by Prince Eugene", "6a194354"], "d": ["After the rout at Varadin and the loss of Temesvár, Prince Eugene besieged Belgrade; when the relief army that came to rescue the city was also routed, the fortress surrendered. The city, which had been recovered in 1690 after Karlowitz, was thus lost again and the Danube line of defence collapsed. Belgrade could be recovered only twenty-two years later, with the Treaty of Belgrade in 1739. Other settlements lost on the same date: Smederevo.", "3bf3f600"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Fall of Özi", "90a67a6c"], "d": ["Özi (Ochakov), the key fortress north of the Black Sea, passed into Russian hands in a bloody assault; the population of the city was put to the sword.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Treaty of Bucharest — loss of Bessarabia", "932da4d6"], "d": ["With the treaty ending the Russian war of 1806-1812, the area east of the Prut (Bessarabia) was ceded to Russia. Other settlements lost on the same date: Akkerman, Kiliya, Khotyn, Bender, Izmail.", "a4c3a1fb"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Treaty of Edirne", "b3a8fe4c"], "d": ["At the end of the war in which the Russian army entered Edirne, the Danube delta was lost; the autonomy/independence of Greece was effectively accepted. Other settlements lost on the same date: Brăila, Anapa, Akhaltsikhe. Although the treaty returned the land, it did not end the occupation at once: Wallachia-Moldavia and Silistra remained under Russian administration as a pledge until the war indemnity was paid — this is why these places appear on the map as under occupation after 1829 as well.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Edict of autonomy for Serbia — hereditary knezship and the garrison condition", "6a5d901d"], "d": ["The hatt-ı hümâyun issued in accordance with the provision of the Treaty of Edirne concerning Serbia recognized Miloš Obrenović as hereditary knez and made Serbia an autonomous principality free in its internal affairs and dependent on the Ottomans externally. The provisions: the knezship would pass from father to son, a fixed annual tax would be paid, the Serbian assembly would establish its own internal administration, the church would be autonomous; in return, Ottoman garrisons would remain in the fortresses of Belgrade, Smederevo, Šabac, Soko and Ušće (Fethülislâm). This dual structure lasted until the withdrawal of the garrisons in 1867. On the map the city of Belgrade is joined to autonomous Serbia at this date; the fortress of Kalemegdan is shown with an Ottoman garrison until 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cyprus left to British administration", "423da3ee"], "d": ["In return for an alliance against the Russian threat, the administration of Cyprus was transferred to Britain; legally it remained Ottoman land. Other settlements lost on the same date: Nicosia (Lefkoşa), Famagusta (Magosa).", "04ce99ee"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cession of Thessaly to Greece", "ac614d24"], "d": ["In accordance with the decisions of the Congress of Berlin, Thessaly and the surroundings of Arta were ceded to Greece. Other settlements lost on the same date: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia).", "850edaa2"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Union of Eastern Rumelia with Bulgaria", "ee43f137"], "d": ["The autonomous province of Eastern Rumelia was joined to Bulgaria by a coup; the Sublime Porte accepted the fait accompli.", "41e57063"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Battle of Domokos", "9c6f29a5"], "d": ["In the Ottoman-Greek War of 1897 the army won a decisive victory at Domokos; territorial gain remained limited owing to diplomatic pressure.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomy for Crete", "2e764881"], "d": ["Although the Ottoman-Greek War ended in an Ottoman victory, Britain, Russia, France and Italy proclaimed the autonomy of Crete on 18 December 1897; the island was to be a neutral and autonomous province under Ottoman dominion. After 6 November 1898 the Turkish flag was no longer raised at Candia and Kisamos; with Prince George, son of the Greek king, taking up his post as extraordinary commissioner on 22 December 1898, Crete effectively left Ottoman administration (formally it separated in 1913). Other settlements lost on the same date: Candia (Crete), Chania (Hanya).", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Independence of Bulgaria and annexation of Bosnia", "393feaa4"], "d": ["In the confusion of the constitutional revolution, Bulgaria declared independence and Austria-Hungary annexed Bosnia-Herzegovina.", "6b7e2450"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Recovery of Edirne", "536e5599"], "d": ["In the Second Balkan War the army crossed the Maritsa and recovered Edirne without a fight. Other places annexed on the same date: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Victory of Kut al-Amara", "98b972bc"], "d": ["The commander of the British division besieged at Kut surrendered with his 13,000 soldiers — one of the greatest Ottoman victories of the First World War.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Loss of Baghdad", "2c18a816"], "d": ["The 383-year Ottoman Baghdad passed to the British army. Other settlements lost on the same date: Karbala.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Loss of Jerusalem", "94067617"], "d": ["The 401-year Ottoman Jerusalem was surrendered without being defended.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Loss of Damascus", "ed177b68"], "d": ["With the collapse of the Palestine front, Damascus was evacuated; four centuries of Ottoman rule in Syria came to an end. Other settlements lost on the same date: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Surrender of Medina", "76b505f6"], "d": ["Seventy-two days after the armistice, the resistance of Fahreddin Pasha, the 'Desert Tiger', came to an end by the sultan's will; the last Ottoman unit in the Hejaz laid down its arms.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Occupation of Izmir", "e32e5e77"], "d": ["The Greek army landed at Izmir; the resistance that began with the first bullet lit the fuse of the National Struggle. Aydın, on the other hand, was occupied on 27 May 1919 (a separate entry).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Formal occupation of Istanbul", "a8e98ada"], "d": ["The Entente forces formally occupied Istanbul and the Meclis-i Meb'ûsan was dissolved; the deputies made their way to Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Treaty of Kars", "bb32d4e0"], "d": ["Between the Grand National Assembly and the Caucasian republics, the eastern border was drawn in its present form.", "fe736259"]},
"OLAYLAR_FRANSA_KONTROL_1027:1284-01-01:0":{"b": ["The County of Champagne was attached to the French crown through the marriage of Joan I to Philip IV: Troyes (together with Meaux)", "cae2654d"], "d": ["Through the marriage (1284) of Joan I, countess of Champagne and queen of Navarre, to Philip (IV), heir to France, Troyes, the capital of Champagne, was joined to the crown lands; for Meaux, Treccani says in the same year (1284) 'it passed to the king of France'. The official annexation of the county is in 1314 with the accession of Louis X (künye t).", "03072856"]},
"OLAYLAR_FRANSA_KONTROL_1027:1305-01-01:0":{"b": ["The count of Flanders ceded Walloon Flanders (Lille, Douai, Béthune) to King Philip IV of France: Lille", "a4746f27"], "d": ["The 'French' (Walloon) part of the County of Flanders — the castellanies of Douai, Béthune and Lille — was given to the king of France in 1305 (definitive transfer 1320); in 1369 the dukes of Burgundy took it by marriage.", "fa06bb72"]},
"OLAYLAR_FRANSA_KONTROL_1027:1312-01-01:0":{"b": ["The supremacy of the king of France was established at Lyon: Philip IV (the Fair) took Lyon, an imperial fief, by the Treaty of Vienne", "60ea68d8"], "d": ["In Lyon, which had been a fief of the German emperor since 1032 and whose actual power was shared between the archbishop and the counts of Forez, the supremacy of King Philip IV of France was established in 1312; from this date the city is regarded as French.", "74a8638d"]},
"OLAYLAR_FRANSA_KONTROL_1027:1314-11-29:0":{"b": ["Philip IV died; Louis X (the Quarrelsome) became king of France", "10fd76ef"], "d": ["Philip IV died on 29 November 1314; his son Louis X came to the French throne (he had already been king of Navarre since 1305).", "3aa6f8e3"]},
"OLAYLAR_FRANSA_KONTROL_1027:1317-01-09:0":{"b": ["Philip V was crowned at Reims (as regent after the death of Louis X, he had proclaimed himself king upon the death of his nephew John I)", "3b50d3fc"], "d": ["Louis X died on 5 July 1316; the regent Philip V proclaimed himself king after the posthumous son John I, who died 4 days after his birth, and was crowned at Reims on 9 January 1317. The day of the proclamation is not in the source; the atlas takes the day of the coronation.", "5e0b5084"]},
"OLAYLAR_FRANSA_KONTROL_1027:1322-01-03:0":{"b": ["Philip V died; Charles IV became king of France", "a0b9abda"], "d": ["Philip V died at Longchamp during the night of 2 January 1322; his brother Charles IV came to the throne.", "a4efde24"]},
"OLAYLAR_FRANSA_KONTROL_1027:1328-05-29:0":{"b": ["Philip VI (Valois) was crowned at Reims: the Valois dynasty began", "a9595d82"], "d": ["When Charles IV died in February 1328 without a male heir, Philip of Valois became regent; he was crowned at Reims on 29 May 1328 and began the Valois dynasty. The claim of King Edward III of England through his mother is one of the sparks of the Hundred Years' War.", "aca69718"]},
"OLAYLAR_FRANSA_KONTROL_1027:1348-06-09:0":{"b": ["Queen Joanna of Naples sold Avignon to Pope Clement VI", "ecd3d028"], "d": ["As countess of Provence, Queen Joanna of Naples sold the city of Avignon to Pope Clement VI for 80,000 florins on 9 June 1348; the city remained a papal exclave until 1791. The settlement record carried this border; the entry was missing.", "682eb4f6"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-04-18:0":{"b": ["Philip VI bought Montpellier from the king of Majorca", "05d06418"], "d": ["The sale by James III, king of Majorca, of his rights over Montpellier to King Philip VI of France was confirmed on 18 April 1349; Montpellier passed to the French crown.", "302b9de1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-07-16:0":{"b": ["Humbert II transferred the Dauphiné to the grandson of the king of France: Grenoble", "a8d8a248"], "d": ["The Treaty of Romans was made between Humbert II and the king of France on 30 March 1349; on 16 July 1349 at Lyon, by the deed 'Transport du Dauphiné à la France', the lands and title of the Dauphiné were left to Charles (the grandson of King Philip VI of France). From this moment 'Dauphin' became the title of the heir to the French throne.", "c129d1f5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1350-08-22:0":{"b": ["Philip VI died; John II (the Good) became king of France", "3eb96ab5"], "d": ["Philip VI died at Nogent-le-Roi on 22 August 1350; his son John II came to the throne.", "ed19aa83"]},
"OLAYLAR_FRANSA_KONTROL_1027:1360-10-24:0":{"b": ["Treaty of Calais: the terms of Brétigny were ratified, Poitou and Aquitaine were ceded to England: Poitiers", "8e13271f"], "d": ["The preliminary agreement of Brétigny of 8 May 1360 was ratified at Calais on 24 October 1360: Poitou, Saintonge, Aunis, Agenais, Périgord, Limousin, Quercy, Angoumois and Rouergue were left to England. Limoges, La Rochelle and Poitiers pass to England in the atlas on this day.", "278ddde1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1388-09-28:0":{"b": ["Nice surrendered to Count Amadeus VII of Savoy (the 'dédition' of Nice to Savoy)", "3af46844"], "d": ["During the succession dispute among the Angevin heirs of Provence, Nice and its surroundings (the County of Nice) came under the dominion of Count Amadeus VII of Savoy on 28 September 1388; Nice remained in the Savoy/Sardinian dynasty until 1860 (apart from French occupations). The atlas already carried this border; the entry was missing.", "04a5e558"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-12-01:0":{"b": ["Henry V entered Paris: the Anglo-Burgundian regime began", "126d50cb"], "d": ["After the Treaty of Troyes (21 May 1420), Paris came under Anglo-Burgundian dominion in December 1420; the city was governed in the name of Henry VI until April 1436.", "7426a907"]},
"OLAYLAR_FRANSA_KONTROL_1027:1422-10-21:0":{"b": ["Charles VI died; Charles VII was proclaimed king of France", "7aeefd1a"], "d": ["Charles VI died on 21 October 1422; despite the Treaty of Troyes, Charles VII proclaimed himself king (the Bourges region); Paris remained under Anglo-Burgundian control.", "da118a77"]},
"OLAYLAR_FRANSA_KONTROL_1027:1436-04-13:0":{"b": ["Paris surrendered to King Charles VII of France", "f3d92546"], "d": ["After the Treaty of Arras (1435), the people of Paris opened the gates to Charles VII's commanders on 13 April 1436; English rule came to an end.", "79a422fe"]},
"OLAYLAR_FRANSA_KONTROL_1027:1450-04-15:0":{"b": ["Battle of Formigny: the French army defeated the English army, the reconquest of Normandy accelerated", "77d20042"], "d": ["On 15 April 1450 at Formigny the French army defeated the English relief force; Caen and Cherbourg fell, and Normandy returned to French control.", "0287dae5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1477-01-01:0":{"b": ["Louis XI took Artois (Arras) from the Burgundian inheritance", "da697a1e"], "d": ["With the death of Charles the Bold at Nancy (5 January 1477), King Louis XI of France occupied Artois; Arras resisted and was taken by storm, and its walls were demolished. The Treaty of Arras (23 December 1482) left Artois in France as the dowry of Marguerite; by the Treaty of Senlis of 1493 it returned to the Habsburgs.", "7867c9fc"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:0":{"b": ["With the death of Charles III, Provence passed to King Louis XI of France under his will: Aix-en-Provence", "dc558e2c"], "d": ["Charles III, the last count of Provence of the House of Anjou, made his will in Marseille on 10 December 1481 and died on 11 December 1481; the County of Provence passed into the hands of the king of France. The union was legally finalized in 1486 (the accession of the Estates of Provence).", "42fad3ff"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:1":{"b": ["With the death of Charles III, Provence passed to King Louis XI of France under his will: Marseille", "bd072b2d"], "d": ["The will was drawn up in Marseille (10 December 1481); with Charles's death (11 December) Provence, and with it Marseille, passed to the French crown.", "3baf7804"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:2":{"b": ["With the death of Charles III, Provence passed to King Louis XI of France under his will: Arles", "de44f23c"], "d": ["Arles had been in the hands of the counts of Provence (Anjou) since 1251; with the passage of the county to the French crown (11 December 1481) it became French.", "b58a0e54"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:3":{"b": ["With the death of Charles III, Provence passed to King Louis XI of France under his will: Toulon", "7a8c1f9a"], "d": ["Toulon, the port of Provence, became French with the passage of the county to the French crown (11 December 1481); there is no separate source specific to Toulon, and the elder-brother center is Aix-en-Provence (DECLARED APPROXIMATION).", "11d22f4b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1493-01-01:0":{"b": ["Treaty of Senlis: Arras (Artois) returned to the Habsburg Maximilian", "040b03f8"], "d": ["The Treaty of Senlis (1493) between Charles VIII and Maximilian I gave Artois and Arras to the Habsburgs.", "2e7e96b7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1498-04-07:0":{"b": ["Charles VIII died; Louis XII became king of France", "560db6d5"], "d": ["Charles VIII died at Amboise on 7 April 1498; his cousin the duke of Orléans, Louis XII, came to the throne.", "24214314"]},
"OLAYLAR_FRANSA_KONTROL_1027:1552-01-01:0":{"b": ["Henry II's campaign of the Three Bishoprics: Toul was joined to France", "5d7053ac"], "d": ["Toul, ruled by prince-bishops and dependent on the German Empire, was joined to France in 1552 (the Three Bishoprics together with Metz and Verdun); it was legally confirmed at Westphalia in 1648. The day of Metz (18 April 1552) is separate in the atlas; for Toul there is no day in the source.", "5cdb37db"]},
"OLAYLAR_FRANSA_KONTROL_1027:1559-07-10:0":{"b": ["Henry II died; Francis II became king of France", "88a1a26e"], "d": ["Henry II died on 10 July 1559; his fifteen-year-old son Francis II came to the throne (influence of the House of Guise).", "746455f8"]},
"OLAYLAR_FRANSA_KONTROL_1027:1560-12-05:0":{"b": ["Francis II died; Charles IX became king of France", "16566c2b"], "d": ["Francis II died on 5 December 1560; his brother Charles IX (aged 10) came to the throne, and his mother Catherine de' Medici became regent.", "0139a790"]},
"OLAYLAR_FRANSA_KONTROL_1027:1574-05-30:0":{"b": ["Charles IX died; Henry III became king of France (while king of Poland)", "f86885f1"], "d": ["Charles IX died on 30 May 1574; his brother Henry de Valois, who was king of Poland, became heir to the French throne and returned to France in September 1574.", "f3fea374"]},
"OLAYLAR_FRANSA_KONTROL_1027:1589-08-01:0":{"b": ["On his deathbed Henry III recognized Henry of Navarre (Henry IV) as his successor: the Bourbon dynasty begins", "328bca08"], "d": ["Henry III, who had been assassinated, as the last king of the Valois line solemnly recognized Henry of Navarre as his successor on 1 August 1589; with his death (2 August) the Bourbon dynasty passed to the French throne.", "df18d0c2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1610-05-14:0":{"b": ["The reign of Henry IV came to an end; Louis XIII became king", "dfe5892c"], "d": ["Henry IV died in Paris by assassination on 14 May 1610; his son Louis XIII became king. (The end of the reign is, in Treccani, «Regnò fino al 14 maggio 1610».)", "86a0f811"]},
"OLAYLAR_FRANSA_KONTROL_1027:1643-05-14:0":{"b": ["Louis XIII died; five-year-old Louis XIV became king (regency: Anne of Austria, Mazarin)", "2ac0d106"], "d": ["Louis XIII died at Saint-Germain-en-Laye on 14 May 1643; his son Louis XIV came to the throne on the same day.", "6a173c34"]},
"OLAYLAR_FRANSA_KONTROL_1027:1681-09-30:0":{"b": ["Strasbourg capitulated to Louis XIV's army: it was joined to France", "3c3c1cc6"], "d": ["During the policy of the Réunions, Louvois's army besieged Strasbourg; the city signed the terms of surrender on 30 September 1681 (deed of capitulation at Illkirch); ratification on 3 October, and Louis XIV's ceremonial entry on 23 October 1681. The city was joined to France, and municipal autonomy was destroyed.", "4f2a5014"]},
"OLAYLAR_FRANSA_KONTROL_1027:1791-09-14:0":{"b": ["The Constituent Assembly approved the union of Avignon and the Comtat Venaissin with France", "d15fe246"], "d": ["After the expulsion of the papal vice-legate in Avignon (12 June 1790), the Constituent Assembly examined the request for union; the union was approved on 14 September 1791. Pius VI protested on 5 November 1791; by Article 6 of the Treaty of Tolentino (19 February 1797) the papacy renounced Avignon and the Comtat.", "a422cae7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1793-01-03:0":{"b": ["Monaco was annexed to the French Republic under the name Fort-Hercule", "1b846e31"], "d": ["With Revolutionary France's annexation of Monaco, Grimaldi sovereignty was cut off; the principality was part of France (Fort-Hercule) until 1814.", "c3f4c386"]},
"OLAYLAR_FRANSA_KONTROL_1027:1798-03-15:0":{"b": ["The Republic of Mulhouse joined the French Republic (Réunion)", "0c2b4f8a"], "d": ["The Republic of Mulhouse, an ally of the Swiss Confederation since 1515, joined France voluntarily after the Peace of Basel (1795); the union took place in 1798 (Réunion).", "e775b26b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1814-05-30:0":{"b": ["Treaty of Paris: Monaco returned to Grimaldi sovereignty", "f3011157"], "d": ["By the Treaty of Paris of 30 May 1814 the rights of the Grimaldis were restored; Monaco emerged from French annexation (the Sardinian protectorate of 1815-1861 is a separate matter and is not treated in this entry).", "32ba22e7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1861-02-02:0":{"b": ["Franco-Monegasque treaty: Monaco gave up its rights over Menton (and Roquebrune) for 4 million francs; Menton passed to France", "ffa21e54"], "d": ["After the cession of Piedmont-Sardinia, together with Nice, to France in 1860, the Prince of Monaco ceded his rights of sovereignty over Menton and Roquebrune to France. Menton had been a free city under Sardinian protection since 1848.", "0aff978e"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-17:0":{"b": ["French troops entered Mulhouse: the return of Alsace began", "a56edca7"], "d": ["Six days after the Armistice (11 November 1918), French troops entered Mulhouse. Article 51 of Versailles treats the return of Alsace-Lorraine to French sovereignty as retroactive to 11 November 1918; signature 28 June 1919, entry into force 10 January 1920.", "204a7d28"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-18:0":{"b": ["French troops entered Colmar", "dabdf81a"], "d": ["Colmar welcomed French troops on 18 November 1918; Alsace was returning to French administration (legal retroactivity 11 November 1918, Versailles art. 51).", "04dcdb67"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-19:0":{"b": ["The French 28th Infantry Division entered Metz", "c37a5b99"], "d": ["The French 28th Infantry Division entered Metz on 19 November 1918; Moselle returned to French administration.", "aa57e100"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-21:0":{"b": ["French troops entered Strasbourg (official ceremony 22 November)", "92b3cc2e"], "d": ["After 47 years of German administration, the first French troops entered Strasbourg on 21 November 1918; the official entry ceremony was held the next day.", "22f53345"]},
"OLAYLAR_FRANSA_KONTROL_1027:1940-08-02:0":{"b": ["Wagner and Bürckel became chiefs of civil administration of Alsace and Lorraine: the region was in effect annexed to the Reich", "0e36dc11"], "d": ["After France's defeat, Alsace and Moselle were in effect annexed to Germany without a treaty: Alsace was placed under the civil administration of Wagner, Gauleiter of Baden, and Moselle under that of Bürckel, Gauleiter of Saar-Palatinate (Moselle was attached to Gau Westmark on 30 November 1940). The armistice text contains no annexation clause; legally French sovereignty continues (Ordonnance of 9 August 1944).", "8f35b253"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-20:0":{"b": ["Mulhouse was liberated", "151f48e4"], "d": ["The French First Army (de Lattre) liberated Mulhouse in November 1944.", "78fba884"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-22:0":{"b": ["Metz was liberated (the forts held out until December)", "17049694"], "d": ["The US Third Army liberated Metz on 22 November 1944; the surrounding forts held out until December.", "4566f454"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-23:0":{"b": ["Leclerc's 2nd Armored Division liberated Strasbourg", "7b399aa3"], "d": ["The 2nd Armored Division under Leclerc entered Strasbourg on 23 November 1944; German administration in the capital of Alsace (de facto annexation since 1940) came to an end.", "4f1f13e2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1945-02-02:0":{"b": ["Colmar was liberated (the Colmar Pocket was cleared on 9 February)", "41a297f7"], "d": ["Colmar was liberated on 2 February 1945; the Colmar Pocket was completely cleared on 9 February 1945.", "3cc05417"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Süleyman the Lawgiver's departure on the Vienna campaign — the Habsburg war began again", "f7afd2a9"], "d": ["After Mohács the Hungarian throne had been split in two, and in 1527 Ferdinand had taken Buda and driven Szapolyai out of the capital. The sultan set out on campaign for the fourth time to support Szapolyai and halt the Habsburg advance; before the campaign, the grand vizier Ibrahim Pasha was given the title of serasker and the beylerbeyilik of Rumelia, and all the planning was done with him. Heavy rains along the way delayed the army's advance; the campaign continued with the taking of Buda and its being given to Szapolyai, and the siege of Vienna.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Renewal of the peace with the Habsburgs — the end of the war over Transylvania and Temeşvar", "97071975"], "d": ["The war, which had begun with the passing of Transylvania to Ferdinand in 1551 and was carried on through campaigns such as the conquest of Temeşvar and the siege of Eğri, was closed with the decision to continue the peace with the Habsburgs. The agreement mutually renewed the earlier commitments of the two sides; but it brought no solution to the disorders on the frontier, and after Ferdinand's death in 1564 events in Transylvania increased again.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["Süleyman the Lawgiver's last campaign — departure from Istanbul with Szigetvár and Eğri as targets", "31277d21"], "d": ["After Ferdinand's death in 1564 and Maximilian II's accession to the throne, clashes on the Transylvanian frontier had increased. In the campaign that the aged sultan planned with Sokullu Mehmed Pasha, the targets were to be the fortresses of Szigetvár and Eğri, and the emperor was also to be intimidated. After praying at the Tomb of Eyüp Sultan, he left Istanbul with a great ceremony; he reached Edirne on 15 May and reached Belgrade on the fiftieth day of his march. This was his last departure from the capital, which he would never see again.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Treaty of Edirne — the end of the state of war with the Habsburgs", "d08883e3"], "d": ["Envoys of the Habsburgs, the Safavids, Poland, France and Venice were present before Selim II, who wintered in Edirne after the Szigetvár campaign. It was decided that peace with the Safavids would continue; a treaty was signed that ended the state of war with the Habsburgs. The influence of the grand vizier Sokullu Mehmed Pasha was great in these affairs.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Decision on the Iranian campaign — two commanders were appointed against the Safavids, shaken by the death of Tahmasb", "1f09b186"], "d": ["With the poisoning of Shah Tahmasb I in 1576 as a result of the disputes among the dynasty and the notables of the state, the Safavids had been drawn into great turmoil; this determined the direction of the campaign to be launched. Lala Mustafa Pasha was charged with entering Iran from the Erzurum side and Koca Sinan Pasha from the Baghdad side. When the dispute between the two viziers intensified, Sokullu intervened: Sinan Pasha was removed from his post, and Lala Mustafa Pasha was charged with the conquest of Shirvan by way of Georgia. This decision is the opening of the Ottoman-Safavid war of 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Cigalazade Sinan Pasha set out on the Iranian campaign", "1e90763e"], "d": ["While the two-front war with Iran and Austria continued, Shah Abbas had besieged and taken Revan and entered Kars, but could be stopped only before Akhaltsikhe. Cigalazade Sinan Pasha, appointed commander of the East, set out from Istanbul late and reached the front of Kars on 8 November. Although circumstances were favourable, he did not march against the shah but wintered in Van, and upon the shah's attack he moved to Erzurum; a campaign season was wasted.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Cigalazade Sinan Pasha's rout near Lake Urmia (Sufiyan)", "7438fec4"], "d": ["The position of Sinan Pasha, who marched in the 1605 campaign season to retake Tabriz, was shaken when the beylerbeyi of Erzurum, Köse Sefer Pasha, moved separately from the main army and was taken prisoner. Shah Abbas's sudden attack inflicted a heavy defeat on the army around Lake Urmia; Sinan Pasha withdrew first to Van, then to Diyarbekir. His having the beylerbeyi of Aleppo, Canbolatoğlu Hüseyin Pasha, executed for being late with aid kindled a great revolt in Anatolia; after Sinan Pasha's death Shah Abbas took Ganja, Shirvan and Shamakhi.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Kuyucu Murad Pasha's Tabriz campaign — no encounter took place at Acıçay", "3c0a0a5d"], "d": ["The grand vizier Kuyucu Murad Pasha, who had suppressed the Celali revolts and secured calm in Anatolia, marched by way of Erzurum, Hasankale, Chaldiran and Khoy against Shah Abbas, who was reported to be waiting in Tabriz. The two armies came face to face at the locality of Acıçay north of Tabriz, but no battle took place; correspondence continued. With the approach of winter and a shortage of munitions and provisions, the pasha withdrew to Diyarbekir by way of Ahlat, Van and Bitlis, and died there the following summer while preparing a new campaign (5 August 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["The Ottoman-Safavid war began again — the grand vizier Öküz Mehmed Pasha set out on the Eastern campaign", "ef32fa31"], "d": ["When no news came from İncili Mustafa Çavuş, who had been sent to Iran as an envoy after the 1612 Treaty of Nasuh Pasha, the grand vizier Mehmed Pasha was charged with the Eastern campaign and, having completed his preparations, crossed to Üsküdar. Just as he was setting out, news came that İncili Çavuş and the Iranian envoy Burun Kāsım Khan had reached Van with an agreement and gifts, but the campaign was not postponed. The grand vizier spent the winter in Aleppo.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Siege of Revan — lifted without result after fifty-five days", "64a4ecb6"], "d": ["The grand vizier, who set out from Aleppo in April 1616 with a large army, reached Revan by way of Erzurum and Kars. Because it was thought the fortress would surrender easily, heavy cannon had not been brought; the siege lasted fifty-five days without materiel. After the Janissary agha Muslu Agha and Tekeli Mehmed Pasha fell as martyrs, with the reluctance of the soldiers and the advance of the season, the siege was lifted and the army withdrew to Erzurum. Mehmed Pasha was dismissed in November 1616, and Halil Pasha took his place.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["The rout of Serav (Pul-i Shikasta) — Halil Pasha's Iranian campaign", "d323ed03"], "d": ["Halil Pasha, who became commander in place of Öküz Mehmed Pasha, marched on Iran again in 1618. The battle fought at the locality of Pul-i Shikasta between Tabriz and Ardabil ended in the defeat of the Ottoman army. After this rout, which is also referred to in the sources as the Battle of Serav, the Treaty of Serav was signed in the same month.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["Hafız Ahmed Pasha's siege of Baghdad — it lasted seven months and twenty days and ended without result", "764acb0a"], "d": ["The Ottomans, who had lost Baghdad in 1623, marched under the grand vizier and commander Hafız Ahmed Pasha to retake the city. When the proposal, at the council assembled at Kirkuk, to hold the passes first was not accepted, the army besieged Baghdad directly. The pasha himself entered the trenches; although the city was entered through a mine exploded on the seventy-second day, the soldiers were repulsed. When Shah Abbas came to its aid with 30,000 men in March 1626, the army was caught between two fires; heavy losses were suffered in the shah's attack of 7 June. When provisions ran out and the heat and fever were wearing down the soldiers, the siege was lifted and the army withdrew to Diyarbekir.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["Hüsrev Pasha's siege of Baghdad — lifted after thirty-nine days", "18de5581"], "d": ["After the victory of Mihriban (5 May 1630), the grand vizier Hüsrev Pasha, who entered Hamadan and burned and destroyed the city, instead of marching on Qazvin turned back to the real target, Baghdad, by the decision of the war council assembled at Dergezin. The army, which reached the vicinity of Baghdad in early August, besieged the city on 6 October. Heavy losses were suffered in the sortie of the Iranian garrison on 26 October and in the general assault of 9 November; this second siege after the loss of Baghdad was also lifted without result. The army withdrew to Mosul.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Lepanto was returned to the Ottomans in accordance with Karlowitz", "9ca4f9dd"], "d": ["Lepanto, which, after resisting for a long time during the wars of 1683-1699, fell to Venice together with the neighbouring fortresses in July 1687, remained in Venetian hands until a year after the Treaty of Karlowitz and then returned to the Ottomans. The fortress at the mouth of the Gulf of Corinth thus came back under Ottoman administration fifteen years before the Morea.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Topal Osman Pasha defeated Nadir at Dujail — the siege of Baghdad was lifted", "7ae1fc9e"], "d": ["Against Nadir, who had besieged Baghdad in January 1733, the army sent to the aid of Baghdad under the command of Topal Osman Pasha routed Nadir's forces at Dujail near Samarra; the wounded Nadir withdrew to Hamadan, and the siege that had lasted for months was lifted. But the victory was short-lived: at the end of the same year Nadir entered Iraq again and defeated the Ottoman forces at Akderbend, north of Kirkuk; Topal Osman Pasha lost his life during these battles and was buried in Kirkuk.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Nadir Shah's Iraq campaign — the last Ottoman-Iranian war began, Kirkuk fell", "ba014bf5"], "d": ["Nadir Shah, who had stayed eighteen months in Dagestan and Georgia, his demand that Jaʿfarism be recognised as the fifth school having been rejected by the Ottomans, began a new campaign against the Ottomans in 1743 and entered Kirkuk with a large army. He could not repeat the same success at Mosul; he was forced to lift the siege. This war is the last Ottoman-Iranian war, which ended with the 1746 Treaty of Kerden.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Nadir Shah's siege of Kars — it lasted two months and produced no result", "a3ea61d9"], "d": ["Sāfī Mirza, a Safavid prince who had taken refuge with the Ottomans, was claiming rights to the Iranian throne; according to the plan, the seraskier of Kars would take him by way of Tabriz to Isfahan and place him on the throne, and the Ottomans had opened three fronts against Iran. Thereupon Nadir Shah marched on Kars and besieged the fortress. He obtained no result from the siege, which lasted two months.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["The rout of Kağaverd — the army of Yeğen Mehmed Pasha was dispersed", "7caf6f22"], "d": ["In the year after the siege of Kars, Nadir Shah routed the Ottoman forces under the command of Yeğen Mehmed Pasha at the locality of Kağaverd. He then returned to Isfahan. His giving up the insistence on the recognition of Jaʿfarism opened the way to the Treaty of Kerden the following year.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["The seizure of the emirate of Ha'il by Saudi-Wahhabi forces — the administration was in the hands of the Ibn Ali family of the Abde clan", "2d29ceb9"], "d": ["When the forces of the First Saudi State seized the emirate of Ha'il, the administration of the city was in the hands of the Ibn Ali family of the Abde clan of the Shammar tribe. This family ruled Ha'il until 1835, when Abdullah b. Rashid seized the emirate; the Rashidid dynasty was founded only at that date. In the atlas Ha'il had until now appeared ownerless until 1836, whereas the source names the emir of the city in 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["The passing of the Kvarner islands to Napoleon's Kingdom of Italy and of the Bay of Kotor to Russian administration", "c5e411c8"], "d": ["After the Treaty of Pressburg, the Kvarner islands — unlike Dalmatia — were attached not directly to France but to Napoleon's Kingdom of Italy; they entered the Illyrian Provinces only in 1809. In the Bay of Kotor, Austrian administration ended and Russian administration was established between 1806 and 1807; the Bay passed to France only in 1807. These two distinctions cannot be met by a single 'France' window in the atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Dalmatia's passing to French administration — the implementation of the Treaty of Pressburg (Bratislava)", "00bfe4f6"], "d": ["The Treaty of Pressburg (Bratislava/Pressburg) of 26 December 1805 forced Austria to give up Istria, Dalmatia and all the Adriatic islands. France effectively took over the administration in February 1806; Zadar remained the seat of the governor-general (proveditor), and between 1806 and 1810 this office was held by the Venetian Vincenzo Dandolo. Dalmatia was added to the Illyrian Provinces after the 1809 Treaty of Schönbrunn. The first Austrian administration, which had lasted since 1797, thus came to an end — in the atlas this period had until now appeared as uninterrupted Austrian.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Austria's retaking of the Illyrian Provinces and Dalmatia — the end of Napoleonic administration", "1b2ac942"], "d": ["At the end of 1813 Habsburg units retook the region south of the Sava, and the old frontier organisation was re-established; the Austrian army entered Istria in October 1813. Karlovac thereafter became part of the Austrian Kingdom of Illyria. The period of French administration in Dalmatia also closed in 1813. The region's belonging to Austria was officially confirmed by the 1814 Peace of Paris and the decisions of the 1815 Congress of Vienna.", "a5c337df"]},
"OLAYLAR_KAMERIKA:1535-04-17:0":{"b": ["The Viceroyalty of New Spain was established", "d86e1ae4"], "d": ["Charles V, king of Spain, attached the conquered Mexican lands directly to royal administration, established the Viceroyalty of New Spain, and appointed Antonio de Mendoza as the first viceroy. This arrangement ended the order based on the personal disposal of the conquerors. The boundaries of the viceroyalty, whose center was in Mexico, comprised Mexico, the Yucatán peninsula and the regions of Guatemala.", "a4ad96e7"]},
"OLAYLAR_KAMERIKA:1762-11-03:0":{"b": ["Treaty of Fontainebleau — Louisiana was ceded to Spain", "c96ae72d"], "d": ["Toward the end of the Seven Years' War, France ceded Louisiana west of the Mississippi, and New Orleans, to Spain by a secret treaty. Thus France's presence in North America in effect came to an end: the next year the Treaty of Paris would give the east of the river to Britain.", "18ac5acb"]},
"OLAYLAR_KAMERIKA:1803-01-01:0":{"b": ["Fort William was founded — the inland headquarters of the North West Company", "41157d26"], "d": ["When Grand Portage remained on United States territory, the North West Company moved its inland headquarters to the north of Lake Superior and founded Fort William. The post was the annual meeting place where the canoes coming from Montreal and the furs coming from the interior met, and it became the heart of the company's continent-wide network.", "72d44bb1"]},
"OLAYLAR_KAMERIKA:1803-01-01:1":{"b": ["Fort Dearborn was founded — a United States post at the Chicago portage", "1f5f943b"], "d": ["The United States Army founded Fort Dearborn at the Chicago portage, which joins Lake Michigan and the Mississippi basin. The portage had been known and used since the 1670s; the fort marked the westward extension of United States control in the Northwest Territory.", "c067e27f"]},
"OLAYLAR_KAMERIKA:1803-01-01:2":{"b": ["Fort George (Chisasibi) was founded — the east coast of James Bay", "bbf75f94"], "d": ["The Hudson's Bay Company founded Fort George on the east coast of James Bay at the mouth of the La Grande River. The post enabled the Cree groups of the interior to trade without descending to the coast and completed the company's eastern coastal line.", "4a44c409"]},
"OLAYLAR_KAMERIKA:1829-01-01:0":{"b": ["Fort Halkett was founded — the fur line along the Liard", "de534aa9"], "d": ["The Hudson's Bay Company founded Fort Halkett on the Liard River and thereby extended the fur line from the Mackenzie basin to the west of the Rockies. The post was one of the company's westernmost advanced stations in Kaska Dene territory.", "b47a58dd"]},
"OLAYLAR_KAMERIKA:1829-01-01:1":{"b": ["Fort Pitt was founded — a bison meat and fur center on the North Saskatchewan", "0fca471b"], "d": ["The Hudson's Bay Company founded Fort Pitt on the bank of the North Saskatchewan in order to close the gap between Fort Carlton and Fort Edmonton. The post became one of the main centers of pemmican supply and a nodal point of trade between the Plains Cree and the company.", "4806ba8d"]},
"OLAYLAR_KAMERIKA:1829-01-01:2":{"b": ["Springfield was founded — the first permanent settlement on the Ozark plateau", "49557b40"], "d": ["Springfield was founded on the Ozark plateau, at the eastern end of the Osage lands in southwestern Missouri. The settlement became the center of the migration toward the land opened up after the Osage left the region in 1825, and became the main town of southwestern Missouri.", "74ee2fe5"]},
"OLAYLAR_KAMERIKA:1851-09-17:0":{"b": ["Treaty of Fort Laramie — boundaries were drawn on the Northern Plains", "791662bf"], "d": ["The treaty signed between the United States and the peoples of the Northern Plains defined in writing for the first time the boundaries of the lands of the Lakota, Crow, Mandan, Hidatsa, Arikara, Cheyenne, Arapaho and Assiniboine, and in return bound itself to the security of the emigrant roads. The boundaries were soon overrun.", "ccb46cba"]},
"OLAYLAR_KAMERIKA:1868-07-03:0":{"b": ["Treaty of Fort Bridger — the Wind River Reservation was established", "daa3f132"], "d": ["The treaty that the Eastern Shoshone and Bannock signed with the United States granted the Shoshone under Washakie a reservation in the Wind River basin. The Shoshone, unlike the other peoples who fought the United States on the plains, had chosen the path of alliance and had in this way kept part of their homeland. The treaty determined the legal status of the Shoshone lands in the northern part of the Great Basin.", "e37c9fa3"]},
"OLAYLAR_KAMERIKA:1880-09-01:0":{"b": ["Britain transferred the Arctic Archipelago to Canada", "f8a7cb12"], "d": ["By decision of the British Order in Council, all the islands in the north of North America and the rights over them were transferred to the Dominion of Canada. The decision was the last step following the transfer of Rupert's Land completed in 1870, and established on paper the present northern boundaries of Canada. The transfer was made without consulting the Inuit communities living in those lands, and actual administration was not established for decades.", "4cb3cc28"]},
"OLAYLAR_KI117:1684-08-24:0":{"b": ["Yazlovets passes to Polish hands", "c86581e5"], "d": ["During Sobieski's Moldavian campaign the Polish army, after a two-day siege, retook Yazlovets, which had been in Ottoman hands since 1672. The dissolution of the sancak of Kamianets began in this way.", "98482094"]},
"OLAYLAR_KI117:1684-11-03:0":{"b": ["Pest returns to the Ottomans", "13914c49"], "d": ["Pest, which Habsburg troops had entered in June 1684, returned to Ottoman control in early November 1684 after the failure of the siege of Buda; the Habsburgs would enter Pest for good in 1686.", "41164adc"]},
"OLAYLAR_KI117:1686-01-01:0":{"b": ["The Ottoman evacuation of the fortress of Medzhybizh", "2c4b5a7f"], "d": ["The fortress of Medzhybizh in Podolia was evacuated by the Ottomans in 1686; as they withdrew they tried to blow up the fortress. About eight years of Ottoman rule came to an end.", "27fe058d"]},
"OLAYLAR_KI117:1686-06-17:0":{"b": ["Habsburg cavalry entered Pest — preliminary preparation for the siege of Buda", "c9d23487"], "d": ["The vanguard of the Habsburg army preparing for the siege of Buda, the Bavarian cavalry, entered Pest, which the Ottoman garrison had abandoned; the eastern bank of the Danube definitively passed under Habsburg control. Buda itself would fall on 2 September.", "9329e3b2"]},
"OLAYLAR_KI117:1686-10-01:0":{"b": ["Mohács passes under Habsburg control", "f022d9c0"], "d": ["In the Habsburg advance south of the Danube after the fall of Buda, Mohács passed under the control of the allies in the autumn of 1686; the following summer the army would try to resist along this line at Harsány (1687).", "06cb2407"]},
"OLAYLAR_KI117:1687-07-01:0":{"b": ["Lepanto (İnebahtı) passes to Venice", "8daedb90"], "d": ["After the fall of Patras, Lepanto at the mouth of the Gulf of Corinth was also abandoned by the Ottomans and passed under Venetian control; it would be returned by the Treaty of Karlowitz in 1699.", "2b368884"]},
"OLAYLAR_KI117:1689-09-11:0":{"b": ["Baden reached Jagodina — the Morava corridor entered the Austrian line", "a6459b85"], "d": ["After the defeat at Batočina (30 August) the Ottoman army withdrew southward; Baden reached Jagodina on 11 September 1689 and built a bridge over the Morava. The Austrian line extended to Niš by way of Jagodina–Ćuprija–Paraćin, while Alaca Hisar remained outside the line.", "9badb3bd"]},
"OLAYLAR_KI117:1690-08-29:0":{"b": ["Dursun Mehmed Pasha entered Vidin — the Danube bank is Ottoman again", "2b4d5344"], "d": ["In Fâzıl Mustafa Pasha's counteroffensive, the land army of Dursun Mehmed Pasha, the mutasarrıf of Karaman, and the Danube fleet of Mezemorta Hüseyin Pasha retook Vidin from Austria.", "d76ac495"]},
"OLAYLAR_KI117:1690-09-01:0":{"b": ["The pasha of Rumelia entered the fortress of Orsova", "3884232b"], "d": ["When the Austrian army withdrew from Serbia at the end of August 1690, the pasha of Rumelia retook Orsova; the Danube bank of the Banat returned to Ottoman control.", "541ca167"]},
"OLAYLAR_KI117:1690-09-17:0":{"b": ["The fortresses of Valona and Kanina fell to Venice", "51bf7b50"], "d": ["While the Ottoman counteroffensive continued in Serbia, the Venetian fleet and forces took Valona and Kanina on the Albanian coast; the two fortresses would be demolished and abandoned in March 1691.", "238bd38c"]},
"OLAYLAR_KI117:1691-03-15:0":{"b": ["Venice demolished the fortresses it had taken in Albania and withdrew", "378490dd"], "d": ["The Venetians, who had taken Valona and Kanina on 17 September 1690, demolished the fortresses and withdrew in mid-March 1691; southern Albania returned to Ottoman control.", "aa90ce2d"]},
"OLAYLAR_KI117:1695-01-01:0":{"b": ["Kızıkermen passes into Russian hands", "2b90f9af"], "d": ["In the Dnieper-line operations concurrent with Russia's Azov campaign, Sheremetev and Mazepa took Kızıkermen; the fortress remained in Russian hands until the Treaty of Istanbul of 1700.", "c310dfdd"]},
"OLAYLAR_KI117:1695-01-12:0":{"b": ["The surrender of Gyula to the Habsburgs", "e378c570"], "d": ["The besieged Gyula signed a capitulation on 21 December 1694; on 12 January 1695 the garrison marched out and Habsburg troops entered. Until Karlowitz (1699) the fortress was in Habsburg, not Ottoman, hands.", "5e4c275b"]},
"OLAYLAR_KI117:1699-09-22:0":{"b": ["The surrender of Kamianets to Poland", "05950f7a"], "d": ["As required by the Treaty of Karlowitz of 26 January 1699, the evacuation of Podolia was completed in September; the keys of Kamianets were handed over to the Polish commission on 22 September 1699. The transfer to Poland, together with the dependent fortresses of the sancak (Bar, Medzhybizh, Yazlovets), was effectively accomplished on this day.", "15c85c1d"]},
"OLAYLAR_KRONOEKSIK0921:1603-06-07:0":{"b": ["The strangling of Prince Mahmud", "9fc2fdb5"], "d": ["Mehmed III, suspecting that his eldest son Prince Mahmud had designs on the throne and could depose him, had him strangled; the prince's mother and about thirty of her servants were thrown into the sea. In the midst of the Celâlî revolts and the unrest in Anatolia, the sultan had seen that the soldiery inclined toward the prince; it is recorded that the valide sultan was also displeased with the prince's mother. This execution is one of the last links leading, with the death of Mehmed III six months later, to the throne being left solely to the thirteen-year-old Ahmed I and to the effective end of the custom of fratricide.", "bacf93cd"]},
"OLAYLAR_KRONOEKSIK0921:1621-01-01:0":{"b": ["An unprecedented winter — the freezing of the Bosphorus", "9e4fb488"], "d": ["While preparations for the Polish campaign continued, Istanbul experienced an unprecedented winter: the strait froze, and food and drink could not be found in the city. Grand Vizier Güzelce Ali Pasha, who feared for his life because of the distress in the market, died shortly after the weather improved and the situation returned to normal, on 15 Rabî' al-âkhir (9 March), and Hüseyin Pasha of Ohrid was brought in his place. The imperial tent was pitched on 7 Jumâdâ al-âkhira (29 April) on the plain of Dâvud Pasha; the campaign that would take Osman II to Khotin began after this winter.", "146293da"]},
"OLAYLAR_KRONOEKSIK0921:1826-04-08:0":{"b": ["The completion of the construction of the Nusretiye Mosque", "30dfdc64"], "d": ["The construction of the sultanic mosque that Mahmud II had built at Tophane was finished on 8 April 1826; the building replaced the mosque of the Tophane Barracks that was reduced to ashes in the great fire of 24 February 1823, and its construction had begun in June 1823. Its architect is Krikor Amira Kalfa of the Balyan family; it is regarded as the most showy example of the Empire style in Ottoman mosque architecture. On 14 May 1826 the minarets were demolished as far as the lower balcony and rebuilt so as to be higher; the name \"Nusretiye\" (victory) of the mosque was given in commemoration of the abolition of the Janissary Corps in June of the same year, but it is known among the people as the Tophane Mosque.", "3043db31"]},
"OLAYLAR_KRONOEKSIK0921:1883-11-03:0":{"b": ["The founding of the Hendese-i Mülkiyye Mektebi", "abfa076e"], "d": ["After the Ottoman-Russian War of 1877-78, the Hendese-i Mülkiyye Mektebi was founded by Abdülhamid II on 3 November 1883 with the aim of training engineers from the Turkish and Muslim population. The school institutionalized civil engineering education as a separate institution alongside the military engineering schools; the opening ceremony of its own building was held on 29 October 1884. In 1909 it was taken from military administration, attached to the Ministry of Public Works (Nâfia Nezâreti), and took the name Mühendis Mekteb-i Âlîsi.", "48cf01ce"]},
"OLAYLAR_KUNFUZE_1016:1814-03-01:0":{"b": ["Muhammad Ali's forces took Qunfudhah from the Wahhabis", "fbeec58b"], "d": ["A naval expedition setting out from Jeddah took Qunfudhah, which had been for five years in the hands of the Asir sheikh Tami, without bloodshed.", "fa0c98f2"]},
"OLAYLAR_KUNFUZE_1016:1814-05-01:0":{"b": ["Tami's attack: the Egyptian garrison withdrew to the ships", "4dcc360c"], "d": ["The Wahhabi force under Tami overpowered the Albanian soldiers holding the wells; the Egyptian forces fled to the ships, and the cannon and baggage were left to the Wahhabis.", "63048c2e"]},
"OLAYLAR_KUNFUZE_1016:1815-03-01:0":{"b": ["Muhammad Ali entered Qunfudhah after the victory at Bisl", "916105b7"], "d": ["The army that marched south after Bisl reached Qunfudhah; the captured Tami was brought here, and from here the army returned to Mecca.", "9e1ae360"]},
"OLAYLAR_KUNFUZE_1016:1840-05-09:0":{"b": ["The Egyptian army withdrew from Tihama", "1047f577"], "d": ["On the order of evacuation, Egypt's army of Yemen left Tihama; the coastal cities passed into the hands of the sharif of Abu Arish.", "f6a889e6"]},
"OLAYLAR_KUNFUZE_1016:1871-03-01:0":{"b": ["Redif Pasha's division landed at Qunfudhah", "4a6ef114"], "d": ["The reserve division (firka-i ihtiyatiyya) that passed through the Suez Canal landed at Qunfudhah, which was in the hands of the Mughaydis, and marched from there to the Asir mountains.", "9de9bb79"]},
"OLAYLAR_KUNFUZE_1016:1916-07-18:0":{"b": ["The surrender of Qunfudhah to British ships", "265e164a"], "d": ["On the bombardment of British warships the Ottoman garrison surrendered; the Idrisi flag was raised over the town, and a few days later an Idrisi garrison was installed. In August, at the protest of Sharif Husayn, Britain forced the Idrisi to withdraw.", "f88ff660"]},
"OLAYLAR_KUNFUZE_1016:1919-05-01:0":{"b": ["King Husayn of the Hejaz reoccupied Qunfudhah", "a86c61fa"], "d": ["Hejaz officials were sent to Qunfudhah, which had been left empty throughout the war; the Idrisi objected.", "c93e8a47"]},
"OLAYLAR_KURULUS_GERI_1021:0630-01-11:0":{"b": ["Mecca was conquered: the city passed to the Medina State", "8435e73c"], "d": ["The Prophet conquered Mecca (20 Ramadan 8 / 11 January 630).", "865a73bd"]},
"OLAYLAR_KURULUS_GERI_1021:0632-06-08:0":{"b": ["Death of the Prophet: Mecca was attached to the Rashidun caliphs", "b65e8cd1"], "d": ["Muhammad died on 13 Rabīʿ I 11 / 8 June 632; Mecca came under the administration of the Rashidun caliphs.", "99716bea"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["Kufa was founded", "617d0f35"], "d": ["Kufa was generally established as a garrison city in 17 (638); it became the centre of the Rashidun Caliphate in Iraq (the day is unknown).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-01-01:0":{"b": ["ʿAlī was martyred in Kufa; Kufa passed to Umayyad rule", "94fb307d"], "d": ["ʿAlī was martyred by Ibn Muljam in the Mosque of Kufa (661); the Rashidun period closed, and the city came under Umayyad administration (year precision; the Zubayrid interim period of 680-691 was not written separately in the record).", "a58ed98f"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["Muʿāwiya received the oath of allegiance: Mecca came under Umayyad rule", "d6dcc232"], "d": ["Muʿāwiya received the oath of allegiance on 25 Rabīʿ I 41 / 29 July 661; Mecca was attached to the Umayyad governors (no day specific to Mecca, the state's day).", "16cecb18"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["Kairouan was founded (ʿUqba b. Nāfiʿ, Umayyad)", "7409e9ae"], "d": ["The Umayyad governor ʿUqba b. Nāfiʿ founded Kairouan in 670 as the base of Ifriqiya.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0683-11-27:0":{"b": ["Ibn al-Zubayr proclaimed his caliphate in Mecca: Mecca left the Umayyads", "9e31ca5c"], "d": ["The news of Yazīd's death reached Mecca (27 November 683); ʿAbd Allāh b. al-Zubayr proclaimed a caliphate centred on Mecca (64/683).", "212a96b5"]},
"OLAYLAR_KURULUS_GERI_1021:0692-10-01:0":{"b": ["Al-Ḥajjāj took Mecca: the city again came under Umayyad rule", "48dd6e68"], "d": ["At the end of the siege by al-Ḥajjāj b. Yūsuf, Mecca again came under Umayyad rule on 14 Jumādā I 73 / 1 October 692.", "25eedec5"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["ʿAbd al-Raḥmān b. Ḥabīb rebelled: Kairouan left Umayyad administration", "4c7a0da0"], "d": ["With the rebellion of ʿAbd al-Raḥmān b. Ḥabīb in 745, Kairouan left the Umayyad governorship; a Habibid/Kharijite interim until 761 (a gap with a declared owner).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["The Abbasid army took Kufa", "0191709e"], "d": ["The Abbasid army took Kufa on 14 Muharram 132 (2 September 749); the city passed from the Umayyads to the Abbasids.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0750-08-05:0":{"b": ["The Umayyad state came to an end: Mecca passed to Abbasid rule", "382e4d6e"], "d": ["The last Umayyad caliph, Marwān II, was killed on 26 Dhū'l-Ḥijja 132 / 5 August 750; Mecca entered the Abbasid governorship of the Haramayn (no day specific to Mecca — the day of the end of the state, declared approximation).", "710c6ec7"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["Muhammad b. al-Ashʿath, appointed by the Abbasids, took Kairouan", "71af9f79"], "d": ["In the year 144 (761) Muhammad b. al-Ashʿath took Kairouan in the name of the Abbasids.", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["Caliph al-Manṣūr began the construction of Baghdad (Madīnat al-Salām)", "844a94d5"], "d": ["Construction work on the city founded on the bank of the Tigris began in 762; it became the permanent capital of the Abbasids (the day is unknown, only the year is confirmed).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0800-01-01:0":{"b": ["Ibrāhīm b. al-Aghlab became governor: the Aghlabids in Kairouan", "f7279ba9"], "d": ["Hārūn al-Rashīd appointed Ibrāhīm b. al-Aghlab governor of Ifriqiya; the Aghlabids (800-909) made Kairouan their capital.", "3b6e9426"]},
"OLAYLAR_KURULUS_GERI_1021:0909-01-01:0":{"b": ["The Fatimids took Kairouan; the Aghlabids came to an end", "021693e0"], "d": ["In 909 Ziyādat Allāh III fled to Egypt; Kairouan passed to the Fatimids.", "a6422efd"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["The Buyid Ahmad (Muʿizz al-Dawla) entered Baghdad; the city passed to Buyid rule", "31accd4a"], "d": ["Ahmad entered Baghdad on 11 Jumādā I 334 (19 December 945); the caliph al-Mustakfī made him amīr al-umarāʾ, and the city passed to the rule of the Buyids (Kufa also came under Buyid rule 945-1055; for Kufa the day was taken from the neighbour, Baghdad).", "11f31be7"]},
"OLAYLAR_KURULUS_GERI_1021:0969-01-01:0":{"b": ["The khutba was read in the name of the Fatimids in Mecca (358/969)", "3f069fea"], "d": ["The emir of Mecca, Jaʿfar b. Muhammad, had the khutba read in the name of the Fatimids (358/969, year precision); the Fatimids as the suzerain state.", "2256892c"]},
"OLAYLAR_KURULUS_GERI_1021:0972-10-02:0":{"b": ["The Zirids in Kairouan (Buluggīn b. Zīrī governor of Ifriqiya)", "5494e662"], "d": ["In the name of the Fatimid caliph, Buluggīn b. Zīrī governed Ifriqiya; the Zirids (972-1057) ruled Kairouan (TDV gives the year, the day is from the künye f).", "ffcba4c5"]},
"OLAYLAR_KURULUS_GERI_1021:1057-01-01:0":{"b": ["The Hilali plunder: al-Muʿizz b. Bādīs withdrew to Mahdia, Zirid rule in Kairouan came to an end", "4dbbdff5"], "d": ["Around 449 (1057) the Hilalis plundered Kairouan; the Zirids withdrew to Mahdia; the owner of the city until 1229 cannot be traced year by year in the sources (declared gap).", "8bebfdc7"]},
"OLAYLAR_KURULUS_GERI_1021:1085-05-25:0":{"b": ["Alfonso VI entered Toledo: the city passed to Castilian rule", "3b72bb5f"], "d": ["Treccani: Alfonso VI entered Toledo on 25 May 1085; two years later the city became the capital of Castile (TDV Tuleytula gives only the year: 478/1085; the surrender day of 8 May 1085 is recorded separately in the tail chronology).", "fa2c9677"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["The retaking of Damietta from the French — the evacuation of the Lesbe fortress", "06b1e7b0"], "d": ["A force under İbrahim Pasha from the grand vizier's army was sent to Damietta. On the morning of 14 May, while the assault on the Lesbe fortress that protected Damietta was being prepared, it was seen that the fortress had been evacuated by the French and the garrison had withdrawn; two small forts dependent on it were also taken. Damietta became the second Nile-mouth city to pass out of French control after Rosetta, which had fallen in April.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["The taking over of Cairo from the French — Belliard's capitulation", "7a11bb5e"], "d": ["During the joint Ottoman and British operation directed at Egypt, General Belliard, commander of the French forces in Cairo, signed the capitulation. Together with Cairo, Suez, which the French had seized in November 1798, also passed out of French control. The close of the occupation would be completed two months later in Alexandria, and the evacuation from the country would continue until October.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["The taking over of Alexandria from the French — Menou's capitulation", "cd50663c"], "d": ["General Menou, commander-in-chief of the Army of the Orient, was besieged in Alexandria on 17 August; on 21 August the British took the fort of Marabout near the city, and on 31 August Menou signed the capitulation of the army. The return of the French troops to France began on 2 September. Thus the occupation that had begun with the landing at Alexandria in June 1798 ended in the city where it had begun.", "22e807c1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:0763-01-01:0":{"b": ["Stephen II, Duke of Naples, turned from Constantinople to Rome: the duchy became in effect independent", "5a181f23"], "d": ["The duchy of Naples, dependent on Byzantium, became in effect autonomous in 763 under Stephen II by turning to the Pope (the first duke, Basil, had been appointed in 661).", "4202f3af"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:0":{"b": ["Cosenza passed from Byzantium to the Normans: Duchy of Apulia and Calabria", "80b85c65"], "d": ["The duchy of Robert Guiscard (1059) included Calabria; Cosenza passed from Byzantium to the Norman duchy (the day of the conquest specific to the city was not read; year level).", "97fda44a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:1":{"b": ["Reggio Calabria passed from Byzantium to the Normans: Duchy of Apulia and Calabria", "221f6474"], "d": ["The duchy of Robert Guiscard (1059) included Calabria; Reggio passed from Byzantium to the Norman duchy (the day of the conquest specific to the city was not read; year level).", "31927a9e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:0":{"b": ["Brindisi passed from Byzantium to the Normans: Duchy of Apulia", "52c14154"], "d": ["With the Norman conquest of Bari in 1071, Byzantium's last stronghold in Italy fell; Brindisi, tied to the Bari chain, was joined to the duchy of Apulia (no dated sentence specific to the city was found).", "db68d985"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:1":{"b": ["Lecce passed from Byzantium to the Normans: Duchy of Apulia", "73da4722"], "d": ["With the Norman conquest of Bari in 1071, Byzantium's last stronghold in Italy fell; Lecce, tied to the Bari chain, was joined to the duchy of Apulia (no dated sentence specific to the city was found).", "e11ac323"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1099-01-01:0":{"b": ["The Compagna Communis was founded in Genoa: the city passed to communal government", "1cc30776"], "d": ["The notables of Genoa organized the government of the city as a commune by founding the Compagna Communis; the beginning of the Republic of Genoa.", "952b5184"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:0":{"b": ["Taranto passed from the Duchy of Apulia to the Kingdom of Sicily (Roger II)", "3ecf982e"], "d": ["In 1128 Roger II took the duchy of Apulia and Bohemond II's principality of Taranto/Otranto/Brindisi (May-June 1128, secondary); on the same day as the Bari and Salerno chains.", "b52e2957"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:1":{"b": ["Brindisi passed from the Duchy of Apulia to the Kingdom of Sicily (Roger II)", "6519178f"], "d": ["In 1128 Roger II took Brindisi in Bohemond II's principality of Taranto (secondary); on the same day as the Bari and Salerno chains.", "7adade28"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:2":{"b": ["Lecce passed from the Duchy of Apulia to the Kingdom of Sicily (Roger II; elder-brother center Bari)", "22cdacd2"], "d": ["Lecce changed hands, tied to the Bari chain, with the joining of the duchy of Apulia to the Kingdom of Sicily (1128); no dated sentence specific to the city was found.", "9c938986"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:3":{"b": ["Cosenza passed from the Duchy of Apulia and Calabria to the Kingdom of Sicily (Roger II)", "75da9e9c"], "d": ["Calabria became part of the Kingdom of Sicily with the passing of the duchy of Apulia and Calabria to Roger II (1128); no dated sentence specific to the city was found (elder-brother center Bari/Melfi chain).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:4":{"b": ["Reggio Calabria passed from the Duchy of Apulia and Calabria to the Kingdom of Sicily (Roger II)", "37e6922f"], "d": ["Calabria became part of the Kingdom of Sicily with the passing of the duchy of Apulia and Calabria to Roger II (1128); no dated sentence specific to the city was found (elder-brother center Bari/Melfi chain).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1143-01-01:0":{"b": ["The Roman Commune was founded: the senate was renewed (renovatio senatus), the Pope's temporal sovereignty was suspended", "b54d2c34"], "d": ["The people of Rome re-established the commune and the senate on the Capitol; under the influence of Arnold of Brescia, papal sovereignty was in effect not recognized until 1155 (künye f 1143, Treccani 1144).", "baeccd38"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1318-07-25:0":{"b": ["Jacopo I da Carrara was elected protector and governor of Padua: the Commune of Padua passed to a single lord", "b3fc0eae"], "d": ["The aristocracy of Padua elected Jacopo I da Carrara protector/governor for life (shortly after 25 July 1318); the commune passed to a single lord. The day is not certain, and the first day of the range was taken.", "aa9a4a3f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1351-05-01:0":{"b": ["Zurich joined the Confederation by perpetual alliance: the fifth member alongside Lucerne, Uri, Schwyz and Unterwalden", "78e9419b"], "d": ["On 1 May 1351 Zurich made a perpetual alliance with Lucerne, Uri, Schwyz and Unterwalden and became a member of the Old Swiss Confederacy.", "4646e7ae"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1506-11-11:0":{"b": ["Pope Julius II entered Bologna: the Bentivoglio lordship was abolished, the Papacy began direct rule", "dc4823a7"], "d": ["Pope Julius II entered Bologna with his army and expelled Giovanni II Bentivoglio; the city was attached to the Papal States.", "9afc6459"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1532-01-01:0":{"b": ["The communal liberty of Ancona came to an end: under Clement VII it came directly under papal sovereignty", "d2fbbb8f"], "d": ["The communal liberty of the Republic of Ancona came to an end in 1532, under Clement VII, when it passed under the direct sovereignty of the Papacy (year precision; day/month not read).", "518c4913"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1536-05-21:0":{"b": ["Geneva voted for the Reformation: the rule of the bishop and of Savoy came to an end, the Republic of Geneva was born", "dcb02e44"], "d": ["By a vote of the general council on 21 May 1536, Geneva adopted the Reformation; the city remained an independent republic at Bern's side but did not become a member of the Confederation.", "fd9e9db5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1540-01-01:0":{"b": ["The Baglioni lordship came to an end: Perugia came under the direct papal rule of Paul III", "3c57f2fe"], "d": ["At the end of the Salt War the Baglioni lordship was abolished and Paul III began the construction of the Rocca Paolina; the de facto independence of the Commune of Perugia came to an end (year precision; day not read).", "0a01ed80"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1739-10-17:0":{"b": ["Cardinal Alberoni occupied San Marino: papal rule was imposed", "4d3a4296"], "d": ["Cardinal Giulio Alberoni, legate of Ravenna, occupied San Marino with military force and tried to attach it to the Papacy; the people resisted through civil disobedience.", "79343d06"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1740-02-05:0":{"b": ["Pope Clement XII recognized the rights of San Marino: independence was restored", "0783c00e"], "d": ["Upon secret petitions the Pope recognized the rights of San Marino; the Alberoni occupation came to an end.", "d3268069"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-05-15:0":{"b": ["Napoleon entered Milan: Austrian rule came to an end", "adce9a6c"], "d": ["After the first victories of the Italian campaign, Bonaparte entered Milan on 15 May 1796; Lombardy passed out of Austrian hands.", "2a2ae65e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-06-23:0":{"b": ["Armistice of Bologna: Bologna and Ferrara fell into French hands", "5eed42c8"], "d": ["Pope Pius VI signed an armistice at Bologna; the legations of Bologna and Ferrara came under French control, and a heavy indemnity was paid.", "4447b7b3"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-12-27:0":{"b": ["The Cispadane Republic was proclaimed (Modena, Reggio, Bologna, Ferrara)", "f9ee3f5a"], "d": ["At the Congress of Reggio, Modena, Reggio, Bologna and Ferrara united and proclaimed the Cispadane Republic; the Este duchy in effect came to an end.", "0529810e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-02:0":{"b": ["Wurmser surrendered Mantua", "476b954d"], "d": ["At the end of a siege lasting months, the Austrian commander Wurmser surrendered Mantua to the French on 2 February 1797.", "68c18933"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-19:0":{"b": ["Treaty of Tolentino: the Pope ceded Bologna, Ferrara and the Romagna to France", "9868973b"], "d": ["Pius VI made peace with France at Tolentino; Bologna, Ferrara and the Romagna (Ravenna, Rimini) passed to the Cispadane Republic, which was under French tutelage.", "2d453d48"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-05-12:0":{"b": ["The Republic of Venice came to an end: the Great Council dissolved itself", "a03a1a31"], "d": ["Under Napoleon's pressure the Great Council dissolved itself on 12 May 1797 and Doge Manin resigned; the French occupation began, and the later fate of the Veneto was determined at Campo Formio.", "cd4ad1df"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-07-09:0":{"b": ["The Cisalpine Republic was ceremonially founded in Milan: Lombardy, Mantua, Bergamo, Brescia and the Cispadane territories united", "b8338ba1"], "d": ["Lombardy, Mantua, Bergamo, Brescia, the Cispadane Republic (Modena, Reggio, Bologna, Ferrara) and the Romagna, all conquered by Napoleon, united in a single state.", "ed1bf80a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-02-15:0":{"b": ["The Roman Republic was proclaimed: papal rule was interrupted", "30145500"], "d": ["Under Berthier's occupation of Rome, the Roman Republic was proclaimed on the Capitol; Pope Pius VI was sent into exile.", "99f72dba"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-04-26:0":{"b": ["Geneva was annexed to France: the Republic of Geneva came to an end, the department of Léman was formed", "cbee4241"], "d": ["A treaty of annexation was signed with France; Geneva and its surroundings were joined to the French Republic as the department of Léman.", "3c1c8254"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-12-09:0":{"b": ["Piedmont was taken under French administration; Charles Emmanuel IV withdrew to Sardinia", "d4e022ae"], "d": ["In December 1798 the House of Savoy gave up mainland Piedmont and withdrew to the island of Sardinia, and Turin came under French control (official annexation 11 September 1802).", "dcb442ed"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-01-23:0":{"b": ["The Parthenopean Republic was proclaimed: the French army entered Naples, a sister republic replaced the Bourbon kingdom", "f657b307"], "d": ["Championnet's army took Naples; the Bourbon Ferdinand IV had fled to Palermo. The actual control of the republic is largely the city of Naples and its surroundings (the provinces remained pro-Bourbon).", "9e17f40e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-04-27:0":{"b": ["After Cassano the Austro-Russian army brought down the Cisalpine Republic", "5b6ad0d8"], "d": ["After the Battle of Cassano, Austro-Russian forces entered Lombardy; the Cisalpine Republic collapsed.", "09c16276"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-06-13:0":{"b": ["Cardinal Ruffo retook Naples: the Parthenopean Republic came to an end, Bourbon rule returned", "04d437c6"], "d": ["The Sanfedist army entered Naples under Cardinal Ruffo; the republican forts surrendered shortly afterwards, and the kingdom returned to Bourbon rule.", "775b1d4c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-09-30:0":{"b": ["Neapolitan troops entered Rome: the Roman Republic came to an end, papal rule returned", "a367ed6a"], "d": ["Neapolitan forces occupied Rome and the Roman Republic came to an end; the actual return of papal rule was completed in July 1800 with the entry of Pius VII.", "6ee7e336"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1800-06-04:0":{"b": ["After Marengo Napoleon re-established the Cisalpine Republic", "c03710d1"], "d": ["After the victory of Marengo, Napoleon returned to Milan and re-established the Cisalpine Republic (infobox: 2 June).", "df5345f5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1802-10-09:0":{"b": ["Duke Ferdinand I of Parma died: the duchy passed to French administration", "0e6bc319"], "d": ["Ferdinand, who had ceded the duchy to France by the Treaty of Aranjuez (1801), died on 9 October 1802; Parma and Piacenza came under French administration (official annexation 1808).", "5d07614d"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-06-04:0":{"b": ["Napoleon accepted the annexation of Liguria: Genoa was joined to the French Empire", "ecc8047e"], "d": ["The Ligurian Senate approved the annexation on 25 May 1805; Napoleon accepted it on 4 June 1805, and the Ligurian Republic came to an end.", "054ecfb4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-12-26:0":{"b": ["Treaty of Pressburg: Veneto, Istria and Dalmatia passed to the Kingdom of Italy", "94ff5a04"], "d": ["Austria ceded the former Venetian lands (Veneto, Friuli, Istria, Dalmatia) to Napoleon's Kingdom of Italy.", "5e25f259"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1807-12-10:0":{"b": ["The Kingdom of Etruria came to an end: Tuscany came under French occupation", "f4c9b9ef"], "d": ["Napoleon dissolved the Kingdom of Etruria; the regent queen left Florence, and in 1808 Tuscany was joined to France as the departments of Arno, Ombrone and Méditerranée.", "d2e2917f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1808-04-02:0":{"b": ["Napoleon joined the Marche to the Kingdom of Italy: Ancona became the center of the Metauro department", "2314868d"], "d": ["By decree no. 158 issued from Saint-Cloud, the Marche, belonging to the Papacy, was added to the Kingdom of Italy; the decree of 20 April 1808 established the departments of Metauro (Ancona), Musone (Macerata) and Tronto (Fermo).", "10d2d834"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1809-05-17:0":{"b": ["Napoleon joined the papal lands to the French Empire", "f4ba4cb8"], "d": ["Rome and the remaining territories of the Papal States (including Umbria) were annexed to France; Pius VII was arrested.", "b281eb72"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1810-02-28:0":{"b": ["Treaty of Paris: Bavaria ceded South Tyrol (Trento) to Napoleon, the region was joined to the Kingdom of Italy", "01762dda"], "d": ["The King of Bavaria ceded South Tyrol to Napoleon; the department of Alto Adige, centered on Trento, was formed and attached to the Kingdom of Italy (partition of 9 June 1810).", "1ceb45f7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-10-15:0":{"b": ["Austrian troops entered Trento: the Alto Adige department of the Kingdom of Italy collapsed", "1870c11e"], "d": ["Austrian troops under General Fenner entered Bolzano on 11 October and Trento on 15 October 1813; a provisional Austrian administration was established on 10 December 1813.", "66916a3e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-12-31:0":{"b": ["The French garrison withdrew from Geneva: the Republic of Geneva was re-established", "b06ab617"], "d": ["With the approach of Austrian troops, French rule collapsed; on 31 December 1813 the Republic of Geneva was restored, and in 1814-1815 it joined the Confederation.", "0fe9a364"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-11:0":{"b": ["Fontainebleau: Parma and Piacenza were given to Marie Louise", "909f6ba0"], "d": ["With Napoleon's abdication, Parma, Piacenza and Guastalla were given to his wife Marie Louise (actual transfer to her rule 1816).", "6d19058c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-16:0":{"b": ["Eugène signed an armistice at Mantua: the Kingdom of Italy collapsed, Austria took Milan", "f658fa23"], "d": ["With the Armistice of Schiarino-Rizzino, Napoleon's Kingdom of Italy in effect came to an end; Lombardy and the Veneto came under Austrian control (official transfer by the Final Act of Vienna, 9 June 1815).", "a0989fbc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-20:0":{"b": ["Victor Emmanuel I returned to Turin: the House of Savoy was restored", "32499bf1"], "d": ["French rule in Piedmont came to an end; Victor Emmanuel VII returned from Sardinia to Turin and put the 1770 constitution back into force.", "a2ce4d35"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-24:0":{"b": ["Pius VII returned to Rome: papal rule was re-established", "d0b4171c"], "d": ["After five years of captivity, Pope Pius VII entered Rome in triumph on 24 May 1814; the Papal States were restored (the Legations were returned in 1815).", "d93a4a6c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-07-14:0":{"b": ["Francis IV took over the government as Duke of Modena: the Este-Habsburg duchy was restored", "e06a5823"], "d": ["When Napoleon's Kingdom of Italy dissolved, the Duchy of Modena and Reggio was returned to the Habsburg-Este dynasty (Francis IV).", "daa659f4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-09-01:0":{"b": ["Ferdinand III, Grand Duke of Tuscany, was restored", "f6f21c83"], "d": ["With the end of the Napoleonic period, Ferdinand III of the Habsburg-Lorraine dynasty resumed the government of Tuscany (September 1814).", "a310e5c7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1848-03-22:0":{"b": ["Manin took the Venice Arsenal: the Republic of San Marco was proclaimed", "154bae0a"], "d": ["Under the leadership of Daniele Manin, Venice rose against Austrian rule and proclaimed the Republic of San Marco; Austrian troops withdrew from the city on 26 March.", "476c31cc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-02-09:0":{"b": ["The Roman Republic was proclaimed: with the Pope having fled to Gaeta, the Constituent Assembly established the republic", "282025d1"], "d": ["The triumvirate headed by Mazzini proclaimed the republic in Rome; papal rule was suspended.", "03575b62"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-07-03:0":{"b": ["The French army entered Rome: the Roman Republic came to an end, papal rule returned", "2e5ed341"], "d": ["Oudinot's French expeditionary force took Rome; Garibaldi withdrew and the republic fell (Wikipedia 2 July, most sources 3 July).", "bbaabf25"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-08-22:0":{"b": ["Venice surrendered to Austria: the Republic of San Marco came to an end", "f5e5de33"], "d": ["At the end of the siege, cholera and famine, Manin surrendered the city; Austrian rule returned (the infobox says 27 August).", "70a16b74"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1943-09-23:0":{"b": ["Mussolini founded the Salò Republic: northern Italy became the Italian Social Republic under German protection", "9248adee"], "d": ["Mussolini, rescued by the Germans, founded the Italian Social Republic (Salò), comprising northern and central Italy, under German military control; the Kingdom and the Badoglio government remained in the south.", "cd238153"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:536-12-09:0":{"b": ["Belisarius entered Rome: Rome passed from Ostrogothic rule to Byzantium", "f74ca8a4"], "d": ["In the Gothic War, Belisarius's army entered Rome on 9 December 536; the city was taken from the Ostrogoths and attached to Byzantium (Totila would retake it in 546).", "75602e01"]},
"OLAYLAR_OK104:1284-01-01:0":{"b": ["Byzantium retook Krujë (Akçahisar), Durrës and Vlorë from the Angevins", "4e1a9810"], "d": ["Durrës and Krujë, which Charles of Anjou had taken in 1271-1272, were retaken after Charles's death by the Byzantine emperor Andronikos II (TDV Kruya: 'he retook Valona, Durrës and Krujë'). Only the year is known; the day is unconfirmed.", "eef9a5c3"]},
"OLAYLAR_OK104:1304-01-01:0":{"b": ["Philip of Taranto brought Durrës (Durazzo) under Angevin rule again", "be355b48"], "d": ["In Durrës, which had passed to Byzantium in 1284, Philip, Prince of Taranto, son of King Charles II of Naples, re-established Angevin rule in 1304; the Kingdom of Albania (Regnum Albaniae) was proclaimed anew, but in Philip's lifetime it remained limited to this city (Europange: 'The kingdom of Albania was re-established in 1304, when Philip of Taranto was able to restore the Angevin regime in Durazzo'). In 1332 his son Robert gave Durrës to John of Gravina in exchange for the Principality of Achaea; the duchy of Durazzo remained in Angevin hands until Charles Thopia took the city in 1368. Only the year is known; the day is unconfirmed.", "f918f799"]},
"OLAYLAR_OK104:1344-01-01:0":{"b": ["The Serbs captured Krujë (Akçahisar), Berat and Vlorë", "cef4ca73"], "d": ["TDV Kruya: 'in 1344 the Serbs captured Krujë, Berat and Vlorë'. TDV Arnavutluk says that Dušan occupied Albania between 1343 and 1346, and that with the collapse of his empire in 1355 the local lords grew stronger. Only the year is known; the day is unconfirmed.", "0ab9765f"]},
"OLAYLAR_OK104:1392-01-01:0":{"b": ["Durrës (Durazzo) passed from the Thopias to Venice", "da0afe63"], "d": ["Charles Thopia's son George Thopia ceded Durrës, which Charles had taken in 1368, to Venice in 1392 (TDV Draç: 'was ceded to Venice by Thopia's son George', no year); Venice confirmed the city's statutes in August 1392. Venice held Durrës until the Ottomans took it in 1501. Only the year is known; the day is unconfirmed.", "072ad728"]},
"OLAYLAR_OK104:1393-05-01:0":{"b": ["The surrender of Lezhë (Alessio) by the Dukagjins to Venice", "2cab90db"], "d": ["Paul and Lek Dukagjin, who had held Lezhë (Alessio) since 1387 as the center of the Albanian Principality of Dukagjin, seeing that they could not defend this port at the mouth of the Drin against Ottoman pressure, ceded the fortress to Venice and withdrew to the mountainous region east of the city. The city then remained in Venetian hands until it was taken in 1478, during Mehmed the Conqueror's Shkodër campaign, by Dâvud Pasha, the beylerbeyi of Rumelia — both Skanderbeg's convening of the anti-Ottoman alliance (Lidhja e Lezhës) here on 1 March 1444 and his death here on 17 January 1468 took place in a Venetian fortress.", "a7df86bc"]},
"OLAYLAR_OK104:1443-01-01:0":{"b": ["Skanderbeg captured Krujë (Akçahisar) — the Albanian resistance begins", "8f007d17"], "d": ["After the defeat at Izladi (TDV Kruya: 847/1443), Skanderbeg occupied Krujë. After the death of his father Gjon Kastrioti in 1437, the Ottomans had given the city not to him but to Hasan Bey, whom they appointed. Only the year is known; the day is unconfirmed.", "d5be30c0"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Poland's advance of the Dnieper line — the founding of Kremenchuk", "1bc86966"], "d": ["Poland-Lithuania founded a new frontier town at the central Dnieper crossing, the passage point of Crimean raids; twenty-five years later a fortress was added there. Thus Poland's line of control descended to the northern bank of the Zaporozhian steppe, and for the first time this crossing of the river was tied to the continuous garrison of a state. In the following century the town would pass into the Hetmanate order as a Cossack regimental centre.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["The appearance of Uman on Poland's Yedisan frontier line", "2e6551ab"], "d": ["Uman first entered the records as a settlement at the southeastern tip of the Bratslav region under Polish administration. Its location lay on the northward raiding routes of the Crimean Khanate; the settling of a permanent town there shows that the empty steppe belt between the two states had begun to narrow from the north. For the next two centuries the city would remain the southernmost large Polish settlement on this line.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["The advance of Muscovy's steppe defence line — Chuhuiv", "c68d36d3"], "d": ["The Cossack leader Yakiv Ostrianyn and his men, who took refuge in Muscovy after their uprising in Poland, founded a frontier settlement on the Donets. This was one of the first great leaps toward the steppe of the defence line Muscovy had built against Crimean raids; over the following half century, towns such as Sumy, Izium and Bakhmut would arise one after another on the same line. The settlement continued as the seat of a company attached to the Kharkiv regiment until 1765.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["The founding of Sloboda Ukraine — Sumy and the belt of steppe settlement", "ab7abf59"], "d": ["Peasants and Cossacks from the Bila Tserkva regiment in Right-Bank Ukraine, under Colonel Herasym Kondratiev, founded a new town on the Psel; four years later the Muscovite voivode fortified the fortress. This wave of migration is the beginning of the Sloboda Ukraine order, which opened the empty steppe on Muscovy's southern border to settlement: tax exemption was granted to those who came, and border watch duty was expected in return. From 1658 to 1765 Sumy was the seat of the regiment bearing its own name.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Construction of Yenikale — the locking of the Strait of Kerch", "d9067015"], "d": ["After the cession of Azak to Russia in 1700, the only gate by which the Black Sea opens to the Sea of Azov became a strategic frontier line. The Ottoman Empire had a new fortification built at the locality of Akıntı Burnu, ten kilometres northeast of the city of Kerch, and brought the passage of the strait within cannon range; the fortress was given the name Yenikale, which is simply what it means. For seventy years the fortress remained the eastern lock of Crimea, and with Kerch it was ceded to Russia by the nineteenth article of the Treaty of Küçük Kaynarca in 1774.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Fortress of St Elizabeth — Russia's southern border reaching the Ottoman-Crimean raiding line", "b9097272"], "d": ["Russia built a new fortress bearing the name of St Elizabeth on the land of the Zaporozhian Cossacks. The stated reason for the fortress was to protect the Balkan settlers placed in New Serbia from Ottoman and Crimean raids; that is, the Russian frontier line descended for the first time to the middle of the steppe, right onto the raiding routes. This forward outpost became the starting point of the northern Black Sea expansion that would begin twenty years later with Küçük Kaynarca.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["Second Treaty of Erzurum — the Shatt al-Arab border and the abandonment of the Khuzestan coast", "5d1f9103"], "d": ["The Ottoman-Iranian border dispute, which had remained unresolved for more than a century, was settled by the second treaty, signed in Erzurum after long negotiations conducted under British and Russian mediation. The whole of the Shatt al-Arab waterway remained Ottoman; in return, the settlements on the eastern bank of the river — including the port of Muhammara and the island of Abadan opposite it — were left to the Qajars. Thus the coastal strip of Khuzestan, which had been considered under Ottoman administration since the annexation of Basra in 1546, was lost three hundred years later. Mehmed Hurşid Pasha, a member of the boundary commission set up to mark on the ground the line drawn by the treaty, travelled through the region between 1848 and 1852 and wrote the Seyâhatnâme-i Hudûd.", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Withdrawal from Tabriz — the end of a week-long occupation and the return via Kars and Bayburt", "fd1542e3"], "d": ["Yavuz Sultan Selim, who entered Tabriz on 6 September after the victory of Chaldiran, stayed in the city for about a week; he had Shah Ismāʿīl's treasury and some of the city's artisans and scholars, together with their families, transferred to Istanbul. Although he wished to spend the winter in Karabakh and continue the campaign the following year, he gave up this plan in the face of the Janissaries' opposition, and the army turned back via Kars and Bayburt. Thus Tabriz did not remain in Ottoman hands: Chaldiran was a victory in the field, while a lasting territorial gain came the following year with the campaign of Kemah, Diyarbekir and Eastern Anatolia.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["The incorporation of Nusaybin, Derik and Silopi into the Ottoman realm — the southern branch of Diyarbekir", "c3621d22"], "d": ["After the surrender of Âmid and the establishment of the beylerbeyilik of Diyarbekir, Nusaybin, Derik and Silopi, south of the Mardin plain, also passed under Ottoman administration when İdrîs-i Bitlisî won over the Kurdish beys of the region. These places were organised as the nahiye and kaza centres of the new beylerbeyilik; some, such as Cizre, were left to their local beys with the status of yurtluk-ocaklık. Thus the Eastern Anatolian campaign that had begun after Chaldiran reached Upper Mesopotamia.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Declaration of Czechoslovak independence — the first successor state of the Habsburg legacy", "8f40155f"], "d": ["Following the loss of Austria-Hungary's strength in the war and the strikes, demonstrations and uprisings within the country, the National Council declared the independence of Czechoslovakia on 28 October 1918. A provisional national assembly was formed on the basis of the 1911 election results, and on 14 November 1918 the government with Masaryk as its head took office. The new state gained its place in international law with the Treaty of Saint-Germain-en-Laye (10 September 1919). On the map, Czechoslovakia appears on 11 November 1918; the declaration of independence precedes this by two weeks.", "80a8405f"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Proclamation of the State of Slovenes, Croats and Serbs — the Croatian Sabor severed the Habsburg ties", "2e5ae559"], "d": ["On 29 October 1918 the Croatian Sabor declared that Croatia, Slavonia and Dalmatia had severed all their constitutional ties with Austria-Hungary; on the same day the founding of the State of Slovenes, Croats and Serbs was celebrated in Ljubljana. In Bosnia-Herzegovina, the Austro-Hungarian administration transferred authority to the government of the National Council on 1 November 1918. This state lasted until the Kingdom of Serbs, Croats and Slovenes was proclaimed in Belgrade on 1 December 1918.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Founding of the Republic of Austria — the German core of the Habsburg legacy", "1ec8b06f"], "d": ["When it was announced on 29 October that Czechoslovakia had been founded in Prague and the State of Serbs, Croats and Slovenes in Zagreb, the German Austrians also founded the Republic of Austria on 30 October. On the same day the Ottoman Empire was signing the Armistice of Mudros; the ends of the two empires fell side by side on the calendar.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Aster Revolution — Károlyi became prime minister, the monarchy in Hungary began to dissolve (the people's republic was proclaimed on 16 November)", "d7780d2e"], "d": ["When the defeat of the Central Powers became clear, anti-monarchical sentiment grew stronger in Hungary and a shift to the left took place. On 31 October 1918, as a result of the \"Aster Revolution\", the radical-minded Count Mihály Károlyi became prime minister, and then the people's republic was proclaimed; Károlyi was elected president in his own right on 11 January 1919.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Armistice of Villa Giusti — Austria-Hungary laid down arms, Trento and Trieste passed to Italy", "75da65fb"], "d": ["Emperor Karl's signing of an armistice with the Italians at Villa Giusti on 3 November 1918 accelerated the break-up of the empire. TDV explicitly records this day as Austria's laying down of arms: \"Austria, having accepted defeat, laid down its arms on 3 November, and Germany on 11 November.\" On the map, Trento and Trieste pass from Austria to Italy on this day — this is the first territorial transfer of the dissolution visible on the map.", "a86d1725"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Poland's independence — the Regency Council gave command of the army to Piłsudski", "e8b546cf"], "d": ["Józef Piłsudski returned to Warsaw on 10 November 1918. On 11 November the Regency Council gave him command of the army; a few days later it also left to him the task of forming the national government.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["The Serbian army occupied Pécs (Peçuy) — the Serbian occupation of Baranya began", "68f0695f"], "d": ["Pécs, of strategic importance because of its coal mines, came under Serbian occupation on 14 November 1918. The Serbian occupation of Pécs and the province of Baranya lasted until August 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["The Serbian army occupied Timișoara (Temeşvar) — the Serbian military administration of the Banat began", "3cc85350"], "d": ["Serbian troops occupied Timișoara on 14 November 1918, dispersed the national guards and assumed the military, and shortly afterwards the civil, administration of the Banat. French troops also entered the city in early December; Romanian administration was established only in July-August 1919.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Serbian troops entered Szigetvár — the occupation of southern Somogy", "a06b1907"], "d": ["Advancing north of the line drawn by the Belgrade military convention, 220 soldiers of the Serbian army under the command of Obren Petrović entered Szigetvár, the district seat of Somogy, on the night connecting the 18th to the 19th; the villages of the district were also held by this force. The occupation lasted until August 1921; Trianon left Szigetvár in Hungary.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Founding of the Kingdom of Serbs, Croats and Slovenes and of Greater Romania — on the same day, two states", "6fd85345"], "d": ["As a result of the union with Serbia of the Slavs who had separated from the empire with the dissolution of Austria-Hungary, the Kingdom of Serbs, Croats and Slovenes was founded on 1 December 1918; about 250,000 km² of territory and a population of 12,000,000. Its foundation had been laid in the Corfu Declaration of 20 July 1917, and the assemblies of Podgorica on 26 October, Bosnia-Herzegovina on 28 October and Novi Sad on 25 November had taken decisions to join. On the same day Greater Romania came into being with the joining of Transylvania, Bukovina and Bessarabia by the decision of their own peoples. On the map, the territories of the Kingdom of Serbia pass to Yugoslavia.", "4565e7a6"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["The Romanian army entered Brașov (Brassó) and was welcomed with a ceremony", "4a917d27"], "d": ["The Romanian army entered Brașov in December 1918; the city's Romanian notables welcomed the army and General Berthelot with a ceremony.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["The Italian army occupied Knin", "7949dd0f"], "d": ["The Italian army occupied Knin on 19 December 1918. The occupation lasted until 4 April 1921, when the Italian army withdrew from the city after the Treaty of Rapallo.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Czechoslovak troops took Košice (Kassa)", "0989490f"], "d": ["When the 30th Infantry Regiment, bearing the name of Alois Jirásek, occupied the city on 29 December 1918, Košice was effectively joined to the Czechoslovak Republic.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["The Romanian army entered Szatmár (19 April) and Oradea (Varad, 20 April)", "3ee2bd72"], "d": ["On Easter Saturday, 19 April 1919, in Satu Mare, a local delegation headed by Dr. Ilie Carol Barbul welcomed the first patrol of the 2nd Cavalry Division under the command of Colonel Ressel at the bridge over the Someș. The next day, 20 April 1919, Romanian troops under the command of General Traian Moșoiu entered Oradea.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Treaty of Versailles — the return of Alsace-Lorraine to France passed into law", "3babdfcb"], "d": ["The Paris Peace Conference convened on 18 January 1919, and the Treaty of Versailles was signed with Germany on 28 June. Article 51 of the treaty returned Alsace-Lorraine (Strasbourg, Metz, Colmar, Mulhouse), which had been German since 1871, to French sovereignty — but it tied the transfer not to the day of signature but, retroactively, to the armistice of 11 November 1918. The same series of conferences produced Saint-Germain with Austria (10 September 1919), Neuilly with Bulgaria (27 November 1919), Trianon with Hungary (4 June 1920) and Sèvres with the Ottoman Empire (10 August 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Romanian troops reached Lugoj (Lugos) — Romanian administration in the east of the Banat", "f65fc73c"], "d": ["The train carrying the Romanian troops reached Lugoj at 2 p.m. on 22 July 1919; the people of the city welcomed the army at the station, the prefect of Caraș-Severin, George Dobrin, delivered the welcoming speech, and General Jitianu replied. Romanian administration was established in July 1919 in the part of the Banat that fell to Romania; the legal transfer took place with the Treaty of Trianon in 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["The Romanian army entered Timișoara (Temeşvar) — Romanian administration was established in the city", "8728e1d1"], "d": ["On the morning of 3 August 1919, the first units of the Romanian army under the command of Colonel Virgil Economu entered Timișoara, which Serbian troops had entered on 14 November 1918 and French troops in early December, and Romanian administration was established in the city.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["The SHS army entered Prekmurje — Murska Sobota and Lendava left Hungarian administration", "21b2ba08"], "d": ["Troops of the Kingdom of Serbs, Croats and Slovenes entered Prekmurje, beyond the Mura river, on 12 August 1919; Hungarian administration in the region ended on that day. The legal transfer took place with the Treaty of Trianon in 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Treaty of Saint-Germain — Austria's reduction passed into law", "e7b722d5"], "d": ["After the war, Austria signed the Peace Treaty of Saint-Germain with the Allies. According to the treaty, Austria recognised the independence of Hungary, Czechoslovakia and Yugoslavia; it agreed not to unite with Germany without the consent of the League of Nations, to abolish compulsory military service and to limit the army to 30,000 men. This is also the document through which Czechoslovakia gained its place in international law. The transfer on the map had taken place a year earlier; this treaty registered it.", "482c2ef4"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Treaty of Neuilly — Bulgaria lost Western Thrace and the Aegean coast", "01f2b8c8"], "d": ["With the war ending in defeat, Tsar Ferdinand had been forced to ask for an armistice and abdicate in favour of his son Boris (29 September 1918). Under the Treaty of Neuilly, which ended the war, Bulgaria suffered a strategic loss of territory in favour of the Serbs, lost the whole of Western Thrace, had to cede its Aegean Sea coast to Greece, and confirmed the provisions of the Treaty of Bucharest that gave Southern Dobruja to Romania. On the map, the counterpart of this transfer is not on the day of the treaty but in May 1920, when the administration actually changed hands: Dedeağaç, Sofulu, Orestiada and Çirmen pass to Greece on 14 May, and Gümülcine, İskeçe, Dimetoka and Ferecik on 27 May.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Treaty of Trianon — Hungary lost two thirds of its territory", "84aff507"], "d": ["Under the Treaty of Trianon, signed three months after Horthy was made regent on 1 March 1920, Hungary suffered heavy losses of territory and people: two thirds of its territory of 283,000 km² excluding Croatia, and sixty percent of its population, including more than three million Hungarians, remained outside its borders, and its army was reduced to 35,000 men. On the map, the Hungarian Regency appears with these reduced borders; Transylvania and Upper Hungary also pass to the colours of Romania and Czechoslovakia on exactly this day.", "6073745e"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["The Banat was divided, Temeşvar was left to Romania (Trianon arts. 27/3 and 45)", "256b4aca"], "d": ["The Treaty of Trianon drew the Hungarian-Romanian border with art. 27/3, and with art. 45 Hungary renounced in favour of Romania all its rights and titles in the former monarchy's territories beyond this border; thus the union of Transylvania, the Banat, Crișana and Maramureș with Romania was recognised in international law. The Banat region was divided between Romania and Serbia; the city of Tımışvar was joined to the Kingdom of Romania. Romanian administration had been in effective operation in Temeşvar since 3 August 1919; the treaty put this situation into law.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["The Italian army withdrew from Knin", "a1d2e846"], "d": ["Following the Treaty of Rapallo, the Italian army withdrew from Knin on 4 April 1921; the occupation that had begun on 19 December 1918 came to an end.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Italy handed Šibenik over to the SHS Kingdom", "9d07b12a"], "d": ["The Italian occupation that had begun on 6 November 1918 ended on 12 June 1921 with a ceremony attended by the military representatives of Italy and the SHS Kingdom.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Serbian troops withdrew from Szigetvár — the Hungarian gendarmerie took over the town", "97781b77"], "d": ["Following the entry into force of Trianon, Serbian forces began to withdraw from Barcs and Szigetvár on 17 August and took away everything that could be moved. Around noon on 20 August, Hungarian gendarmerie units entered; in the afternoon the municipal council and officials took the oath, and at five o'clock the military handover took place in the town hall.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["The Serbian occupation of Pécs (Peçuy) ended — the Hungarian National Army entered the city", "f437115a"], "d": ["Serbian troops began to evacuate the region on 18 August 1921; on 20-21 August the administration of the city and province was handed over to representatives of the Hungarian government, and on 22 August units of the Hungarian National Army entered the city.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["The Austrian Bundesheer entered Burgenland — the territory Trianon left to Austria was actually taken over", "7bfd6915"], "d": ["Trianon (1920) and Saint-Germain (1919) had left the German-speaking strip of Western Hungary to Austria; the first attempt at takeover on 28 August 1921 failed because of the resistance of Hungarian irregular units. After the Venice Protocol (13 October 1921), the Allied General Commission approved the entry of the Bundesheer on 11 November, and the takeover of northern Burgenland began two days later; the south was taken over on 6 December 1921, and the Sopron region remained in Hungary by plebiscite.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["Constantinople was inaugurated with a ceremony; the centre of the empire effectively shifted to the east", "e4d78842"], "d": ["The new capital founded by Constantine I was inaugurated with a ceremony on 11 May 330; Constantinople became the capital of the Byzantine (Eastern Roman) Empire.", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["The commander Jawhar al-Ṣiqillī entered Fustat and conquered Egypt; the Ikhshidids came to an end", "fd0410b1"], "d": ["In the name of the Fatimid caliph al-Muʿizz li-Dīn Allāh, Jawhar al-Ṣiqillī entered Fustat (17 Shaʿbān 358 / 6 July 969); Egypt passed from the Ikhshidids to the Fatimids, and the region where Cairo was to be founded came under Fatimid rule.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["Abū'l-Zawwād took Mosul; the Uqaylid dynasty was founded", "c3032f55"], "d": ["The Uqaylid Abū'l-Zawwād Muhammad b. al-Musayyab seized Mosul (380 / 990); the first day of the intersection of Hijri 380 ∩ 990, 31 March 990, was chosen (Hijri-Gregorian table, ±1-2 days); the day is not in the source.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["Afonso Henriques took Lisbon (Üşbûne); the city became the centre of the new Kingdom of Portugal", "24fddde8"], "d": ["Lisbon (Üşbûne) was taken from the Almoravids and passed into Portuguese hands (27 Jumādā I 542 / 24 October 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["James I took the city of Mallorca (Medina Mayurqa)", "47fd675c"], "d": ["James I, King of Aragon, took the city of Mallorca from the Muslims; Palma passed to the Crown of Aragon.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["Muhammad b. Yūsuf Ibn al-Aḥmar founded the Nasrid State in Granada", "23f66f33"], "d": ["The Nasrid State was founded with Granada as its centre (26 Ramadan 635 / 12 May 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["Agreement of Stensby: the Teutonic Order gave Northern Estonia (Reval) back to Valdemar II, King of Denmark", "b64c584d"], "d": ["By the agreement reached at Stensby in Sjælland in June 1238, Reval and Northern Estonia returned to Danish rule (the day is not in the source).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["Surrender agreement of Valencia: James I took the city", "977120b3"], "d": ["Valencia (Balansiya) passed to James I, King of Aragon, by a surrender agreement on 28 September 1238 (ceremonial entry on 9 October).", "c3465b4f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1054-11-05:0":{"b": ["The Uqaylid Quraysh has the khutba read in the name of Tughril Beg", "9fb65fc0"], "d": ["When Tughril Beg came to the region on account of his Baghdad campaign, the Uqaylid emir Quraysh had the khutba read in Tughril Beg's name in Sha'ban 446 / November 1054; after the killing of the Marwanid Sulayman he was gravely wounded in 447/1055.", "43df7313"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1064-01-01:0":{"b": ["Sultan Alp Arslan conquers Ani and gives the administration of the city to the Shaddadid Abu Shuja' Manuchihr", "f2c51a49"], "d": ["Alp Arslan, who conquered Ani in 456/1064, gave the administration of the city to Abu Shuja' Manuchihr, son of the Shaddadid Abu'l-Aswar Shavur. Manuchihr also added Kars to his lands and, fearing the approaching Byzantine army, had the walls damaged during the conquest repaired; as a Seljuk vassal he ruled at Ani for fifty-four years.", "6ddc5837"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:0":{"b": ["Alp Arslan captures Akhaltsikhe", "31b9964f"], "d": ["Akhaltsikhe, captured by Alp Arslan in Seljuk times (1068), came under Mongol rule in 1267-1268.", "f2d87d84"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:1":{"b": ["Alp Arslan and his allies raze Tbilisi and Kartli", "ff50ab5d"], "d": ["King Bagrat had recovered most of the fortresses; but in 1068 Alp Arslan and his allies razed Tbilisi and Kartli.", "753e1b62"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1073-01-01:0":{"b": ["Philaretos gathers Armenian priests at the city of Hunu (Elbistan region), has a catholicos elected and makes the city a catholicosal seat", "66005693"], "d": ["Taking advantage of the capture of Romanos Diogenes at the Battle of Manzikert in 1071, Philaretos gathered Armenian priests at the city of Hunu and had a catholicos elected. Thus the religious centre of an Armenian administration detached from Byzantium in the Marash-Elbistan-Malatya region was established.", "146d6889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1076-01-01:0":{"b": ["Sultan Malik-Shah comes as far as Kartli on a Georgian campaign; he entrusts responsibility for the region to Sarhang Savtegin", "830b979a"], "d": ["Malik-Shah, together with the Georgian commander Ioane, son of Liparit, who had remained loyal to him, campaigned against Georgia and came as far as Kartli, returned with many captives and much booty, and entrusted responsibility for the region to Sarhang Savtegin (1076). King Giorgi II won his wars with Savtegin and recovered some places.", "8a5912c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1078-07-14:0":{"b": ["Malik-Shah enters Georgia across the Araxes, plunders the Somkheti region and takes Ioane captive", "e62fd603"], "d": ["When King Giorgi II defeated Savtegin and recovered some places, Sultan Malik-Shah again set out on campaign and entered Georgia across the Araxes (471/1078-79); he plundered the Somkheti region and took Ioane captive, and returned, leaving Savtegin there with reinforcements. The emir Ahmad inflicted a heavy defeat on the king at Kouel and retook Kars.", "57f4ff76"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1083-01-01:0":{"b": ["Suleyman Shah I campaigns in Cilicia (Çukurova) and conquers Tarsus, Adana, Ayn Zarba and Mopsuestia", "c443ee8b"], "d": ["Suleyman Shah, who took the title of sultan in 1082, in the same year campaigned in Cilicia (Çukurova) and conquered the cities and fortresses of Tarsus, Adana, Ayn Zarba and Mopsuestia (1082-1083); then, at the invitation of the people of Antioch, he marched on Antioch with his sons Kilij Arslan and Dawud.", "e617bea2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-01-01:0":{"b": ["Chubuk Beg conquers Harput and founds the Chubukid Principality, embracing the Palu and Çemişgezek areas", "1f333d7d"], "d": ["During the Turkish raids directed at Anatolia after 1071, Chubuk Beg conquered Harput and founded the principality, which included the Palu and Çemişgezek areas. The principality's life was short; in the 1110s the Artuqid Belek took the city.", "5c951bf7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-04-29:0":{"b": ["Sultan Malik-Shah grants Bitlis and its region as iqta' to Dilmaçoğlu Mehmed Beg; the Dilmaçoğulları Principality begins", "7cdcb46f"], "d": ["After the Seljuk army's commander-in-chief Fakhr al-Dawla Ibn Jahir had taken Bitlis and its region, Sultan Malik-Shah granted it as iqta' to Dilmaçoğlu Mehmed Beg, who had taken part at Manzikert (478/1085). The principality ruled at Bitlis and Erzen from 1085 to 1394.", "da296fec"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-06-20:0":{"b": ["Muslim ibn Quraysh is defeated and killed by Suleyman Shah at Kurzahil", "fc482adb"], "d": ["Muslim ibn Quraysh, the Uqaylid who wished to found a united Arab state independent of the Great Seljuk Sultan, fought Suleyman Shah when he had the Antioch region plundered; he was defeated and killed at the place called Kurzahil (24 Safar 478 / 20 June 1085) and was buried at the Aleppo Gate.", "9f4da840"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1086-01-01:0":{"b": ["Sultan Malik-Shah comes to the Caucasus with a great army and brings the region wholly into submission", "79dd07e4"], "d": ["After King Giorgi II went to Isfahan and accepted Malik-Shah's suzerainty, Malik-Shah came to the Caucasus once more in 1086 with a great army and brought the region wholly into submission; Eastern Georgia had been given the name 'Didi Turkoba' (Great Turkish Time).", "a15ba581"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1095-01-01:0":{"b": ["Chaka Beg is killed at a banquet by his son-in-law Kilij Arslan I", "20cdcec9"], "d": ["Anna Komnene, who records that Chaka Beg was killed at a banquet by his son-in-law Kilij Arslan, gives 1097 as the date of death, but in view of the siege of Malatya in 1096 and the fall of Nicaea in 1097 this is wrong; the date of death must be 1095 (d. 488/1095 [?]).", "9a287bc8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1097-01-01:0":{"b": ["Kilij Arslan I besieges Malatya, which the Danishmendids also wished to take; he lifts the siege when the Crusaders turn towards Nicaea", "4f036db3"], "d": ["In the winter of 490/1097 Kilij Arslan marched on Malatya, on which the Danishmendids also had designs, and besieged the city for a time; on learning that the crusader armies had set out, he turned towards Nicaea, and Nicaea was lost (June 1097).", "4282aef8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1100-07-01:0":{"b": ["Gümüshtegin Ghazi ambushes and captures Bohemond, Prince of Antioch, and takes him to Niksar and imprisons him", "c43f8a71"], "d": ["Gümüshtegin the Danishmendid, besieging Malatya, ambushed and defeated the forces of Bohemond, Prince of Antioch, who had come to its aid; Bohemond was taken first to Sivas, then to Niksar, and imprisoned. The siege was lifted when Baldwin, Count of Edessa, approached.", "543833c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-06-23:0":{"b": ["Under the agreement between the Crusaders and Emperor Alexios Komnenos, Ankara is handed over to Byzantium", "d64f8668"], "d": ["During the First Crusade Raymond of Toulouse had occupied Ankara without meeting serious resistance, and the Turks in the fortress had been put to the sword; under the agreement between the Crusaders and Alexios Komnenos the city was handed over to the Byzantine Empire on 23 June 1101. Byzantine administration lasted about twenty years.", "f8a37732"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-08-01:0":{"b": ["Gümüshtegin, Kilij Arslan I and Ridwan rout the Lombard crusader army near Merzifon", "f2703ea8"], "d": ["The Lombard Crusaders, who had taken Ankara to free Bohemond from captivity and advanced towards Çankırı, were routed in August 1101 near Merzifon by the joint Turkish army of 20,000 men of Gümüshtegin, Kilij Arslan I, Ridwan, ruler of Aleppo, and Qaraja, emir of Harran.", "ddaa77e1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1102-01-01:0":{"b": ["Sökmen takes over Hasankeyf; the Hisn Kayfa branch of the Artuqids is founded", "07e6f974"], "d": ["On the death of Kurbuqa, emir of Mosul, Sökmen, who supported Musa in Mosul, helped him defeat Chökürmish in return for Musa's promise; when Musa was killed he went to Hasankeyf and took over the city. Thus the Hisn Kayfa branch of the Artuqids was founded (1102-1232).", "fccc615e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-01-01:0":{"b": ["Sökmen seizes Mardin after the death of his nephew Yaquti", "a5099d54"], "d": ["Mardin was under the rule of Sökmen's nephew Yaquti; taking advantage of the dispute that arose on his death, Sökmen seized the city in 1103 and bound to himself the greater part of the Diyarbakır region.", "43484644"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-08-01:0":{"b": ["Kilij Arslan I defeats Gümüshtegin Ghazi near Marash", "15ec5217"], "d": ["Gümüshtegin's release of Bohemond for ransom and the displeasure of Kilij Arslan, who demanded a share of the ransom, set the two allies against each other; Kilij Arslan routed Gümüshtegin near Marash.", "64f2df55"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-01-01:0":{"b": ["Gümüshtegin Ghazi dies at Sivas; his son Emir Ghazi becomes head of the Danishmendid dynasty", "75915f65"], "d": ["With Gümüshtegin's death the Danishmendids suffered a great shock; Malatya was surrendered to the Seljuks, and struggles for the throne arose among the members of the dynasty. His eldest son Emir Ghazi took over the government.", "f184fc73"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-05-07:0":{"b": ["Sökmen al-Qutbi and Chökürmish defeat and capture Baldwin du Bourg, Count of Edessa, and Joscelin near Harran (Balikh)", "5240d89c"], "d": ["The Crusader Baldwin du Bourg, Count of Edessa, and Joscelin, Count of Tell Bashir, were defeated by the Muslims and taken prisoner at the Battle of Harran on 9 Sha'ban 497 / 7 May 1104. Sökmen, the hero of the victory, fell ill and died in October of the same year.", "3b141414"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-10-01:0":{"b": ["Sökmen dies; his son Ibrahim succeeds him", "c40e3436"], "d": ["Sökmen, who fell ill shortly after the victory at Harran, died in October 1104; his son Ibrahim succeeded to the Hisn Kayfa branch, and on Ibrahim's death in 1108 his brother Dawud became Artuqid ruler.", "3fb73425"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:0":{"b": ["Muhammad Tapar routs the Georgian forces and destroys some cities", "372cbcc6"], "d": ["When King David launched a new invasion with a great army obtained from the Kipchaks and came as far as Ganja, the Seljuk Sultan Muhammad Tapar marched on Georgia, routed the Georgian forces and destroyed some cities (503/1110).", "f381ea2e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:1":{"b": ["Malik-Shah (Shahinshah), sent by the Great Seljuk Sultan Muhammad Tapar, takes the throne of the Anatolian Seljuks at Konya", "b8987991"], "d": ["After the death of Kilij Arslan I, because of the attacks of Alexios Komnenos, Muhammad Tapar sent Kilij Arslan's eldest son Malik-Shah to Anatolia; Malik-Shah came to Konya, took the throne and struggled with Alexios for six years.", "a8488c23"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1111-09-01:0":{"b": ["Sökmen al-Qutbi dies at Balis on the Euphrates; his son Zahir al-Din Ibrahim succeeds him", "510ea223"], "d": ["Sökmen, who had joined the army of Mawdud, son of Altuntegin, sent by Muhammad Tapar against the Crusaders, left the army when his illness grew worse and died at Balis in September 1111. His son Ibrahim became head of the Shah-i Armans (Ahlatshahs) and remained until 1126/1127.", "1ca34ea9"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1112-01-01:0":{"b": ["The Artuqid Belek takes Palu as his centre and seizes the lands of the Chubukids", "624ab91f"], "d": ["With Belek ibn Bahram's mastery of Harput in 1112, Palu passed from the Chubukids to the Harput branch of the Artuqids; Belek made it his capital.", "2d7c33df"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["David IV begins to settle 45,000 Kipchak families in Georgia", "559894b0"], "d": ["David agreed with 45,000 Kipchak families from the North Caucasus and the southern Russian steppes and brought them to Georgia from 1118, and with their help ended Seljuk rule at Tbilisi in 1121.", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["Emir Ghazi routs Roger, Prince of Antioch, and raids Antioch", "7bd138a2"], "d": ["Emir Ghazi raided Antioch in May 1119 with an army of 7,000 and routed Roger, Prince of Antioch, who marched against him.", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["Georgian King David routs the Muslim army at Didgori; the road to Tbilisi and Ani is opened", "03b19a6d"], "d": ["Against the great army obtained by the Georgian King David (David II in TDV; David IV the Builder in Georgian sources) from the Kipchaks, Tughril, ruler of Ganja, sent by Mahmud, the Seljuk Sultan of Iraq, the atabeg Gündoğdu, Dubays ibn Sadaqa, the Artuqid Ilghazi and Dilmaçoğlu Togan Arslan were defeated near Didgori on 12 August 1121. The Georgians then occupied Tbilisi, which had been under Islamic rule for centuries, and made it their capital.", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["Najm al-Din Ilghazi dies; his sons rule, Sulayman at Mayyafariqin and Timurtash at Mardin", "5e1a6c08"], "d": ["Ilghazi, the Artuqid ruler of Mardin, who had struggled hard against the Crusaders from Aleppo, fell ill during the Zardana Castle campaign with his nephew Belek and Tughtegin, atabeg of Damascus, and died on 19 November 1122. Of his sons, Sulayman ruled at Mayyafariqin and Timurtash at Mardin, and his nephew Sulayman at Aleppo.", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["Elbistan comes under Danishmendid rule when Emir Ghazi seizes the Malatya region", "5be35d74"], "d": ["Elbistan, which had been devastated by a great earthquake in 1114, came under Danishmendid rule in 1124 when the Danishmendid Emir Ghazi seized the Malatya region.", "a81725b1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:0":{"b": ["The Danishmendids take control of the Kastamonu region", "e1be4a42"], "d": ["In 1129 Ankara, Çankırı, Kastamonu and the Black Sea coasts came under Emir Ghazi's control; the Kastamonu region was added to the Danishmendid borders.", "df047345"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:1":{"b": ["The Danishmendids take control of Çankırı, Kastamonu and the Black Sea coasts", "db4c771a"], "d": ["The Danishmendids, the most powerful state in Anatolia in the time of Emir Ghazi, took control in 1129 of Ankara, Çankırı, Kastamonu and the Black Sea coasts; the greater part of the lands extending from Malatya to the Sakarya came under Danishmendid rule.", "1d1edb93"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1130-01-01:0":{"b": ["Shaddadid Fadl IV dies in the war undertaken by Kurti, emir of Erzen, to retake Dvin", "d8a7ad18"], "d": ["Fadl IV, who had retaken Ani after besieging it and added Ganja and Dvin to his lands, died in 524/1130 in the war undertaken by Kurti, emir of Erzen, to retake Dvin; his brother succeeded him, but his son Mahmud came to Ani and seized the government.", "7810bf30"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1131-01-01:0":{"b": ["The Saltukid Ziya al-Din Ghazi routs the Georgian King Ivane", "5ba067d6"], "d": ["Ziya al-Din Ghazi, who took part in the campaign mounted against the Georgians when in 1126 they passed İspir and Pasinler and came as far as Oltu, routed King Ivane in 1131.", "d91b0282"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1132-01-01:0":{"b": ["On Ziya al-Din Ghazi's death his nephew Izz al-Din Saltuk II becomes head of the Saltukid principality", "726791ef"], "d": ["Ziya al-Din Ghazi, a relative of the Artuqid Timurtash, died in 526/1132; his nephew Izz al-Din Saltuk II became head of the principality.", "a7412435"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1134-01-01:0":{"b": ["Emir Ghazi dies; his eldest son Malik Muhammad is proclaimed ruler at Malatya", "1cf04ea6"], "d": ["Emir Ghazi (Malik Ghazi), the most influential ruler in Anatolia, died in 528/1134. The diploma of investiture (manshur), golden staff and gifts sent by the Abbasid caliph al-Mustarshid-Billah and Sultan Sanjar were given to Malik Muhammad, and he was proclaimed ruler at Malatya. His brothers Ayn al-Dawla and Yaghan rebelled.", "e39192f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:0":{"b": ["Sultan Mas'ud takes Sivas; he takes Ankara, Çankırı and Kastamonu from the Danishmendids and gives them to his son Shahinshah", "cc439683"], "d": ["When the Danishmendids split into three branches on Malik Muhammad's death, the Anatolian Seljuk Sultan Mas'ud I marched on Sivas and took the city, and appointed his younger son Shahinshah as governor of Ankara, Çankırı and Kastamonu.", "6b775908"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:1":{"b": ["Sultan Mas'ud takes Kastamonu from the Danishmendids and leaves it to his son Shahinshah", "ae895779"], "d": ["Sultan Mas'ud, who had taken Sivas, gave Kastamonu together with Ankara and Çankırı to the governorship of his younger son Shahinshah.", "f8cfb811"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:2":{"b": ["Sultan Mas'ud takes Çankırı from the Danishmendids and leaves it to his son Shahinshah", "8047e8a8"], "d": ["Mas'ud I, taking advantage of the Danishmendid struggles for the throne, seized Ankara, Çankırı and Kastamonu and left the administration of these three cities to his son Shahinshah.", "07d66793"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-06-17:0":{"b": ["Sultan Mas'ud begins the three-month siege of Malatya; without result, he lifts it on 14 September 1143", "4c2d2d2b"], "d": ["Sultan Mas'ud, who had taken Sivas from the dynasty that had divided into three on the death of the Danishmendid Malik Muhammad (537/1142), besieged Malatya on 1 Dhu al-Hijja 537 / 17 June 1143; after three months without result, on 2 Rabi' al-awwal 538 / 14 September 1143 he lifted the siege and returned to Konya.", "2dc53da5"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-12-06:0":{"b": ["Malik Muhammad dies at Kayseri; the Danishmendids split into the Sivas, Malatya and Kayseri branches", "1ee92ff3"], "d": ["After Malik Muhammad, who according to Michael the Syrian died at Kayseri on 6 December 1143, his brother Yaghibasan established his rule at Sivas, his son Dhu al-Nun at Kayseri, and Ayn al-Dawla at Malatya and Elbistan; the Danishmendids divided into three branches and entered a destructive struggle among themselves.", "b07a9299"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1144-08-01:0":{"b": ["Dawud, Artuqid ruler of Hisn Kayfa, dies; his son Fakhr al-Din Qara Arslan succeeds him", "4782f166"], "d": ["Dawud, who had allied with the Mardin Artuqid Timurtash against Zengi, Atabeg of Mosul, died on 1 August 1144; his son Fakhr al-Din Qara Arslan came to an understanding with the Anatolian Seljuk Sultan Mas'ud I against Zengi.", "48a2c46f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1153-03-29:0":{"b": ["As a result of a plot by Fakhr al-Din Shaddad, emir of Ani, the Saltukid army is defeated by the Georgian King Demetrius; Izz al-Din Saltuk is taken prisoner", "f936d922"], "d": ["Shaddad, emir of Ani, who had sought Saltuk's daughter and been refused, announced that he wished to sell the city to Saltuk and enter his service; when Saltuk came with his army, he informed the Georgian king. The Saltukid army was heavily defeated by King Demetrius, and Saltuk was taken prisoner and freed for a ransom of 100,000 dinars.", "0d47e21f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-01-01:0":{"b": ["After Sultan Mas'ud's death, his Danishmendid son-in-law Yaghibasan is given Amasya, Ankara and Cappadocia", "295fac37"], "d": ["When Kilij Arslan II came to the throne on Mas'ud's death (1155), of Mas'ud's two sons-in-law belonging to the Danishmendid dynasty, Yaghibasan was given Amasya, Ankara and Cappadocia, and Dhu al-Nun the cities of Kayseri and Sivas; his brothers claimed the throne and rose in revolt.", "b6540bd8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-03-07:0":{"b": ["Fakhr al-Din Shaddad is taken prisoner by the Georgians; in Ani, after a revolt of Armenian nuns, his brother Fadl V is installed in his place", "2e64eb02"], "d": ["After the Georgian King Demetrius defeated the Saltukid army, Armenian nuns, reacting to Fakhr al-Din Shaddad's conduct, rose in revolt and installed his brother Fadl V at Ani in place of Saltuk (550/1155); Fadl V's emirate ended in 1161 with the surrender of Ani to the Georgian king.", "56cd50fc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-01-01:0":{"b": ["The Georgian King Giorgi captures Ani", "8081e228"], "d": ["The Georgian King Giorgi, after inflicting a heavy defeat in 1154 on the Saltukid ruler Izz al-Din Saltuk, captured the city of Ani in 1161; the Shaddadid emirate came to an end when the clergy rose up and surrendered the city to the Georgian king.", "357c7a97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-08-01:0":{"b": ["Shah-i Arman Sökmen, Izz al-Din Saltuk and Dawlatshah besiege Ani; the Muslims are defeated when Saltuk leaves the camp", "d651d8fe"], "d": ["After the Georgian King Giorgi captured Ani, Sökmen II, Shah of Ahlat, Izz al-Din Saltuk II, Fakhr al-Dawla Dawlatshah, lord of Erzen and Bitlis, and other Turkish emirs united and besieged the city. On King Giorgi's arrival, Saltuk left the camp without informing the other lords; the Muslims were defeated, very many were killed, and 9,000 were taken prisoner.", "2345b0e8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:0":{"b": ["The Georgians invade Dvin", "e8f2a041"], "d": ["The Georgians, who had taken Ani in 1161, invaded Kars and Dvin the following year; afterwards a joint campaign of the Muslim lords defeated Georgia in 1163.", "b28be1b3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:1":{"b": ["The Georgians invade Kars and Dvin", "a7388ca5"], "d": ["The Georgians, having taken Ani in 1161, invaded Kars and Dvin the following year; after killing a large number of Muslims and burning mosques and houses, they returned to Tbilisi.", "2a892f7b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-01-01:0":{"b": ["The united army of the Muslim lords defeats the Georgian King Giorgi; Giorgi is forced to return Ani", "346b30b1"], "d": ["The great army formed at the initiative of Sultan Tughril and Atabeg Shams al-Din Eldiguz inflicted a heavy defeat in 558/1163 on King Giorgi of Georgia, and Giorgi was forced to return Ani.", "a59e4ef4"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-07-01:0":{"b": ["The allied army of the Turkish lords defeats the Georgian army near Lukri Castle", "58d3a0d5"], "d": ["More than 50,000 mujahids, including Eldiguz, Sökmen, Izz al-Din Saltuk, Ibn Aqsunqur and Arslanshah, invaded Georgia; in July 1163 the Georgians were defeated around Lukri Castle, King Giorgi abandoned his baggage and fled, and was forced to return Ani.", "7ac70a0b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1164-08-04:0":{"b": ["Yaghibasan, Malik of Sivas, dies at Çankırı; a new struggle begins among the Danishmendids", "59448eb7"], "d": ["Yaghibasan, who had gone to Çankırı to obtain aid from the Seljuk Malik Shahinshah against Kilij Arslan II, died there on 4 August 1164; he was buried in the cemetery of the madrasa he had built at Niksar. Who succeeded him after his death is disputed.", "0efd18be"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1165-01-01:0":{"b": ["Kilij Arslan II takes the Darende and Gedük (Şarkışla) region from the Danishmendids", "917ee1e6"], "d": ["After Yaghibasan's death Kilij Arslan II, taking advantage of the struggle within the dynasty, annexed the Elbistan, Darende and Gedük region in 1165.", "7f39a47e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1168-01-01:0":{"b": ["Izz al-Din Saltuk II dies; his son Nasir al-Din Muhammad takes the throne", "40c0ab87"], "d": ["After Izz al-Din Saltuk's death in 563/1168, his son Nasir al-Din Muhammad took the Saltukid throne; the Great Mosque of Erzurum was built in his name in 1179.", "18b4b682"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1170-09-14:0":{"b": ["Kilij Arslan II rebuilds Aksaray and makes it a military base under the name Dar al-Zafar", "e0f2e591"], "d": ["Kilij Arslan II made the city of Aksaray, which he rebuilt in 566 (1170-71) and named Dar al-Zafar, a military base; he had mosques, zawiyas, madrasas and a caravanserai built, and settled there the ghazis and scholars he had brought from Azerbaijan.", "0ddd80f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1172-01-01:0":{"b": ["The people of Sivas rise up and kill Isma'il; with Nur al-Din Zengi's support Dhu al-Nun takes the Danishmendid throne at Sivas", "ab96caf2"], "d": ["In Sivas the people rose against Isma'il because of famine and his not distributing the stocks in the granaries; Isma'il and his wife were killed. The notables of the city invited Dhu al-Nun, who had taken refuge with Nur al-Din; with Nur al-Din's help Dhu al-Nun took the Danishmendid throne at Sivas in 567/1172, but soon afterwards, under pressure from Kilij Arslan II, fled to Niksar.", "374133e0"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:0":{"b": ["Kilij Arslan II takes Niksar from the Danishmendids and adds it to Seljuk rule", "e49e3971"], "d": ["In the summer of 1175 Kilij Arslan II seized Sivas, Niksar, Comana, Tokat and the other Danishmendid lands; Niksar, one of the Danishmendid centres where Yaghibasan lay buried in the cemetery of his madrasa, passed into Seljuk hands.", "aa58d509"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:1":{"b": ["Kilij Arslan II takes Tokat from the vanished Danishmendid province and adds it to Seljuk rule", "1894c403"], "d": ["After the death of Atabeg Nur al-Din Mahmud Zengi in 569/1174, Kilij Arslan II, disregarding the terms of the treaty, seized Sivas, Niksar, Comana, Tokat and the other Danishmendid lands in the summer of 1175; Dhu al-Nun and Shahinshah took refuge with Byzantium and the Sivas branch of the Danishmendids disappeared.", "dbfcc454"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1180-05-28:0":{"b": ["Kilij Arslan II takes the Uluborlu, Kütahya and Dorylaeum (Eskişehir) region from Byzantium", "807be33d"], "d": ["When Emperor Manuel did not abide by the terms of the treaty and did not have the fortress of Dorylaeum demolished, Kilij Arslan II had the Meander valley laid waste in 573/1177; Uluborlu, Kütahya and Dorylaeum passed to Seljuk rule in 576/1180.", "60e80418"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-01-01:0":{"b": ["The Georgian King David marches on Erzurum; he turns back in the face of popular resistance", "07419985"], "d": ["The Georgian King David marched on Erzurum, defeated Nasir al-Din Muhammad and caused him to withdraw into the city; faced with the courage and determination of the Turkish population, he plundered the surroundings and withdrew (580/1184-85).", "85711193"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-04-14:0":{"b": ["Kilij Arslan II divides his country among his eleven sons", "b1ee119d"], "d": ["In his old age Kilij Arslan II divided the country among his sons; Tokat fell to the share of his eldest son Rukn al-Din Suleyman Shah. The Seljuk realm was divided into eleven parts.", "09e83cd3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-01-01:0":{"b": ["The governor Isaac Doukas Komnenos rebels against Emperor Andronikos and declares Cyprus independent", "445f5db0"], "d": ["While Cyprus continued as a province of Byzantium, the governor Isaac Doukas Komnenos rebelled against Emperor Andronikos Komnenos and declared independence, and Cyprus passed out of Byzantine rule in 1185.", "00f3ca97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-07-10:0":{"b": ["Sökmen II (Shah-i Arman), Shah of Ahlat, dies during the siege of Mosul", "f492f6ba"], "d": ["When Saladin besieged Mosul again in 1185, news came that his ally Sökmen had died (9 Rabi' al-akhir 581 / 10 July 1185). Saladin did not return empty-handed from the Ahlat campaign and took Mayyafariqin, which had been left without a ruler.", "2692f19a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1190-05-17:0":{"b": ["The crusader army under Frederick Barbarossa defeats the Seljuk army and enters Konya", "f1f901b6"], "d": ["Barbarossa, the German emperor, who crossed into Anatolia from Gallipoli in March 1190, entered Seljuk territory near Uluborlu and on 17 May 1190 defeated the army of Qutb al-Din Malik-Shah and the other Seljuk maliks, and entered Konya, the capital, which the sultan had evacuated.", "0d30744a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1192-08-26:0":{"b": ["Kilij Arslan II dies during the siege of Aksaray; Kaykhusraw I succeeds him", "083f9fae"], "d": ["Kilij Arslan II, who was besieging Aksaray with Ghiyath al-Din Kaykhusraw during his struggle with his sons, fell ill and died on 15 Sha'ban 588 / 26 August 1192; Kaykhusraw took the throne at Konya.", "1f04ea47"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1193-05-18:0":{"b": ["Begtemür, Shah of Ahlat, is killed by his son-in-law Hazar Dinari", "12078a3c"], "d": ["About two and a half months after Saladin's death, Sayf al-Din Begtemür was killed on 18 May 1193 by his son-in-law Badr al-Din Aqsunqur Hazar Dinari, one of his commanders. Hazar Dinari imprisoned Begtemür's seven-year-old son and wife in a fortress in the Erzas region.", "e0117ffd"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1196-11-24:0":{"b": ["Ghiyath al-Din Kaykhusraw leaves the throne to his brother Rukn al-Din Suleyman Shah and goes into exile", "557c281e"], "d": ["Kaykhusraw I, struggling with his brothers, was obliged to leave the throne to Suleyman Shah II (Rukn al-Din) (593/1196) and left Konya; Suleyman Shah took his brothers' lands and established the unity of the country.", "129847ea"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1197-01-01:0":{"b": ["Amalric de Lusignan takes the title King of Cyprus; the same year he is also recognised as king of Jerusalem by the Crusaders at Acre", "c38ed247"], "d": ["Amalric took the title of king in 1197 and the same year was recognised as king of Jerusalem by the Crusaders at Acre; the Kingdom of Cyprus became the naval base of the Crusader East.", "1d28312c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1199-01-06:0":{"b": ["Leo, in the Cathedral of Tarsus, puts on the crown sent by the Holy Roman Emperor Henry VI and becomes the first king of the Armenian Kingdom of Cilicia", "99ceea3a"], "d": ["Leo, the Rubenid prince, put on the crown sent by the Holy Roman Emperor Henry VI in the Cathedral of Tarsus and was anointed by the papal legate; the Rubenid principality became the Armenian Kingdom of Cilicia.", "05fe804d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1201-06-23:0":{"b": ["Suleyman Shah II seizes Malatya from his brother Mu'izz al-Din Qaysar Shah", "fff1df20"], "d": ["Suleyman Shah, who moved against his brother Mu'izz al-Din Qaysar Shah, Malik of Malatya, who resisted submitting to him, seized the city on 19 Ramadan 597 / 23 June 1201.", "65e22bbb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-01-01:0":{"b": ["Suleyman Shah II's Georgian campaign: the Seljuks suffer heavy losses in a Georgian raid on the camp; Behram Shah, Mengujekid lord of Erzincan, is taken prisoner", "3ee9e922"], "d": ["Suleyman Shah II, who in 1202 set out on campaign against the Georgians attacking Turkish lands, was struck by a Georgian raid while resting in camp and suffered heavy losses; among the prisoners was Behram Shah, the Mengujekid lord of Erzincan.", "4151b3d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-06-25:0":{"b": ["Suleyman Shah II ends the Saltukid dynasty and grants Erzurum as iqta' to his brother Tughril Shah", "37a63791"], "d": ["Suleyman Shah II, the Anatolian Seljuk Sultan, who came to Erzurum during the Georgian campaign, imprisoned Malik-Shah and abolished the Saltukid principality (2 Shawwal 598 / 25 June 1202) and gave Erzurum to his brother Mughith al-Din Tughril Shah, Malik of Elbistan. The Saltukid lands remained in Tughril Shah's hands until 1225.", "6d717627"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-01-01:0":{"b": ["Suleyman Shah II dies; his young son Kilij Arslan III takes the throne", "838d74dd"], "d": ["Suleyman Shah II, who had achieved no result from the Georgian campaign of 1202, died on the road in 1204 as he marched on a second Georgian campaign (600/1204). He was succeeded by his young son Kilij Arslan III; during his reign of seven or eight months the Isparta region was conquered.", "6d8da37d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-08-29:0":{"b": ["The Georgians raid Azerbaijan, enter the lands of the Shah-i Armans and plunder the Malazgirt and Erciş region", "beb13519"], "d": ["After a successful raid on Azerbaijan in 601/1204-05, the Georgians entered the lands of the Shah-i Armans, advanced as far as Manzikert and then the Erciş area, burning and destroying everywhere; no troops came out against them.", "5c1e0212"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1205-03-01:0":{"b": ["Ghiyath al-Din Kaykhusraw I goes to Konya and takes the Anatolian Seljuk throne a second time", "f6332e53"], "d": ["Kaykhusraw, who after the Crusaders' occupation of Constantinople (mentioned as February 1204) had been obliged to go to his father-in-law's fortress in the Trebizond region, came to the city during Kilij Arslan III's minority and took the throne for the second time (Rajab 601 / March 1205).", "59c0db32"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1207-01-01:0":{"b": ["Kaykhusraw I takes the Denizli region", "47cabadd"], "d": ["During the second sultanate of Ghiyath al-Din Kaykhusraw I (1205-1211) the Denizli and Antalya regions were taken (603/1207); Antalya was taken on 5 March 1207.", "190b906c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-01:0":{"b": ["Kaykhusraw I dies in a battle with the Byzantine army near Alaşehir; the Byzantine army also suffers heavy losses", "fdac0ce7"], "d": ["Kaykhusraw died in a battle he fought with the Byzantine army near Alaşehir; the Byzantine army also suffered very heavy losses. His body was first buried at Alaşehir, then taken to Konya and interred in the Tomb of the Sultans beside the Alaeddin Mosque (end of June 1211).", "fd58f9bc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-15:0":{"b": ["The notables of the state gather at Konya and decide to raise Izz al-Din Kaykawus, Malik of Malatya, to the Seljuk throne; Kaykawus I is proclaimed sultan at Kayseri", "f80be390"], "d": ["On the death of Kaykhusraw I (608/1211), the notables of the state, because he was the eldest son, decided to raise Izz al-Din Kaykawus, Malik of Malatya, to the throne and sent a messenger for him to come to Kayseri; his brother Ala al-Din Kayqubad did not recognise his sultanate.", "09e0f400"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1212-01-01:0":{"b": ["Kayqubad does not recognise the sultanate of his elder brother Kaykawus I and rebels; he shuts himself in Ankara Castle and surrenders", "13cc17e2"], "d": ["Ala al-Din Kayqubad, who rebelled against Izz al-Din Kaykawus, proclaimed sultan at Kayseri on his father's death, besieged Kayseri together with the Armenian King Leo and his uncle Tughril Shah, Malik of Erzurum; without result, he withdrew to Ankara Castle and, when provisions ran out, surrendered on condition that neither he nor the people be harmed (608/1212).", "7b48bb7a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:0":{"b": ["Izz al-Din Kaykawus I dies at Viranşehir near Malatya while preparing an Aleppo campaign", "61f16209"], "d": ["Izz al-Din Kaykawus, who marched on Aleppo, where after the death (1216) of the Ayyubid al-Malik al-Zahir his child son had come to the throne, allied with the Artuqid Nasir al-Din Mahmud of Amid and Kökböri, lord of Irbil; as he came to Malatya he fell ill and died at Viranşehir near Malatya (Shawwal 616 / January 1220).", "a8264a2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:1":{"b": ["Ala al-Din Kayqubad is released from prison and proclaimed ruler at Sivas", "2e697d48"], "d": ["On the death of Izz al-Din Kaykawus I, Kayqubad, released from prison, was proclaimed sultan at Sivas (616/1220). Against the Mongol invasion he had Konya, Sivas and Kayseri surrounded with walls.", "c731bdd7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:2":{"b": ["The Mongols defeat the Georgians for the first time", "b869830b"], "d": ["The Mongols defeated the Georgians for the first time in 1220, and entered Georgia in 1231.", "7f39fa9d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1225-01-13:0":{"b": ["The Armenian King Hethum asks Kayqubad for peace; peace is made in return for an annual tribute of 40,000 gold pieces and military aid", "0d137195"], "d": ["After merchants' complaints about the Franks and the Armenians, Kayqubad declared war in 622 (1225) on the Armenians and the Crusaders; the Armenian King Hethum sent an envoy and asked for peace. The king would pay the sultan 40,000 gold pieces every year and, whenever the sultan wished, send 1,000 horsemen and 500 crossbowmen (carkcı).", "9d0f1a8e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:0":{"b": ["Ala al-Din Kayqubad takes Erzincan and abolishes the Erzincan branch of the Mengujekids", "edfdc566"], "d": ["Kayqubad, who moved against the Mengujekids, who wanted independence, added Erzincan to the Anatolian Seljuk lands in 625/1228; Malik Muzaffar al-Din, lord of Şebinkarahisar of the dynasty, was given Kırşehir as iqta' and, together with some places, Efsus as mulk.", "ba31e942"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:1":{"b": ["The rule of Malik Muzaffar al-Din, ruler of the Şebinkarahisar branch of the Mengujekids, ends; Kırşehir is given to him as iqta'", "1ec2fd55"], "d": ["In 1228 Ala al-Din Kayqubad abolished the Erzincan branch of the Mengujekids; Malik Muzaffar al-Din, lord of Şebinkarahisar of the dynasty, was given Kırşehir as iqta' and, together with some places, the town of Efsus as mulk.", "e17ab2ba"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1232-01-01:0":{"b": ["Seljuk armies take some fortresses in Georgia; Queen Rusudan proposes peace and agrees to betroth her daughter Tamar to Kaykhusraw II", "2a057d64"], "d": ["In 1232, in the time of Ala al-Din Kayqubad I, Kamal al-Din Kamyar and Mubariz al-Din Chavli campaigned in Georgia and took some fortresses; Queen Rusudan, unable to resist the Seljuk army, proposed peace and agreed to betroth her daughter Tamar to Ghiyath al-Din Kaykhusraw II, Kayqubad's son.", "c8ce3253"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1234-01-01:0":{"b": ["The Harput branch falls into the hands of the Anatolian Seljuks", "f2572ad0"], "d": ["Ala al-Din Kayqubad took Harput in 631/1234 against the Ayyubids' advance on Anatolia; the rule of the Artuqid branch at Harput came to an end (after Kösedağ the city fell into the hands of the Ilkhanids).", "b0bea54d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1236-01-01:0":{"b": ["The Mongols occupy Georgia again and send the Georgian notables to Mongolia", "245ae81a"], "d": ["When the Mongols occupied Georgia again in 633/1235-36, they sent the Georgian notables to Mongolia; these remained there for years. The Mongols used large numbers of Georgian soldiers in their campaigns.", "159ea654"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1237-05-31:0":{"b": ["Ala al-Din Kayqubad I dies, poisoned by game meat; his son Ghiyath al-Din Kaykhusraw II succeeds him", "5d74714c"], "d": ["Kayqubad, who closed the age of Seljuk ascendancy, was poisoned by game meat he ate at the banquet he gave for envoys on the festival of Ramadan and died the next day (4 Shawwal 634 / 31 May 1237); through the efforts of the statesmen Kaykhusraw II took the throne in place of the heir apparent Izz al-Din Kilij Arslan.", "7b42c0c6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1239-01-01:0":{"b": ["The Mongol army under Chormaghan Noyan takes and destroys Kars during the Georgian campaign", "f510f715"], "d": ["In 636/1239 the Mongol army under Chormaghan Noyan took Kars during the Georgian campaign and destroyed it; the city remained under Ilkhanid administration until 1336.", "38d144da"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1242-01-01:0":{"b": ["The Mongol commander Baiju Noyan captures Erzurum and puts its people to the sword", "118b9e3a"], "d": ["Baiju Noyan, the Mongol commander in Azerbaijan, taking advantage of the Seljuks' weakening by the Baba'i revolt, seized Erzurum at the end of 1242, put its people to the sword, and returned to the Mughan to attack Anatolia again in the spring.", "dcfa189c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:0":{"b": ["The Mongols, who occupied Anatolia after Köse Dağ, take Amasya and govern it with Mongol governors", "3b39a0ad"], "d": ["The Mongols, who occupied Anatolia after the Battle of Köse Dağ in 1243, took Amasya, and the city began to be administered by Mongol governors.", "a9d1a1e2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:1":{"b": ["After the defeat at Köse Dağ, Kayseri falls into the hands of the Mongols after ten days of resistance", "5600cbe9"], "d": ["After the Battle of Köse Dağ (1243), Kayseri fell into the hands of the Mongols after ten days of resistance and suffered great destruction.", "924187ac"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:2":{"b": ["Queen Rusudan agrees to pay tribute to the Mongols and formally recognises the Great Khan as suzerain", "99d19c31"], "d": ["Realising that she could not cope with the Mongols, Queen Rusudan agreed to become subject to them by paying tribute and in 1243 formally recognised the Great Khan as suzerain. After Rusudan's death the Mongols divided the Caucasus into eight provinces.", "c61c6116"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:3":{"b": ["The Emirate of Tokat is given by the Ilkhanids to Mu'in al-Din Suleyman Parwana after Köse Dağ", "f2938da6"], "d": ["The Ilkhanids, who dominated the Anatolian Seljuk state after the Battle of Köse Dağ, gave the Emirate of Tokat to Mu'in al-Din Suleyman Parwana; in 1276 Tokat was under the administration of Nur al-Din Jibril.", "d931de12"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1244-01-01:0":{"b": ["The Mongol commander Yasavur Noyan briefly seizes Malatya", "98759910"], "d": ["After the Köse Dağ victory (1243) the Mongols achieved no result from their first attempts against Malatya; Yasavur Noyan seized the city briefly in 1244, and in 1258 it was devastated by Baiju Noyan.", "78c903ae"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1246-01-01:0":{"b": ["The statesmen proclaim Izz al-Din Kaykawus, malik of Uluborlu, sultan in the village of Altuntaş in Akşehir", "20d6f3e7"], "d": ["The statesmen proclaimed Izz al-Din Kaykawus, who was malik of Uluborlu (Burgulu) at the time of Ghiyath al-Din Kaykhusraw II's death, sultan in the village of Altuntaş in Akşehir (643/1246).", "e7c6a924"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1247-01-01:0":{"b": ["King Hethum I sends his brother Smbat to Karakorum and forms an alliance with Möngke Khan's brother against the Mamluks", "7413b5e5"], "d": ["King Hethum I sent his brother Smbat to Karakorum and began a formal alliance with the Mongol Empire.", "769d4bcf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1251-01-01:0":{"b": ["After Möngke Khan's accession, the two Davids, returning from Mongolia, rule Georgia jointly", "f1640157"], "d": ["After the accession of the Great Mongol Khan Möngke Khan (1251), two Georgians named David, commissioned by him, returned from Karakorum to their country and ruled jointly; afterwards Batu Khan and Hülegü tried to establish rule in Georgia.", "96249933"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1255-01-01:0":{"b": ["Kilij Arslan IV is defeated by Kaykawus II in the battle of Ahmedhisarı near Kayseri", "edac92e9"], "d": ["After the death of Jalal al-Din Karatay, Kilij Arslan proclaimed himself independent sultan at Kayseri (652/1254); the next year, in the battle fought at a place called Ahmedhisarı near Kayseri, he was defeated by Kaykawus.", "d64649d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-01-01:0":{"b": ["The Mongols under Yashmut take Mayyafariqin after a long siege; Mardin resists for eight months", "c2328a27"], "d": ["In 1257, on his way to the Syrian campaign, Hülegü charged a unit under Yashmut with taking Mardin and Mayyafariqin; Mayyafariqin fell after a long siege, and fortified Mardin held out for more than eight months.", "18f326a7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-03-05:0":{"b": ["Kilij Arslan IV, brought from Burgulu to Konya, is placed alone on the Seljuk throne", "cb3eced9"], "d": ["Kilij Arslan IV, who after the defeat of Sultanhanı (654/1256) was at Burgulu (Uluborlu), was brought to Konya and placed alone on the Seljuk throne on 16 Safar 655 / 5 March 1257; when Kaykawus II came to Konya on 14 Rabi' al-akhir 655 / 1 May 1257, he sent his commander Ali Bahadır against Kilij Arslan.", "32f17269"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1258-01-08:0":{"b": ["Kaykawus II takes Malatya, Sivas, Tokat and Amasya; Kilij Arslan withdraws to Erzincan", "d4834ad1"], "d": ["When Izz al-Din Kaykawus, with the help of his famous commanders, brought Malatya, Sivas, Tokat and Amasya under his rule, Kilij Arslan IV was obliged to withdraw to Erzincan (656/1258); then, by the yarligh of Möngke Khan, the country was divided in two (657/1259).", "5954d32b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1259-01-01:0":{"b": ["By Möngke Khan's yarligh the Seljuk realm is divided in two between Kaykawus II and Kilij Arslan IV", "4dacbe83"], "d": ["After Baiju's departure from Anatolia, Kaykawus II was again seated on the throne at Konya (1 May 1257); by Möngke Khan's yarligh the country was divided between Kaykawus and Kilij Arslan. Kaykawus, who did not accept Mongol rule, took refuge with Byzantium in 660/1262.", "c7df29bf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:0":{"b": ["Kara Arslan, Artuqid ruler of Mardin, accepts Ilkhanid rule", "c6b7b1a6"], "d": ["Mardin suffered famine and plague during the Mongol siege of more than eight months; Kara Arslan, who came to the head on the death of Najm al-Din Ghazi, recognised Mongol rule in return for the restoration to the Artuqids of Dara, Khabur, Nusaybin and Ras al-Ayn, and was confirmed by Hülegü as ruler of Mardin in 659/1261.", "ff8d14de"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:1":{"b": ["When the Mongols are defeated by the Mamluks and withdraw to Iran, the Mamluks attack Cilicia and devastate the country", "505db4aa"], "d": ["When the Ilkhanid Mongols were defeated by the Mamluks and withdrew to Persia, the Mamluks attacked Cilicia and devastated the country; this is the actual beginning of the Mamluk attacks.", "89ccf21b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:0":{"b": ["Mu'in al-Din Parwana has Kilij Arslan IV killed by the Mongols and places his young son Kaykhusraw III on the throne", "27f0dc7a"], "d": ["When Kilij Arslan was forced to agree to being given Sinop as mulk, the vizier Mu'in al-Din Parwana had him killed by the Mongols (664/1266) and installed in his place his child son Kaykhusraw III; Parwana became the unrivalled master of the state.", "4aa91de1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:1":{"b": ["Baybars descends on Cilicia and takes Leo, son of King Hethum of Sis, prisoner", "2cefee6a"], "d": ["The Mamluk Sultan Baybars descended on Cilicia in 1266 and took prisoner Leo, son of King Hethum of Sis; by the subsequent agreement the Armenian king was to return the cities and fortresses he had occupied, and Leo was to be released (in 1268 only Behisni remained in Armenian hands).", "e5f53d00"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:2":{"b": ["Berke, khan of the Golden Horde, comes as far as Tbilisi", "23866ba3"], "d": ["Berke Khan came as far as Tbilisi in 1266; the level of prosperity of Georgia under Ilkhanid rule was nonetheless quite high.", "013e2621"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1268-01-01:0":{"b": ["The atabegs governing the Akhaltsikhe, Ardahan and Artvin areas (Atabegate of Samtskhe/Meskheti) take over the government of the region", "71bb5a86"], "d": ["Between 1268 and 1578 the atabegs, who were the rulers of the Akhaltsikhe, Ardahan and Artvin areas, held the government of the region in their hands, and during this period they remained dependent on the Ilkhanid, Qaraqoyunlu and Aqqoyunlu states.", "44bea8bb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1269-01-01:0":{"b": ["Hethum I abdicates in favour of his son Leo II; the kingdom becomes in effect a Mamluk vassal", "3d94aadc"], "d": ["Hethum I abdicated and left his place to his son Leo II; Leo II was obliged to pay a large annual tribute and the kingdom became in effect a Mamluk vassal.", "cd7ade63"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1271-01-01:0":{"b": ["The Mamluk Sultan Baybars sends a fleet of seventeen ships against Cyprus; the attack fails because of a storm", "cfeb4521"], "d": ["In 1271, while Baybars was taking the last fortresses and cities of the Crusaders in Palestine and Syria, he sent a fleet of seventeen ships against Cyprus, but the attack failed because of a storm that arose.", "c0ba5344"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1275-01-01:0":{"b": ["The Sahib Ata-oghlu Principality is founded at Afyonkarahisar and its surroundings", "c909e2f5"], "d": ["The sons and grandsons of Sahib Ata, vizier of the Anatolian Seljuks, founded a principality at Afyonkarahisar and its surroundings (1275-1341).", "26972b2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1277-06-04:0":{"b": ["The Ilkhanids discover Mu'in al-Din Suleyman Parwana's treachery and put an end to his life", "9a7cc34e"], "d": ["After Baybars's departure from Anatolia, Abaqa Khan, who came with a great army, had 200,000 people massacred on the ground of cooperation with the Mamluks; realising Parwana's treachery too, they put an end to his life and began to administer the Anatolian Seljuk state with officials sent from Tabriz (Parwana's death 676/1277).", "c7bb6ee3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1280-05-03:0":{"b": ["Mas'ud II, son of Kaykawus II, comes to Sinop and goes to the Ilkhanid capital to appear before Abaqa Khan", "9b43e13f"], "d": ["Mas'ud II, son and heir apparent of Kaykawus II, came to Sinop in 679/1280, then went to the Ilkhanid capital and appeared before Abaqa Khan; Abaqa Khan gave him the administration of Erzurum, Erzincan, Sivas, Diyarbakır and Harput.", "0ddb3753"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1282-04-11:0":{"b": ["Arghun Khan proclaims Mas'ud II sultan and has Kaykhusraw III killed", "0afda15b"], "d": ["After Ahmad Tegüder divided the Seljuk lands between Mas'ud II and Kaykhusraw III, Arghun Khan, victorious in the struggle for the Ilkhanid throne, proclaimed Mas'ud II, who was at Tabriz, sultan (681/1282) and had Kaykhusraw III, who was waiting at Erzurum, killed.", "ffa63120"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1284-03-20:0":{"b": ["Mas'ud II returns to Anatolia and takes the throne as Seljuk sultan, first at Kayseri and then at Konya", "ca5c28f4"], "d": ["Mas'ud II returned to Anatolia with Arghun's approval and took the throne at Kayseri and Konya in 683/1284; under the domination of Mongol commanders and governors he remained a 'shadow ruler', and struggled with the Karamanids, the Eshrefids and the Germiyanids.", "c089c457"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1288-11-22:0":{"b": ["The Seljuk vizier Sahib Ata Fakhr al-Din Ali dies near Akşehir", "9c7034f1"], "d": ["Sahib Ata, who served Kaykawus as deputy of the sultanate (na'ib-i saltanat) (657/1259), was imprisoned in Osmancık Castle in 670/1271-72 and reappointed vizier in 674/1275-76; after the campaign against the Karamanids with the allied Seljuk-Mongol army at the end of 686 / beginning of 1288, he died in the village of Nadir, dependent on Akşehir, on 25 Shawwal 687 / 22 November 1288 and was buried in his tomb at Konya.", "f8bf5f4a"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0481-01-01:0":{"b": ["Clovis succeeded his father Childeric as king of the Salian Franks; the centre of power was Tournai", "e4d35fd1"], "d": ["Clovis succeeded his father Childeric I as king of the Salian Franks in 481 at the age of fifteen. At that date the Salian Franks had advanced as far as the river Somme, and the centre of their power was Tournai.", "d4c684f8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0486-01-01:0":{"b": ["Clovis defeats Syagrius at the Battle of Soissons; the Roman rump principality south of the Somme passes to the Franks", "afa05aa7"], "d": ["Clovis attacked the Roman general Syagrius in 486; Syagrius, defeated at the Battle of Soissons, took refuge with the Visigothic king Alaric II and was handed over to him. Clovis thereafter moved his residence to Soissons and gradually seized Belgica Secunda (capital Reims).", "f20e6e70"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0496-12-25:0":{"b": ["Clovis is baptized by Bishop Remigius at Reims (Christmas)", "16299c9a"], "d": ["After his victory against the Alamanni, Clovis went to Reims and, on Christmas Day 496, was baptized by Saint Remigius together with three thousand Franks. The baptism turned the eyes of the Catholic population in the Burgundian and Visigothic kingdoms toward Clovis.", "2d58bf65"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0507-01-01:0":{"b": ["At Vouillé (near Poitiers) Clovis kills the Visigothic king Alaric II; Visigothic territory as far as the Pyrenees passes to the Franks", "e8ea0c78"], "d": ["After completing the subjugation of the Alamanni in 506, Clovis marched the next year against the Visigothic king Alaric II. At Vouillé near Poitiers he killed Alaric with his own hand; the part of the Visigothic kingdom extending to the Pyrenees, except Septimania, was joined to the Frankish state.", "e632a672"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0511-11-27:0":{"b": ["Clovis dies; he is buried at Paris, which he made his capital in his last years, and the unity of the kingdom is left to the Merovingian inheritance", "c6c9caa4"], "d": ["Clovis spent his last years in Paris and made it the capital of the kingdom; by eliminating the minor Frankish kings at centres such as Cambrai and Cologne, he became the sole king of all the Frankish tribes. He died in 511.", "eeb42f8c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0756-01-01:0":{"b": ["By his Italian campaigns Pippin III takes the Exarchate of Ravenna from the Lombards and donates it to the pope; the Papal State is born", "f6bbc975"], "d": ["At the call of Pope Stephen II, Pippin III made two campaigns to Italy, in 754 and 756; by donating to the pope the Exarchate of Ravenna that he took from the Lombard king Aistulf, he became the creator of the papacy's temporal state. Pippin gave the pope the title 'Patrician of the Romans'.", "0e4f19d8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0800-12-25:0":{"b": ["Charlemagne is proclaimed emperor and crowned by Pope Leo III at Saint Peter's in Rome", "3d72f37d"], "d": ["Charlemagne went to Rome in 800 with the aim of restoration; on Christmas Day, as he rose from prayer in the Church of Saint Peter, he was crowned by Pope Leo III and proclaimed emperor and augustus.", "d6956767"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0814-01-28:0":{"b": ["Charlemagne dies at Aachen and is buried the same day in the Church of the Virgin Mary", "915d6f61"], "d": ["Charlemagne spent most of his last years at Aachen (Aix). He fell feverish at the beginning of 814, and as a result of pleurisy he died on 28 January 814 after receiving communion, and was buried the same day in the Church of the Virgin Mary at Aachen; his son Louis the Pious succeeded him.", "8ce37094"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0842-02-14:0":{"b": ["Oaths of Strasbourg: Charles the Bald and Louis the German swear an alliance at Strasbourg", "b462f12a"], "d": ["In the year after the victory of Fontenoy, Charles the Bald and Louis the German strengthened their alliance with the Oaths of Strasbourg; Charles swore in the Germanic language of Louis's people, and Louis in the Romance language of Charles's subjects.", "02ceae89"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0843-08-10:0":{"b": ["Treaty of Verdun: the Carolingian Empire is divided into three (West Francia, Middle Francia, East Francia)", "1b628d03"], "d": ["By the treaty reached at Verdun in August 843, the sons of Louis the Pious divided the empire: Charles the Bald took the west of the Meuse-Saône-Rhône line (West Francia, including the Spanish March), Louis the German the east of the Rhine (Bavaria, Thuringia, Franconia, Saxony; also the area around Speyer-Worms-Mainz), and Lothair took Italy, the imperial title, and the strip in the Rhine-Rhône valleys.", "5bda08ed"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0875-12-25:0":{"b": ["Charles the Bald is crowned with the imperial crown at Rome", "49f42456"], "d": ["Charles the Bald, who descended on Italy with the support of Pope John VIII after the death of Louis II, received the Italian royal crown at Pavia and the imperial crown at Rome.", "d63d65ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0893-01-28:0":{"b": ["Charles the Simple is crowned king at Reims; a rival kingship begins against Odo", "ccc4acd5"], "d": ["Charles III 'the Simple' had been excluded on account of his youth at the deposition of Charles the Fat in 887; during Odo's kingship he was crowned on 28 January 893 at Reims with the recognition of some of the notables, and with the emperor's alliance forced Odo to give up part of Neustria. With Odo's death in 898 he held the whole kingdom.", "cd52d1cb"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0911-01-01:0":{"b": ["Treaty of Saint-Clair-sur-Epte: Charles the Simple cedes present-day Normandy to the Normans", "fd0306b0"], "d": ["Charles III made a treaty with the Normans at Saint-Clair-sur-Epte in 911; some of the Normans were baptized and the land that would later be called the Duchy of Normandy was ceded to them. The story of the marriage of Rollo with the king's sister is Dudo's narrative and is highly doubtful.", "5798ced7"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0923-06-15:0":{"b": ["Battle of Soissons: King Robert I dies, Raoul, Duke of Burgundy, is elected king", "4430302d"], "d": ["Robert, elected to the kingship against Charles the Simple in 922, died in the Battle of Soissons; Robert's partisans, who won the victory, elected Raoul (Rudolph), Duke of Burgundy, king. Charles, trusting Herbert, Count of Vermandois, was captured and died at Péronne in 929.", "9c2c291f"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0955-08-10:0":{"b": ["Battle of the Lechfeld: Otto I puts an end to the Hungarian raids", "7bd31ba4"], "d": ["Otto marched against the Hungarians besieging Augsburg and, with the great victory he won at the Lechfeld on 10 August 955, delivered Germany from the Hungarian raids; in the same year he also defeated the Slavs.", "fbb1b763"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0962-02-02:0":{"b": ["Otto I is crowned emperor at Rome; the beginning of the Holy Roman-German Empire", "24571f97"], "d": ["Otto crossed into Italy at the call of Pope John XII for help against Berengar; after arriving at Pavia at Christmas 961, he was crowned emperor at Rome on 2 February 962 and confirmed the papal rights and privileges. The Roman people swore that they would obtain the emperor's approval in the election of a pope.", "6e725f97"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1016-04-23:0":{"b": ["Æthelred II dies; Cnut (Canute) is elected king by the notables assembled at Southampton", "35653e3c"], "d": ["After the death of Æthelred II on 23 April 1016, the Dane Cnut was elected king by the council of notables at Southampton; London, however, remained loyal to Edmund. Cnut won in the great battle at Assandun, and after Edmund's death in November 1016 he was elected king of all England at the beginning of 1017.", "3a49dfc2"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:0":{"b": ["King Henry I gives the Duchy of Burgundy to his brother Robert; the Capetian Duchy of Burgundy (first ducal house) begins", "18dcd0ab"], "d": ["Henry I, who was King of France, bestowed the Duchy of Burgundy on his brother Robert in 1032; the first Capetian ducal house, which would last until 1361, descended from Robert.", "cbb03a09"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:1":{"b": ["Rudolph III, last king of the Kingdom of Burgundy (Arles), dies; his country passes to Conrad II (German emperor) — Basel enters the imperial lands", "4dc8eb08"], "d": ["Rudolph III (993-1032), the last king of the Kingdom of Burgundy (Jurane Burgundy/Arles), died without an heir and left his lands to Emperor Conrad II. This inheritance is the source of the imperial rights, called after the thirteenth century the Kingdom of Arles, extending from the Jura to the Aar and including part of present-day Switzerland as well as Franche-Comté, the Lyonnais, Dauphiné, Savoy and Provence. Since 888 the authority of the kingdom had been recognized in the bishoprics of Besançon, Basel, Lausanne, Geneva and Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:2":{"b": ["Rudolph III, last king of the Kingdom of Burgundy (Arles), dies; his country passes to Conrad II (German emperor) — Geneva enters the imperial lands", "be189789"], "d": ["Rudolph III (993-1032), the last king of the Kingdom of Burgundy (Jurane Burgundy/Arles), died without an heir and left his lands to Emperor Conrad II. This inheritance is the source of the imperial rights, called after the thirteenth century the Kingdom of Arles, extending from the Jura to the Aar and including part of present-day Switzerland as well as Franche-Comté, the Lyonnais, Dauphiné, Savoy and Provence. Since 888 the authority of the kingdom had been recognized in the bishoprics of Besançon, Basel, Lausanne, Geneva and Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:3":{"b": ["Rudolph III, last king of the Kingdom of Burgundy (Arles), dies; his country passes to Conrad II (German emperor) — Lyon enters the imperial lands", "78601ea1"], "d": ["Rudolph III (993-1032), the last king of the Kingdom of Burgundy (Jurane Burgundy/Arles), died without an heir and left his lands to Emperor Conrad II. This inheritance is the source of the imperial rights, called after the thirteenth century the Kingdom of Arles, extending from the Jura to the Aar and including part of present-day Switzerland as well as Franche-Comté, the Lyonnais, Dauphiné, Savoy and Provence. Since 888 the authority of the kingdom had been recognized in the bishoprics of Besançon, Basel, Lausanne, Geneva and Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-01-05:0":{"b": ["Edward the Confessor dies; Harold Godwinson is elected and crowned king at London", "3ff7af82"], "d": ["Edward the Confessor, who could not attend the consecration of Westminster Abbey, died on 5 January 1066; as he died he recommended Harold as successor. Harold was at once elected and crowned; Northumbria, although it first refused, submitted to him. William, citing Edward's will and Harold's oath of about 1064, claimed the throne and prepared an invasion.", "c67100ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-12-25:0":{"b": ["The Norman duke William is crowned king of England at Westminster", "92ddd637"], "d": ["William, who landed at Pevensey on 28 September 1066, crushed Harold at the Battle of Senlac (Hastings) on 14 October; he was crowned at Westminster on Christmas Day. His subjugation of the south, west and north of England took five more years.", "78756409"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1068-01-01:0":{"b": ["William the Conqueror campaigns against rebel Exeter", "cc25aa87"], "d": ["William's year 1068 passed in military campaigns against Exeter and York, where the partisans of Harold had taken refuge.", "e1fb87c6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1069-01-01:0":{"b": ["Northern revolt: the Danes and English seize York; William besieges and retakes the city, devastates the north", "c15ad892"], "d": ["After the murder of Robert of Comines at Durham, the north proclaimed Edgar Atheling, and the Danish king Sweyn sent a fleet; the Danes and English took York, which was protected by two Norman castles. William marched on York, drove the Danes to their ships, took the city by blockade and devastated the country as far as Durham; at the beginning of 1070 he marched on Chester and completed the subjugation of the north.", "a4420b47"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1075-01-01:0":{"b": ["Pope Gregory VII forbids lay investiture (the conferring of rank by non-clerical persons) in the appointment of clergy", "bc8488be"], "d": ["The prohibition of lay investiture, issued two years after the election of Hildebrand as pope under the name of Gregory VII in 1073, threatened the empire's power over religious appointments and was the beginning of open conflict with Henry IV.", "c78da49d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1080-03-07:0":{"b": ["Pope Gregory VII excommunicates Henry IV a second time and deposes him", "d73a0f3d"], "d": ["Under the pressure of the Saxons after the victory of Flarchheim (27 January 1080) and under the influence of false information, Gregory VII abandoned his policy of waiting; on 7 March 1080 he again declared Henry excommunicated and deposed, and released his subjects from their oaths of allegiance. The effect was much weaker than in 1076; the Synod of Brixen deposed Gregory on 25 June 1080.", "518e832b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1111-04-13:0":{"b": ["Henry V is crowned emperor at Rome; the investiture question is bound to a short-lived compromise", "f7e1aee5"], "d": ["In February 1111 at Sutri, Henry V received the promise of the imperial crown in return for renouncing investiture; the right of investiture and the promise of the crown were wrung from Pope Paschal II, and the coronation ceremony was held on 13 April 1111. After Henry left Rome, a council declared this concession invalid.", "5d77b395"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1152-01-01:0":{"b": ["Henry (II) gains Poitou, Guyenne and Gascony by marrying Eleanor", "4db69859"], "d": ["Henry Plantagenet became Duke of Normandy in 1150 and Count of Anjou in 1151 on his father's death; in 1152 he married Eleanor (Aliénor), who had been divorced from Louis VII, King of France, and thereby obtained Poitou, Guyenne and Gascony — this is the southern half of the Angevin Empire. The marriage drew the hostility of Henry's sovereign, Louis VII.", "39880a5d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1154-10-25:0":{"b": ["King Stephen dies; Henry II ascends the throne of England without encountering any resistance", "e1882039"], "d": ["In 1153 Henry had wrung from Stephen, with the help of the Church and the partisans of his mother Matilda, the recognition of his right of succession to England; when Stephen died on 25 October 1154, he put forward his claim without opposition. The Angevin Empire united the land extending from England to the Pyrenees.", "82a14d22"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1155-06-18:0":{"b": ["Frederick I Barbarossa is crowned emperor at Rome", "94350025"], "d": ["Frederick received the imperial crown at Rome on 18 June 1155 in his first Italian expedition, made in 1154; because of his insufficient forces and the hostility that arose, he returned to Germany in the autumn.", "ae0ad79e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1157-01-01:0":{"b": ["Diet of Besançon: Burgundian nobles offer homage to Frederick; the papal-imperial conflict rises", "7252823d"], "d": ["At the diet assembled at Besançon in October 1157, the Burgundian nobles swore an oath of allegiance to Frederick; because of the seizure of the Swedish archbishop on his return from Rome, the papal-imperial dispute grew.", "7b20ab27"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1173-01-01:0":{"b": ["Raymond V, Count of Toulouse, swears homage to Henry II", "460d9e41"], "d": ["Henry II, who had taken over Eleanor's claims to Toulouse, after a long struggle forced Raymond V, Count of Toulouse, in 1173 to swear homage to him for Toulouse.", "1727d885"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1176-05-29:0":{"b": ["Battle of Legnano: the Lombard League defeats Frederick I", "b7613445"], "d": ["After Frederick launched his fifth Italian expedition in 1174, the Lombard League was formed against him and the fortress of Alessandria was raised. When Henry the Lion, duke of Saxony, failed to send help, Frederick was defeated at Legnano on 29 May 1176; he was thought to have been wounded and killed. He withdrew to Pavia and began peace negotiations with Pope Alexander III.", "4d37e6ac"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1177-01-01:0":{"b": ["Treaty of Venice: Frederick Barbarossa and Pope Alexander III make peace; six-year truce with the Lombard League", "041665b3"], "d": ["After Legnano, Frederick recognised Alexander III as the true pope by the Treaty of Venice of August 1177 and was released from excommunication (in July 1177 he kissed the pope's foot); a six-year truce was made with the Lombard League. The Matildine inheritance was left to arbitration.", "1b138556"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1183-06-25:0":{"b": ["Peace of Constance: Frederick makes a lasting peace with the Lombard League", "91ea5aaf"], "d": ["In June 1183 a treaty was concluded with the Lombard League at Constance (a lasting peace replacing the six-year truce of 1177). In the meantime Henry the Lion, duke of Saxony, had been deprived of his duchy and sent into exile, and the duchy had been broken up; in 1184 Frederick's son Henry was betrothed to Constance, daughter of King Roger of Sicily.", "97ab19ec"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1201-01-01:0":{"b": ["Capitulation of Neuss: Otto IV recognises papal authority over the papal territories", "b43b4c91"], "d": ["By the capitulation of Neuss in 1201, the German emperor Otto IV accepted papal authority over the region extending from Radicofani to the pass of Ceperano (the Exarchate of Ravenna, the Pentapolis, the March of Ancona, the duchy of Spoleto, the lands of Matilda, the county of Bertinoro). For centuries part of these lands remained only a papal aspiration; the actual annexation of places such as Ravenna, Ancona, Bologna and Ferrara dates to the sixteenth century.", "e76fd40c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:0":{"b": ["Philip Augustus conquers Normandy: the union with England, which had lasted since 1106, ends; Maine, Touraine, Anjou and Poitou pass to France in 1204-1205", "ad5f7cb2"], "d": ["After John Lackland had Arthur killed, Philip Augustus took Normandy in 1203-1204 (siege of Château-Gaillard September 1203-April 1204, Rouen on 24 June 1204). The conquest of Maine, Touraine, Anjou and Poitou in 1204 and 1205 was as easy as 'almost a walkover'; only the castles of Loches and Chinon resisted for another year.", "e587727d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:1":{"b": ["Touraine (Tours) passes to the French crown", "220394a0"], "d": ["Philip Augustus's Loire conquests of 1204-1205 bound Maine, Touraine, Anjou and Poitou to the king of France; the castles of Loches and Chinon resisted for another year.", "c3eaca78"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1214-01-01:0":{"b": ["The Rhenish Palatinate is given by Frederick II to Otto of Wittelsbach (the Palatine County in the Wittelsbach dynasty)", "5f54fd76"], "d": ["On the death in 1214 of Henry, count palatine of the Rhine, the German king Frederick II gave the Palatinate to Otto, the younger son of Duke Louis I of Bavaria (betrothed to Henry's sister Agnes). Since Conrad's settlement in 1155 at the castle of Juttenbühel near Heidelberg, this area had been regarded as the capital of the Palatinate.", "066e8777"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1218-01-01:0":{"b": ["Simon de Montfort dies besieging Toulouse", "6da05355"], "d": ["Simon de Montfort, commander of the Albigensian Crusade, had entered Toulouse in 1215, but died in 1218 while besieging the city. Command of the crusade passed to his son Amaury; Raymond VII, son of Raymond VI, became head of the county in 1222.", "47aa27de"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1229-01-01:0":{"b": ["Treaty of Paris (Meaux-Paris): Raymond VII cedes most of his fiefs to the French crown", "ef1cb151"], "d": ["By the Treaty of Paris of 1229 the king of France deprived the house of Toulouse of most of its fiefs; the county was to pass to the French crown in 1271 through Raymond's daughter Jeanne and her husband Alphonse (brother of Louis IX).", "7186cd3b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:0":{"b": ["The king of Norway cedes the Isle of Man and the Hebrides to Scotland for 4,000 marks", "e027acbe"], "d": ["In 1261 Alexander III sent an envoy to Norway to negotiate the cession of the islands; when this produced no result he went to war, and in 1263 the Norwegian fleet was destroyed at Largs. Magnus, king of Man, was forced to give up all the islands except Man. In 1266 the king of Norway ceded the islands (including Man) to Scotland for 4,000 marks; Scottish rule in Man was established only in 1275, when the Manx were defeated at Ronaldsway.", "fdf0afa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:1":{"b": ["The king of Norway cedes the Hebrides and Man to Scotland for 4,000 marks: Peel (Man)", "92b7f459"], "d": ["The defeat at Largs in 1263 undermined Norway's claim to the Hebrides; in 1266 the king of Norway left the islands (including Man) to Scotland for 4,000 marks.", "11675aa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:2":{"b": ["The king of Norway cedes the Hebrides to Scotland for 4,000 marks: Iona (Hebrides)", "215cac00"], "d": ["With Alexander III's defeat of the Norwegian fleet at Largs (1263), Norwegian sovereignty over the Hebrides was shaken; in 1266 the king of Norway ceded the islands to Scotland for 4,000 marks.", "81cc8cf0"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1268-10-29:0":{"b": ["Conradin is executed in Naples: the male line of the Hohenstaufen dies out", "55645d01"], "d": ["Conradin, the last representative of the Hohenstaufen dynasty, was defeated by Charles, duke of Anjou, at Tagliacozzo (23 August 1268); he was then tried as a traitor in Naples and executed on 29 October together with his companion Frederick of Baden (titular duke of Austria). The male line of the Hohenstaufen died out.", "d81af0d1"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1271-01-01:0":{"b": ["Alphonse of Poitiers and his wife Joan die: the inheritance of the county of Toulouse passes to the French crown", "eabc3640"], "d": ["When Raymond VII died in 1249, the inheritance fell to his daughter Joan; Joan was married to Alphonse, brother of Louis IX. With the deaths of the two in 1271, the extensive inheritance of the counts of Toulouse passed to the French crown.", "ee58c39e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1276-11-21:0":{"b": ["Peace of Vienna: Ottokar II, king of Bohemia, renounces Austria, Styria, Carinthia and Carniola", "db5c2bc4"], "d": ["After Rudolf of Habsburg was elected king (1273), he placed Ottokar under the imperial ban and made war in June 1276; having detached Henry, duke of Lower Bavaria, from Ottokar, Rudolf forced the king of Bohemia in November 1276 to give up the four provinces. Ottokar was re-enfeoffed only with Bohemia and Moravia, and his son Wenceslaus was betrothed to Rudolf's daughter; Rudolf entered Vienna in triumph.", "d79ed14c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0569-09-04:0":{"b": ["Alboin entered Milan: northern Italy passed out of Byzantine hands", "b6be0ed6"], "d": ["Alboin entered Milan on 4 September 569; the bishop Honoratus fled to Genoa. Pavia fell after a long siege and the Po valley passed largely into the hands of the Lombards; Byzantium retained only some coastal and fortress cities.", "c0d39443"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0629-01-01:0":{"b": ["The Khazars captured Tiflis", "d0847d32"], "d": ["While subject to the Western Turks, the Khazars crossed the Derbend Pass and raided Georgia and Azerbaijan; Tiflis was captured in 629 and some Armenian groups were brought into submission. Their capital is Balanjar.", "5027db3b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0640-09-19:0":{"b": ["Hou Junji took Gaochang; the Tang established Xizhou on its lands", "1a8726a7"], "d": ["Hou Junji, commander-in-chief of the Jiaohe route, captured Gaochang (Turfan) and the Tang established the prefecture of Xizhou there; Qu Zhisheng, king of Gaochang, was brought as a prisoner before Taizong in the 12th month, and the army returned to China.", "76b4f5c5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0689-01-01:0":{"b": ["Malayu (Jambi) was incorporated into Srivijaya (between 689 and 692, according to the testimony of Yijing)", "da0ffb9b"], "d": ["The Chinese pilgrim Yijing reports that Malayu (the Jambi region), at which he had called in 671, was swallowed up by Shih-li-fo-shih (Srivijaya) between 689 and 692 (Coedès).", "a25038f0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-01-01:0":{"b": ["Tangier was captured (Musa b. Nusayr)", "0b579ded"], "d": ["Tangier was captured in 89 (708); in spring 711 the governor of Tangier, Tariq b. Ziyad, set out on the expedition to Spain.", "a6fd7e17"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-11-20:0":{"b": ["Qutayba b. Muslim took the surrender of Bukhara", "38427fbf"], "d": ["After two unsuccessful campaigns Qutayba marched on Bukhara; after a fierce siege he accepted the city's surrender on condition of military aid, tribute, and the stationing of a Muslim garrison in the citadel (90/708–709); this was a turning point for the conquests of Transoxiana.", "6b255806"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0714-01-01:0":{"b": ["Maslama b. Abd al-Malik captured the Derbend Pass", "839bbcf7"], "d": ["Fierce clashes with the Khazars took place in the time of al-Walid I; Maslama conquered some cities and fortresses in 708 and captured the Derbend Pass in 714; when he left the region in 717 for the siege of Constantinople, the Khazars launched a counteroffensive.", "358cd23d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0747-10-11:0":{"b": ["The Kharijite Abu Hamza captured Medina", "36cae3e0"], "d": ["The Kharijite leader Abu Hamza al-Shari took Medina in Safar 130 (October 747), after he had gained control of Mecca.", "b0263b26"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0748-01-15:0":{"b": ["Nasr b. Sayyar yielded Merv, the center of Khurasan, to the Abbasid rebels", "bc7bee2d"], "d": ["The Umayyad governor of Khurasan, Nasr, was forced to abandon Merv on 9 Jumada I 130 (15 January 748) and Nishapur in June; before the end of 749 the Abbasid armies had brought all of Khurasan under their control.", "dd216140"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0751-01-01:0":{"b": ["The Lombards took Ravenna: the Byzantine Exarchate ended", "f5a42f8f"], "d": ["The Lombard king Aistulf captured Ravenna in 750–751; thus Byzantium's only major center north of the Apennines fell, and only Venice and part of Istria remained attached to the empire.", "6debbee9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0756-01-01:0":{"b": ["Pippin donated the Exarchate of Ravenna to the papacy", "345e02a7"], "d": ["The Frankish king Pippin defeated Aistulf and gave the Exarchate of Ravenna and the Pentapolis to the papacy; thus Ravenna was taken from the Lombards and joined the nucleus of the Papal State. Byzantium was unable to oppose this donation.", "285518a8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0757-12-03:0":{"b": ["The Tang army entered Luoyang (757): the Eastern Capital was retaken from the rebels", "9d80b237"], "d": ["The rebel commander An Qingxu, defeated at the place called Xindian in Shaanxi, and his followers fled to Hebei; Prince Guangping entered Luoyang and drew up his army south of the Tianjin Bridge; more than 300 false officials, such as Chen Xilie and Zhang Ji, awaited their punishment in white garments.", "6194d763"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0761-08-07:0":{"b": ["The Abbasid commander Muhammad b. al-Ash'ath captured Kairouan", "40b80c87"], "d": ["After the appointment of Abd al-Rahman b. Rustam as governor there, the city was captured by Muhammad b. al-Ash'ath al-Khuza'i, whom Caliph al-Mansur had appointed to the governorship of Ifriqiya and the Maghrib (Jumada I 144).", "b5951323"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0764-01-01:0":{"b": ["The Khazar army captured Tiflis", "90eb05a6"], "d": ["When the Khazar princess whom the Abbasid governor Yazid b. Usayd had married died in childbirth, the khagan sent an army under As-Tarkhan; Tiflis was captured in 764.", "0f1e9c4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0774-01-01:0":{"b": ["Pavia surrendered; Desiderius was taken captive; Charlemagne took the title \"King of the Lombards\" (the Lombard Kingdom ended)", "2de54abb"], "d": ["At the call of Pope Hadrian I, Charlemagne crossed the Alps in 773 and entered the Lombard Kingdom; in June 774 Pavia surrendered and King Desiderius was sent to a monastery. Charles took the titles \"King of the Lombards\" and \"Patrician of the Romans\".", "4dbdb9e5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0775-01-01:0":{"b": ["The Ligor (Nakhon Si Thammarat) stele: the Srivijaya king settled at Ligor on the Malay Peninsula and had Buddhist temples built (775)", "62e97b39"], "d": ["The Wat Sema Muang stele shows that the Sumatran kingdom gained a foothold at Ligor on the Malay Peninsula in 775, and that the Srivijaya king (probably Dharmasetu) had a Buddhist temple complex built; the text on the second face refers to the Sailendra lineage.", "85396e40"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0809-01-01:0":{"b": ["Khan Krum took Sofia (Serdica)", "e24c951e"], "d": ["After a long siege the Bulgar Khan Krum captured Sredets (Sofia) and incorporated the city into the Bulgar state; the Bulgar army would come as far as Constantinople in 813.", "468a62fd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0813-01-01:0":{"b": ["Khan Krum took Didymoteichon", "d4e6581d"], "d": ["Didymoteichon, with its double walls, was captured by the Bulgar Khan Krum in 813.", "39bc9529"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0813-01-01:1":{"b": ["Khan Krum took Adrianople", "ab7bbb89"], "d": ["The Bulgar Khan Krum captured Adrianople in 813, and his army came before Constantinople.", "fa54d545"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0827-04-02:0":{"b": ["The Aghlabid–Euphemius fleet conquered Mazara (Mazara del Vallo): the conquest of Sicily began", "a2676b9a"], "d": ["After the Byzantine naval commander Euphemius rebelled against the governor Constantine Soudas and asked for aid from the Aghlabid emir Ziyadat Allah, a Muslim fleet of 10,000 men and more than seventy ships under Asad b. al-Furat came and joined Euphemius and conquered Mazara in 212 (827). The conquest of the island would last 75 years and be completed in 902.", "cc8ea594"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-01-01:0":{"b": ["Philippopolis was incorporated into the Bulgar state under Malamir", "f6c49ed3"], "d": ["Khan Malamir (831–836) incorporated Philippopolis (Plovdiv) into his lands; after this Khan Presian took the greater part of Macedonia.", "f8bd8891"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-02-18:0":{"b": ["Palermo surrendered to the Aghlabid Muslims", "6adfd1ac"], "d": ["After the fall of Mazara, Muslim forces besieged Palermo; the city surrendered in 216 (831). Platani, Caltabellotta, and Corleone would also be taken in 840.", "8693fb4d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-09-12:0":{"b": ["Palermo surrendered to the Muslims.", "4a74d5bb"], "d": ["Palermo surrendered to the Muslims.", "4a74d5bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0843-01-01:0":{"b": ["Messina was conquered; the Strait of Messina between Sicily and Italy came under Muslim control", "3c8d221c"], "d": ["After Platani, Caltabellotta, and Corleone were taken in 840 and the whole Mazara region in 842, Messina in the northeast of the island was conquered the following year (843) and the strategic strait was brought under control.", "87fda636"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0843-01-01:1":{"b": ["Messina surrendered.", "3702c5ff"], "d": ["Messina surrendered.", "3702c5ff"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0868-01-01:0":{"b": ["Oporto was settled during the reign of Alfonso III.", "3338d015"], "d": ["Oporto was settled during the reign of Alfonso III.", "3338d015"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0869-01-01:0":{"b": ["Malta was conquered.", "4edaaaa6"], "d": ["Malta was conquered.", "4edaaaa6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-01-01:0":{"b": ["Battle of Edington (Ethandun) and the Peace of Wedmore: Alfred defeated the Danes (Guthrum)", "bb82711f"], "d": ["After the Danes' sudden raid on Chippenham in January 878, Alfred hid with a small band of men; the armies met at Edington in Wiltshire. After the Peace of Wedmore (878) the Danes withdrew from Wessex; the northeastern half, including London, remained with the Danes, but \"the tide had turned\".", "4f02f617"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-05-21:0":{"b": ["The Arabs took Syracuse", "0ad38c19"], "d": ["The Aghlabids captured Syracuse, the principal Byzantine center in Sicily, on 21 May 878 after a long siege; the island began to pass effectively out of Byzantine hands.", "3c2d97da"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0886-01-01:0":{"b": ["Alfred took London from the Danes; the Alfred–Guthrum peace changed the boundaries in Alfred's favor", "32d8daf9"], "d": ["Alfred captured London in 885 or 886 at the end of the measures he took against the rebellious Danes; a peace was made between Alfred and Guthrum that changed the Wedmore boundaries in Alfred's favor.", "01209a4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-01-01:0":{"b": ["Zamora was settled during the reign of Alfonso III.", "78edf65c"], "d": ["Zamora was settled during the reign of Alfonso III.", "78edf65c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-03-23:0":{"b": ["The Samanid emir Isma'il b. Ahmad captured Talas (Taraz); the Samanids reached their widest frontiers in the east", "a25f7598"], "d": ["To protect Transoxiana against the raids of the non-Muslim Turks, Isma'il b. Ahmad launched a campaign extending as far as Taraz (Talas) and captured the city; most of the Turkish emirs and dihqans there became Muslims, and Oghulchaq, who lost Talas, the center of the Eastern Qarakhanids, moved the capital to Kashgar.", "8bf208a3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0902-08-01:0":{"b": ["Taormina fell: Byzantium's last fortress in Sicily was lost", "525abc8c"], "d": ["With the capture of Taormina by the Arabs, Byzantine domination on the island of Sicily came to an end; only the lands in southern Italy remained.", "9e2eb491"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0903-01-01:0":{"b": ["The Qarmatians captured Hama, Homs, Ma'arrat al-Nu'man, and Baalbek; the Tulunid troops sent against them were defeated (290/903).", "291ecf32"], "d": ["The Qarmatians captured Hama, Homs, Ma'arrat al-Nu'man, and Baalbek; the Tulunid troops sent against them were defeated (290/903).", "291ecf32"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0911-01-01:0":{"b": ["The Ganzhou Uyghur army captured Dunhuang", "36ec7038"], "d": ["Dunhuang, the center of the autonomous kingdom founded by a Chinese commander in 905, was taken in 911 by the Uyghur army under Tegin; the victory increased the prestige of the Ganzhou Uyghurs in the eyes of the Chinese.", "3bffe840"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0914-01-01:0":{"b": ["Simeon took Adrianople", "fe0efa60"], "d": ["The Bulgar Tsar Simeon captured Hadrianopolis (Adrianople) in 914; the city was for a long time the scene of the Byzantine–Bulgar wars.", "0d8b77bc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0923-11-19:0":{"b": ["Li Cunxu entered Kaifeng: the Later Liang fell", "aebaab18"], "d": ["Li Siyuan, the vanguard of Li Cunxu, who had routed the Liang army at Zhongdu, reached the Fengqiu Gate of Kaifeng at sunrise; Wang Zan, the Liang governor of Kaifeng, surrendered the city, and Li Cunxu entered the city through the Daliang Gate.", "4ee60f2e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0934-01-01:0":{"b": ["Byzantium took Melitene", "fd0898d0"], "d": ["The Byzantine army under the domestic of the East, John Kourkouas, advanced as far as the Euphrates and captured Melitene (Malatya) in 934; in 943 Mayyafariqin, Amid, Dara, and Nisibis were also taken.", "46c833cc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-01-01:0":{"b": ["Marzuban takes control of Azerbaijan, Arran, and Armenia (330–331 / 942–943).", "fc600309"], "d": ["Marzuban takes control of Azerbaijan, Arran, and Armenia (330–331 / 942–943).", "fc600309"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-01-01:1":{"b": ["Vushmgir loses Rayy to the Buyid emir Rukn al-Dawla (331/943).", "1e7169f4"], "d": ["Vushmgir loses Rayy to the Buyid emir Rukn al-Dawla (331/943).", "1e7169f4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-09-04:0":{"b": ["The Turkish commander Tuzun expelled the Hamdanids from Mosul (332/943).", "04d1fecc"], "d": ["The Turkish commander Tuzun expelled the Hamdanids from Mosul (332/943).", "04d1fecc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0947-01-01:0":{"b": ["After the second defeat against the Ikhshidids (spring 335/947) Aleppo passed to the Ikhshidids; in 336, by agreement, Sayf al-Dawla settled permanently in Aleppo.", "f5572476"], "d": ["After the second defeat against the Ikhshidids (spring 335/947) Aleppo passed to the Ikhshidids; in 336, by agreement, Sayf al-Dawla settled permanently in Aleppo.", "f5572476"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0960-01-01:0":{"b": ["The Fatimids capture Morocco and Sijilmasa.", "48efa30c"], "d": ["The Fatimids capture Morocco and Sijilmasa.", "48efa30c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0961-03-06:0":{"b": ["Chandax fell: Nikephoros Phokas recovered Crete", "aeefb280"], "d": ["The Byzantine forces under Nikephoros Phokas captured Chandax (Candia) on 6 March 961 after a siege of a year; the Emirate of Crete, which had lasted some 130 years, came to an end. Part of the island's Muslim population left the island, and part was forced to convert.", "ec04c12b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0962-01-01:0":{"b": ["Ahmad b. Hasan al-Kalbi took the Byzantine fortress of Taormina after a seven-month siege and named it al-Mu'izziyya", "37e8ae59"], "d": ["Ahmad b. Hasan al-Kalbi takes the Byzantine fortress of Taormina after a seven-month siege and names it al-Mu'izziyya.", "f8fcc7b1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-01-01:0":{"b": ["Nikephoros Phokas occupied Mopsuestia and Tarsus (354/965).", "045053b4"], "d": ["Nikephoros Phokas occupied Mopsuestia and Tarsus (354/965).", "045053b4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-08-16:0":{"b": ["Tarsus surrendered to Byzantium: Cilicia came under Byzantine rule", "b05e9bd3"], "d": ["Mopsuestia (Misis) surrendered in July 965 and Tarsus a month later, on 16 August 965, on humane terms, and again became a Christian city. Thus the region of Cilicia was annexed to Byzantium.", "faeb461f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0969-10-28:0":{"b": ["Antioch passed into Byzantine hands", "ad0a5da3"], "d": ["After the Byzantine armies took many fortresses and cities in northern Syria, Michael Bourtzes and Peter Phokas, coming from Cilicia, captured Antioch on 28 October 969. For about 115 years the city was Byzantium's main base in Syria.", "38b840e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0971-04-13:0":{"b": ["Tzimiskes took Great Preslav by storm: eastern Bulgaria was annexed to Byzantium", "07c84840"], "d": ["John Tzimiskes entered the plain of Preslav on 12 April 971; on the evening of 13 April the Bulgarian capital, defended by Sviatoslav's men, fell. Tsar Boris was taken captive and Byzantine administration spread over Thrace and eastern Bulgaria.", "ae050b34"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0979-01-01:0":{"b": ["Azerbaijan passed to the Rawwadids; the Musafirids withdrew to Tarum (979 or 980)", "b5b0e767"], "d": ["Azerbaijan passed to the Rawwadids; the Musafirids withdrew to Tarum (979 or 980)", "b5b0e767"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0983-06-15:0":{"b": ["The Qarmatians attacked Basra and imposed tribute on the city (373).", "d667e02e"], "d": ["The Qarmatians attacked Basra and imposed tribute on the city (373).", "d667e02e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-01-01:0":{"b": ["Harun Bughra Khan took Samarkand; the Qarakhanids entered Transoxiana for the first time", "31e0d0ae"], "d": ["Harun Bughra Khan, summoned by the secret agreement of Abu Ali al-Simjuri and Fa'iq al-Khassa, captured Samarkand in early 992 and then marched on Bukhara; he died at Koçkarbaşı on his way back to Kashgar.", "8377be9f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-05-07:0":{"b": ["The Qarakhanid Harun Bughra Khan captured Bukhara", "36955b70"], "d": ["Harun Bughra Khan, who had a secret agreement with Abu Ali al-Simjuri and Fa'iq al-Khassa, captured the Samanid capital Bukhara in Rabi I 382 (May 992); he fell ill shortly afterwards and died.", "cdd97d30"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-08-18:0":{"b": ["Nuh II regained control of Bukhara with the help of the Seljuk Turkmens", "8a88b4d3"], "d": ["On 15 Jumada II 382 (18 August 992), after the death of Harun Bughra Khan, Nuh II regained control of Bukhara with the help of the Seljuk Turkmens.", "00c3767a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0993-01-01:0":{"b": ["Ziri b. Atiyya defeats the Fatimid governor Yaddu b. Ya'la and retakes Fez; he begins to found Oujda.", "69e1def0"], "d": ["Ziri b. Atiyya defeats the Fatimid governor Yaddu b. Ya'la and retakes Fez; he begins to found Oujda.", "69e1def0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0997-01-01:0":{"b": ["Fakhr al-Dawla dies; the sallar Ibrahim b. Marzuban takes Zanjan, Abhar, Suhraward, and Tarum (387/997).", "f7dde64a"], "d": ["Fakhr al-Dawla dies; the sallar Ibrahim b. Marzuban takes Zanjan, Abhar, Suhraward, and Tarum (387/997).", "f7dde64a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0998-03-03:0":{"b": ["Mahmud defeated his brother Isma'il and ascended the Ghaznavid throne", "b2acf57c"], "d": ["Mahmud, who was at Nishapur, refused to recognize his father's testament and took action; the armies of the two brothers met in Rabi I 388 (March 998), and Mahmud defeated Isma'il and ascended the Ghaznavid throne.", "3c2c1e3d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0999-10-14:0":{"b": ["The Qarakhanid Ilig Khan Nasr entered Bukhara; the Samanid family was exiled to Uzgend, and the state effectively ended", "ec519748"], "d": ["In Dhu al-Qa'da 389 (October 999) the Qarakhanids occupied Bukhara; Abd al-Malik was taken captive, and the Samanid family was taken to Uzgend and imprisoned. Ilig Khan Nasr appointed his own governors to the region.", "ef9a0a65"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:0":{"b": ["Doge Pietro II Orseolo subjugated the Dalmatian cities and became \"Duke of Dalmatia\"", "fa3dde09"], "d": ["Setting out with a large fleet at the invitation of the Dalmatians, Orseolo defeated the Croats and the Narentines, cleared the Adriatic of piracy, and received the tribute and oaths of allegiance of the Dalmatian cities; he took the title \"Duke of Dalmatia\". Zadar swore fealty to the doge in 1000.", "d2c778fc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:1":{"b": ["Ragusa (Dubrovnik) and the southern Dalmatian cities swore fealty to Orseolo", "6121e2e9"], "d": ["During Orseolo's Dalmatian campaign, Ragusa, the southernmost of the Dalmatian cities, met the doge's army with its envoys and its archbishop on the islet of San Massimo and offered allegiance to Venice.", "638f8cad"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1013-01-01:0":{"b": ["Mahmud took Lahore from the Hindu Shahis; Lahore became the favorite city of the Ghaznavids", "37ab3445"], "d": ["Lahore, which had been in the hands of the Hindu Shahis since 991, passed to Mahmud of Ghazna in 1013–1014; Mahmud fortified Lahore Fort and established a garrison there of Turkish and Tajik soldiers brought from Khurasan. When the Ghaznavids lost their independence (after 1157), Lahore became the center of the portion that survived in the east.", "90b6f385"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1015-01-01:0":{"b": ["King Robert II annexed the Duchy of Burgundy to the French crown after a war of thirteen years", "257ea2c6"], "d": ["After the death of Duke Henry in 1002 a war broke out over the Duchy of Burgundy; despite the resistance of Otto-William, Count of Burgundy, Robert II, King of France, annexed the duchy to the kingdom in 1015 at the end of a war lasting thirteen years and gave it to his son Henry (later Henry I).", "9b353b9c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:0":{"b": ["Basil II entered Ohrid: the western Bulgarian capital passed into Byzantine hands", "05fe0972"], "d": ["The Bulgarian dynasty, which had resisted for four years after the death of Samuel, surrendered to Basil II at the gates of Ohrid in early 1018. The archbishopric of Ohrid, for its part, continued to exist under Byzantine rule as the center of Slavic Christianity.", "b6ac5adb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:1":{"b": ["Bolesław Chrobry, King of Poland, took Kiev with German and Pecheneg support", "3e44ca65"], "d": ["In August 1018 Bolesław captured Kiev with German and Pecheneg forces; having defeated Yaroslav on the Bug River, he placed his son-in-law Sviatopolk on the throne. Yaroslav was able to retake Kiev only in 1019.", "02428d3c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-05-20:0":{"b": ["Mahmud gained control of the city of Mathura (Muttra)", "78547f01"], "d": ["During the Kanauj campaign the Ghaznavid army gained control of the city of Mathura, which lies midway on the road between Delhi and Agra (409/1018).", "bb198817"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-12-20:0":{"b": ["Mahmud conquered Kanauj (Kanyakubja)", "258b5624"], "d": ["Mahmud left Ghazna on 13 Jumada I 409 (27 September 1018) for his twelfth Indian campaign; after the fortress of Sarsawa, the submission of the Raja of Baran, and Mathura, the main objective, Kanauj, was conquered on 8 Sha'ban 409 (20 December 1018).", "5952deed"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1028-01-01:0":{"b": ["Cnut the Great was proclaimed king in Norway; Olaf Haraldsson fled", "89688331"], "d": ["Cnut came to Norway in 1028 with a fleet of fifty ships and was acclaimed king of Norway at the Øreting; King Olaf II Haraldsson fled first to Sweden and then to Rus' (Gardarike).", "35460867"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1030-01-01:0":{"b": ["The County of Aversa was founded: Rainulf Drengot became a Norman count", "ec99b57a"], "d": ["In 1030, when Sergius, Duke of Naples, installed Rainulf in the fortress of Aversa, the Normans for the first time obtained a permanent base and the organized conquest of southern Italy began.", "8d2a9071"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1033-01-01:0":{"b": ["The Banu Ifran take the city of Fez from Hamama b. al-Mu'izz.", "6cad34e9"], "d": ["The Banu Ifran take the city of Fez from Hamama b. al-Mu'izz.", "6cad34e9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1038-01-01:0":{"b": ["Guaimar took Capua from his uncle and also subjugated Amalfi, Sorrento, and Gaeta", "3b8444df"], "d": ["Guaimar takes Capua from his uncle Pandulf IV; then he also subjugates Amalfi, Sorrento, and Gaeta, and receives recognition from the Emperor Conrad II.", "9e207542"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1038-02-09:0":{"b": ["Ala al-Dawla takes Rayy, then abandons it (Jumada I 429 / February 1038).", "8cd709ec"], "d": ["Ala al-Dawla takes Rayy, then abandons it (Jumada I 429 / February 1038).", "8cd709ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1039-01-01:0":{"b": ["Guaimar, Prince of Salerno, seizes the Duchy of Amalfi with the support of Norman mercenaries.", "39b73a57"], "d": ["Guaimar, Prince of Salerno, seizes the Duchy of Amalfi with the support of Norman mercenaries.", "39b73a57"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1047-01-01:0":{"b": ["The fortress of Kinkever surrenders; Hamadan passes under direct Seljuk control (439/1047).", "2bdca680"], "d": ["The fortress of Kinkever surrenders; Hamadan passes under direct Seljuk control (439/1047).", "2bdca680"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1048-06-16:0":{"b": ["Qavurd Beg took Bardasir, the center of Kirman, ending Buyid rule in Kirman", "131afa64"], "d": ["When Qavurd Beg, son of Chaghri Beg, entered the north of Kirman with 5,000–6,000 horsemen and besieged the center, Bardasir, Bahram b. Lashkarsitan, who ruled in the name of the Buyids, surrendered the city (440/1048); the foundation of the Kirman Seljuks was laid. Abu Kalijar died in the same year.", "8817f5aa"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1050-01-01:0":{"b": ["Qavurd Beg took Jiruft, the southern part of Kirman, from the Quf people and conquered all of Kirman; the emir of Hormuz became a vassal", "87e442c0"], "d": ["The south of Kirman, called Jiruft, was in the hands of the brigand Quf people; Qavurd Beg suppressed them in the eastern mountains, destroyed most of them, and took southern Kirman as well (442/1050); Badr Isa, emir of the island of Hormuz, became a vassal of the Seljuks, and Qavurd also conquered Oman.", "7d6e7ded"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1051-05-15:0":{"b": ["Faramurz surrendered Isfahan to the Seljuks after a siege of a year; Jibal rule ended, and Yazd remained as an iqta", "37716461"], "d": ["Faramurz surrendered Isfahan to the Seljuks after a siege of a year; Jibal rule ended, and Yazd remained as an iqta", "37716461"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1051-05-15:1":{"b": ["Tughril Beg annexed Isfahan to his realm", "93d9438c"], "d": ["Tughril Beg annexed Isfahan to his realm in 443 (1051).", "573195e7"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1057-03-10:0":{"b": ["The Zirid emir al-Mu'izz left Kairouan for Mahdiyya; Kairouan fell to the Hilalis", "becee655"], "d": ["Under the siege of the Banu Hilal, al-Mu'izz b. Badis left Kairouan in 449 (1057) for Mahdiyya, where his son Tamim was governor; the undefended Kairouan was plundered and burned by the Bedouin.", "7b6732bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1061-01-01:0":{"b": ["Count Roger captured Messina (1061)", "28b31d9a"], "d": ["Roger landed near Messina in 1061 and took the city relatively easily; thus the Norman conquest of Sicily began. TDV gives this year as the capture of Messina.", "d06afdbf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:0":{"b": ["Alp Arslan conquered Byzantine Kars; the Georgian king became a vassal of the Seljuks", "25994288"], "d": ["Alp Arslan appeared again on the frontiers of Byzantium and Georgia in 1067; Byzantine Kars was conquered and the Georgian king became a vassal of the Seljuks.", "5395feca"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:1":{"b": ["Alp Arslan took Kayseri", "c40df514"], "d": ["In the time of the Seljuk Sultan Alp Arslan the Turks captured Ani in 1065 and Kayseri in 1067; Byzantium lost the gates of Cappadocia.", "fbeb3963"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1071-01-01:0":{"b": ["Catania passed into Norman hands (1071)", "21617f1b"], "d": ["While the siege of Bari continued, Catania passed into Norman hands in 1071 through a betrayal in the city; however, the city was afterwards lost and permanently taken about ten years later.", "3d49a9a2"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-01-01:0":{"b": ["Mazara passed into Norman hands (1072)", "e7cb9667"], "d": ["In 1072, the year Palermo was taken, Mazara was also conquered; in the following years a fortress was built there and an attack of North African origin was resisted (1075).", "95450106"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-12-15:0":{"b": ["Nasr II took Termez on the death of Alp Arslan, then marched on Balkh and captured that as well", "7747ccc9"], "d": ["On the death of Alp Arslan during his Transoxiana campaign, the Western Qarakhanid Shams al-Mulk Nasr II took Termez in Rabi II 465 (December 1072), then marched on Balkh and captured that too; the Seljuk–Qarakhanid struggle continued in the time of Malikshah.", "1ba5253a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1073-01-01:0":{"b": ["Amalfi appeals to Robert Guiscard against Salerno's pressure; the Normans occupy the city and independence...", "3d375631"], "d": ["Amalfi appeals to Robert Guiscard against Salerno's pressure; the Normans occupy the city and independence ends.", "be93237a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1075-08-16:0":{"b": ["Malikshah's emir Savtegin captured Arran; the Ganja branch of the Shaddadids ended", "e031fc26"], "d": ["In the time of the Shaddadid Fadl III, Savtegin, one of the emirs of Sultan Malikshah, captured Arran (468/1075–76); the region came under Seljuk administration and the Ganja branch of the Shaddadids ended.", "b39c17bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1076-01-01:0":{"b": ["Salerno fell to Robert Guiscard; the Lombard Principality of Salerno ended", "c678238f"], "d": ["After a long resistance Salerno surrendered to Robert Guiscard in December 1076; Prince Gisulf II withdrew into exile at the papal court. Guiscard made Salerno the capital of his own duchy.", "705fecee"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-01-01:0":{"b": ["Roger took Trapani with his fleet", "2b0b3d98"], "d": ["Having built a fleet, Roger intensified his military activity in 1077 and took Trapani and then Castronovo.", "6e482ca5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-07-25:0":{"b": ["Yusuf b. Tashfin captured Tangier", "aa4376c4"], "d": ["The Almoravid emir Yusuf b. Tashfin took Tangier, an important coastal city of the Maghrib al-Aqsa, in the year 470 (1077–78).", "94bf21ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1081-01-01:0":{"b": ["Robert Guiscard landed at Valona and took Corfu", "d5e43c94"], "d": ["In 1081 Guiscard marched with his fleet to Valona (Vlorë), took Corfu, and captured Dyrrhachium in 1082; the march on Constantinople was left unfinished when he was called to help Gregory VII in Rome.", "f805ca31"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1082-01-01:0":{"b": ["Suleyman Shah I, the founder of the Anatolian Seljuks, conquered Tarsus", "93d6092f"], "d": ["Suleyman Shah I conquered Tarsus in 475/1082; the city was taken by the Crusaders in 490/1097 and afterwards changed hands among the Crusaders, Byzantium, and the Armenians of the region.", "912208e8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-03-24:0":{"b": ["Rome surrenders to Henry IV; the antipope Clement III (Guibert) is enthroned, Henry is crowned emperor, and Gregory flees Rome", "311cfeb4"], "d": ["The Romans surrendered the city to Henry, who had descended into Italy in 1081; Guibert, archbishop of Ravenna, was proclaimed pope on 24 March 1084 as Clement III, and Henry was crowned emperor by the rival pope. Gregory VII, abandoned by thirteen cardinals, was forced to flee Rome; he relied on Norman support.", "996d4e46"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-05-10:0":{"b": ["The Almoravids gained control of Ceuta", "48f062fb"], "d": ["Yusuf b. Tashfin brought Ceuta under his rule in 477 (1084); this became the gateway for the crossing into al-Andalus.", "4ba802e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1085-01-01:0":{"b": ["Buldaci, emir of Suleyman Shah, conquered the Ceyhan (Elbistan) region", "406d5385"], "d": ["The Ceyhan (Elbistan) region, a target of the raids of the Turkmen ghazis, was conquered in 1085 by Buldaci, one of the emirs of the Anatolian Seljuk Sultan Suleyman Shah.", "f1f8ec8c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-01-01:0":{"b": ["Syracuse fell to the Normans", "0d66d006"], "d": ["After the fall of Agrigento in July 1086, Syracuse passed into Norman hands in October 1086; Castrogiovanni would surrender in 1087 and Noto in 1091.", "b99596a6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-07-11:0":{"b": ["Tutush captured Aleppo after besieging it for a time.", "11f90dba"], "d": ["Tutush captured Aleppo after besieging it for a time.", "11f90dba"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1088-03-27:0":{"b": ["Malikshah captured Bukhara and Samarkand and took the Western Qarakhanid Ahmad Khan prisoner to Isfahan", "ababb7d4"], "d": ["When the chief qadi Ahmad b. Sulayman was killed by Ahmad Khan, Malikshah, at the call for help of the Shafi'i jurist Abu Tahir b. Alak, captured Bukhara and Samarkand in 481 (1088) and came to Uzgend; he took Ahmad Khan prisoner to Isfahan. Abu Tahir al-Khwarazmi was appointed deputy (naib) in Samarkand.", "b43535bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1089-01-01:0":{"b": ["Duke Ruggero retakes Amalfi.", "18ff3563"], "d": ["Duke Ruggero retakes Amalfi.", "18ff3563"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1090-01-01:0":{"b": ["The island of Malta was annexed to the Norman County", "181ee62e"], "d": ["In 1090 Roger brought the island of Malta also under his sovereignty.", "88b62d2a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1090-03-06:0":{"b": ["Malikshah captured Samarkand for the second time and appointed Emir Atsiz as governor", "685e6aef"], "d": ["Upon the revolt of Ayn al-Dawla, the commander of the Chigils, and Yaqub Tegin's crossing to Samarkand, Malikshah captured Samarkand for a second time at the end of the year 483 (1090) and appointed Emir Atsiz governor there; he then placed Yaqub Tegin at the head of the Eastern Qarakhanids and charged him with fighting Tughril b. Yinal.", "f2c9b630"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1090-03-06:1":{"b": ["The Almoravids captured Granada", "65113a38"], "d": ["During the third crossing into al-Andalus (483/1090) Yusuf b. Tashfin captured Granada and returned to North Africa; the Zirid emirate ended.", "f032e02c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1091-02-23:0":{"b": ["The Almoravids took Seville from the Abbadids", "9ee64f2b"], "d": ["Seville passed into the hands of the Almoravids in 484 (1091); the Abbadid emirate ended.", "75adcb2f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1092-01-01:0":{"b": ["Chaka Bey, after a three-month Byzantine siege, left Mytilene to Byzantium on condition that his soldiers be allowed to depart alive", "4a8d9810"], "d": ["In the spring of 1092 Emperor Alexios Komnenos sent John Doukas by land and Dalassenos by sea to relieve Mytilene; although the three-month siege did not succeed, Chaka Bey, realizing he could hold out no longer, left Mytilene to Byzantium on condition that his soldiers leave the island unharmed.", "f1e57c7a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1094-01-01:0":{"b": ["Rodrigo Díaz de Vivar (the Cid) captured Valencia", "7e966419"], "d": ["The Castilian epic hero Rodrigo Díaz de Vivar took Valencia in 1094, had the ruling qadi Ibn Jahhaf put to death, and subjected the population to kharaj.", "27df4900"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1096-11-01:0":{"b": ["The Seljuk emir Kerbogha took Mosul after a long siege; Uqaylid rule in Mosul ended", "451eac3a"], "d": ["When Muhammad, son of Muslim b. Quraysh, asked the Seljuk emir Kerbogha for help against his brother Ali, Kerbogha seized him, took Nisibis, and after a long siege captured Mosul; Uqaylid rule in Mosul ended in Dhu al-Qa'da 489 / November 1096.", "ab496145"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1097-01-01:0":{"b": ["The Crusaders took Elbistan and gave its administration to a knight", "c44e1068"], "d": ["Elbistan, one of the important cities on the Byzantine marches, passed into the hands of the Crusaders in 1097 and its administration was given to a knight named Pierre d'Aulps; it changed hands several times until 1103.", "1ef4649e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1097-01-01:1":{"b": ["Tarsus was taken by the Crusaders", "31fbde05"], "d": ["Tarsus, which Suleyman Shah had taken in 1082, passed into the hands of the Crusaders in 490/1097; afterwards it changed hands among the Crusaders, Byzantium, and the Armenians of Cilicia.", "7cc2e6da"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1100-01-01:0":{"b": ["The Normans suppress the revolt of Marino Sebaste.", "88976a9e"], "d": ["The Normans suppress the revolt of Marino Sebaste.", "88976a9e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1105-01-01:0":{"b": ["Kilij Arslan I reconquered Elbistan and granted it as an iqta to the vizier Diya al-Din Muhammad", "b4c664ea"], "d": ["Kilij Arslan reconquered Elbistan in 1105 and granted it as an iqta to the vizier Diya al-Din Muhammad.", "479b77ef"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1110-01-01:0":{"b": ["Baldwin I took Sidon after a siege of forty-seven days", "fe59c27d"], "d": ["Sidon, which had earlier saved itself by paying money, surrendered on safe-conduct after a siege of forty-seven days and was turned into a county subject to the Kingdom of Jerusalem.", "1da54820"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1110-01-01:1":{"b": ["Beirut passed into the hands of the Crusader Kingdom of Jerusalem", "7b129d4d"], "d": ["During the Crusades Beirut passed into the hands of the Kingdom of Jerusalem (1110).", "175df636"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1110-01-01:2":{"b": ["Zaragoza passed to the Almoravids; Hudid independence ended", "eda7fd85"], "d": ["The notables of besieged Zaragoza expelled the emir and invited the Almoravids to take over the administration; the independence of the Hudids ended.", "d769a0cf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1118-04-24:0":{"b": ["Togan Arslan, Emir of Erzen, attacked Dvin, killed the Shaddadid Manuchihr, and annexed the city to his lands", "ea150fcc"], "d": ["Despite the raids of the Artuqid Ilghazi and of Qizil Arslan, Emir of Erzen-Bitlis, on Dvin, the Shaddadids held the city until 1105; Qizil Arslan's successor Togan Arslan attacked Dvin in 512/1118, killed Manuchihr, and annexed the city to his lands.", "5fc19459"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1121-01-01:0":{"b": ["David ended Seljuk rule in Tiflis and took the city; Tiflis became the capital of Georgia", "c916b7bf"], "d": ["When the Georgian King David, with Kipchak help, ended Seljuk rule in Tiflis, the family of the Banu Ja'far was expelled from the city; after the Battle of Didgori (12 August 1121) Tiflis and Ani were occupied and Tiflis was made the capital of Georgia.", "192100de"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1123-03-01:0":{"b": ["The Christian population of Ani handed the city over to the Georgian King David; the city purchased by the Saltukid Emir Ali slipped from his grasp", "c3129744"], "d": ["When the Shaddadid Shavur II tried to sell Ani to the Saltukid Emir Ali, who held Kars, the Christian inhabitants revolted, summoned the Georgian King David, who had recently taken Tiflis, and handed the city over to him; Shavur II was arrested with his family and sent to Georgia.", "2d0410cf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1124-06-13:0":{"b": ["Emir Ghazi took the surrender of Malatya after a long siege", "9577600c"], "d": ["On the death of Belek (1124), the Danishmendid Emir Ghazi, taking advantage of the disputes among the Seljuks between Tughril Arslan, the Malik of Malatya, and Suleyman, the Emir of Harput, assaulted Malatya on 13 June 1124 and received the city's surrender after a long siege.", "90a62ad1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1124-12-10:0":{"b": ["Kilij Arslan's widow Ayse Khatun and her son Tughril Arslan surrendered Malatya to the Danishmendids and withdrew to the fortress of Minshar", "d42e670e"], "d": ["After the death of the Artuqid Belek (518/1124), Kilij Arslan's wife Ayse Khatun and her son Tughril Arslan surrendered Malatya to the Danishmendids and withdrew to the fortress of Minshar (1 Dhu al-Qa'da 518 / 10 December 1124).", "5eca3d1f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1128-08-22:0":{"b": ["The Duchy of Apulia (Salerno) was united with Sicily under Roger II", "8e50f9fe"], "d": ["By the investiture of 22 August 1128 the Duchy of Apulia, including Salerno, formally passed to Roger II, Count of Sicily.", "3dc87d43"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1131-01-01:0":{"b": ["Amalfi was annexed to Roger II's Kingdom of Sicily", "82507eed"], "d": ["Amalfi is annexed to the state of Roger II of Sicily. Treccani also: 'Nel 1131 Ruggero sottomise rapidamente la ribelle Amalfi, imponendole un presidio militare' (Treccani DBI Ruggero II).", "283b7e76"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1132-01-01:0":{"b": ["Emir Ghazi retook the Kastamonu region, which the Byzantine Emperor John Komnenos had occupied", "ece32651"], "d": ["Taking advantage of the absence of Emir Ghazi on the Cukurova campaign, Emperor John Komnenos occupied the Kastamonu region; Emir Ghazi retook it in 1132.", "9f686087"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1136-01-01:0":{"b": ["The Duchy of Gaeta was annexed to the Kingdom of Sicily", "f321d342"], "d": ["The duchy had first lost its autonomy through the Norman conquest (1032) and was incorporated into Roger II's Kingdom of Sicily in 1136.", "20895b9e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1144-12-24:0":{"b": ["Turkish forces entered Edessa (Urfa); the citadel surrendered two days later and the city passed to Zengi.", "4e7e4f9b"], "d": ["Turkish forces entered Edessa (Urfa); the citadel surrendered two days later and the city passed to Zengi.", "4e7e4f9b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1146-04-28:0":{"b": ["Abd al-Mu'min captured Fez after a siege of nine months", "e21fef93"], "d": ["Abd al-Mu'min, who marched from Oran to Fez to put an end to the Almoravids, took the city after besieging it for nine months (28 April 1146).", "fbe4e9ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1147-01-01:0":{"b": ["The Normans sacked Corinth", "bf59343b"], "d": ["In autumn 1147 the Sicilian Normans entered the Gulf of Corinth, occupied Corinth, one of the two centers of the silk industry, and carried the booty to Palermo.", "ebaaad31"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1147-01-01:1":{"b": ["Roger, King of Sicily, took Corfu", "67721fa1"], "d": ["Roger II's Norman fleet attacked the Byzantine coasts in autumn 1147; it seized the island of Corfu and sacked Corinth and Thebes. The island was retaken in 1148–1149 with the help of the Venetian fleet.", "043aa674"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1150-01-01:0":{"b": ["The Danishmendid Ayn al-Dawla took Gerger, Kahta, Adiyaman, and Palu from the Crusaders", "d53ab0cb"], "d": ["The Malik of Malatya, Ayn al-Dawla, who attacked Crusader lands together with the Artuqid Kara Arslan, captured Gerger, Kahta, Adiyaman, and Palu in 1150 and took many prisoners. In the same year Yaghibasan, Malik of Sivas-Amasya, took Unye, Samsun, and Bafra.", "ed529306"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1150-01-01:1":{"b": ["Yaghibasan, Malik of Sivas-Amasya, captured Unye, Samsun, and Bafra on the Black Sea coast", "11620be3"], "d": ["The Danishmendid Yaghibasan, in the same year as Ayn al-Dawla's raids in the south, undertook conquests in the Black Sea region and took Unye, Samsun, and Bafra; he later (1157) returned Bafra and Unye to the Byzantine Emperor Manuel.", "33a0b6d6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1150-04-30:0":{"b": ["The Ghurids burned the city of Ghazna", "c08860eb"], "d": ["The ever-strengthening Ghurids burned the city of Ghazna as an act of revenge (545/1150–51); although Bahram Shah regained control of the city in 547 (1152), the Ghaznavids entered a process of collapse.", "c85fc42c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1158-11-04:0":{"b": ["Abd al-Mu'min captured Tunis", "9382f0e8"], "d": ["Abd al-Mu'min took Tunis on 4 November 1158; he then consolidated his successes in northeastern Algeria.", "ffe4c30c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1168-01-01:0":{"b": ["Manuel Komnenos annexed Dalmatia to Byzantium", "85b42f07"], "d": ["Manuel Komnenos, who was continuing his wars with Hungary and Rascia, strengthened his position by conquering Dalmatia after the campaigns of the mid-1160s.", "5a38da3f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1171-01-01:0":{"b": ["The Venetian fleet subdued Dubrovnik and appointed a count", "8001f685"], "d": ["In reprisal for Manuel's arrest of the Venetians, the Venetian fleet, setting out in September 1171, attacked Dubrovnik (Ragusa) on the way; the city surrendered and received a \"count\" from Venice.", "c50776ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1174-01-01:0":{"b": ["The Georgians took Ani for the third time and annexed it to their country", "5d5d4822"], "d": ["The Georgians took the city of Ani in 1174 and annexed it to their country; in response the Shah of Ahlat, Sökmen, and the Seljuk army assembled at Nakhchivan in summer 1175 and conducted a campaign against Georgian lands.", "e730cb1f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1175-07-22:0":{"b": ["The Ayyubids conquered Aden; Zuray'id rule in Aden ended.", "14221ac7"], "d": ["The Ayyubids conquered Aden; Zuray'id rule in Aden ended.", "14221ac7"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1175-07-22:1":{"b": ["Herat passed into the hands of the Ghurids", "87be2dff"], "d": ["Herat came under Ghurid rule in 571 (1175–76); the Ghurid Sultan Ghiyath al-Din Muhammad had turned to the city at the invitation of the inhabitants, who were dissatisfied with the administration of the Seljuk Baha al-Din Tughril.", "bc183cf3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1178-06-19:0":{"b": ["With the Danishmendid lands joined to the Seljuk lands, the Anatolian Seljuk State became a great state", "dc51472f"], "d": ["One of Kilij Arslan II's important achievements was the elimination of the Danishmendids; the cities of central Anatolia such as Kayseri, Sivas, Niksar, Tokat, Amasya, and Malatya were annexed to the Seljuk lands in 574 (1178), and political and national unity was established.", "d208e2ea"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1183-06-11:0":{"b": ["Imad al-Din Zengi surrendered Aleppo to Saladin in exchange for other cities; northern Syria came under Ayyubid rule.", "68e158ff"], "d": ["Imad al-Din Zengi surrendered Aleppo to Saladin in exchange for other cities; northern Syria came under Ayyubid rule.", "68e158ff"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1184-04-14:0":{"b": ["The Banu Ghaniya invaded Bijaya, Algiers, Miliana, and Tunis", "f8aaec7b"], "d": ["The Banu Ghaniya (the continuation of the Almoravids), who had crossed to the Maghrib after submitting to the Abbasids, took advantage of the death of the Almohad ruler and invaded Bijaya, Algiers, Miliana, and Tunis (580/1184).", "c5f0e15e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1187-03-13:0":{"b": ["Abu Yusuf al-Mansur retook Tunis from the Banu Ghaniya", "d8aed3db"], "d": ["The Banu Ghaniya had invaded Bijaya, Algiers, Miliana, and Tunis in 580 (1184); al-Mansur retook Tunis in 583 (1187) but could not expel the Banu Ghaniya from the region entirely.", "299121d0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1196-01-01:0":{"b": ["Al-Mansur, after the victory of Alarcos, retook Wadi al-Hijara and besieged Toledo", "3af05642"], "d": ["Marching north in the wake of the victory of Alarcos, al-Mansur retook some cities and fortresses such as Wadi al-Hijara (Guadalajara) and Salamanca (1196); he also besieged Toledo but achieved no result.", "52b46e56"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1202-01-01:0":{"b": ["Suleyman Shah II made Elbistan a province directly attached to the center", "250007a3"], "d": ["During the Georgian campaign Suleyman Shah II took Erzurum from the Saltukids and gave it to his brother Tughril Shah; in return he made Elbistan a province directly attached to the center (1202).", "8bc24bea"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1202-06-25:0":{"b": ["Bayburt passed to the Anatolian Seljuk State when Saltukid rule ended", "2bd6fd25"], "d": ["When the Seljuks put an end to the Saltukid State in 1202 they took Bayburt as well; the city flourished in the time of Suleyman Shah's brother, the Malik of Erzurum Mughith al-Din Tughril Shah, and his son Jahan Shah (1202–1230).", "1679425b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1202-06-25:1":{"b": ["With the end of Saltukid rule, the Pasinler district was attached to the Erzurum maliklik of the Anatolian Seljuk State", "1866c54c"], "d": ["With Suleyman Shah II's ending of the Saltukid dynasty, the Saltukid cities around Erzurum were attached to the maliklik of Tughril Shah.", "a5ed047f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1202-11-15:0":{"b": ["The Fourth Crusade took and sacked Zadar (Zara)", "ae3b3d6c"], "d": ["The Crusaders, unable to pay their debts to Venice, took Zadar (Zara), a Dalmatian port that the Hungarian king had seized a few years earlier, on the proposal of Doge Dandolo in return for the postponement of the debt; the Christian city was sacked on 15 November 1202. This event is the first link of the chain that turned the direction of the campaign toward Constantinople.", "8373cba5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1203-01-01:0":{"b": ["Philippopolis passed into the hands of Kaloyan's Bulgarians", "2cad7aba"], "d": ["Philippopolis, which was plundered during the Third Crusade and again subjected to Crusader attacks in 1204, passed into the hands of the Bulgarians around 1203.", "1f767853"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1203-01-01:1":{"b": ["The Banu Ghaniya seize control of Tunis (sources give effective rule from the 1180s and 1203 as the year of full control).", "43c34e72"], "d": ["The Banu Ghaniya seize control of Tunis (sources give effective rule from the 1180s and 1203 as the year of full control).", "43c34e72"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1204-06-24:0":{"b": ["Rouen surrenders to Philip Augustus after forty days of resistance", "28930e8f"], "d": ["The siege of Château-Gaillard from September 1203 to April 1204 decided the fate of Normandy; Rouen, tied to England by trade, surrendered on 24 June 1204 after holding out for forty days.", "ab3b6e74"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1205-01-01:0":{"b": ["Thessalonica passed into Crusader hands: the Latin Kingdom of Thessalonica", "2d828a13"], "d": ["Twenty years after the Fourth Crusade the Crusader army captured Thessalonica and made the city the center of the Latin Kingdom of Thessalonica (1205–1225); the Orthodox churches (St Demetrius, Hagia Sophia) were converted into Catholic churches.", "5f84c9dd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1207-01-01:0":{"b": ["Corfu surrendered to Venice: a decarchy of Venetian nobles", "52536f06"], "d": ["The people of Corfu, who had resisted the attack of the Venetian fleet in 1205, surrendered only in 1207; the island was governed in the name of the Republic by a decarchy (a rule of ten men) of Venetian nobles.", "0226f2d5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1208-07-16:0":{"b": ["Herat passed to the Khwarazmshahs after a siege of thirteen months", "4449370f"], "d": ["Herat passed from the Ghurids to the Khwarazmshahs in 605 (1208–1209) after a siege of thirteen months; in 1221 the Mongols under Tolui took the city.", "74068fda"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1209-01-01:0":{"b": ["The Albigensian Crusaders take Carcassonne", "997d9e82"], "d": ["The viscounties of Carcassonne and Béziers were taken by the Crusaders in the Albigensian Crusade in 1209 on account of the role played by Viscount Raymond Roger against Simon de Montfort; the viscounty was confiscated by the crown in 1247.", "e3bff120"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1215-01-01:0":{"b": ["Ala al-Din Muhammad took Ghazna and gave it to his son Jalal al-Din; the atabegs of Fars and Azerbaijan submitted", "eec8d1fd"], "d": ["Ala al-Din Muhammad, who in the same year took Ghazna and gave it to his son Jalal al-Din, defeated the Atabeg of Fars, Sa'd b. Zangi, and the Atabeg of Azerbaijan, Uzbek, and secured their submission; the Khwarazmshahs established their dominion over a vast area extending from the banks of the Syr Darya to Iraq-i Arab.", "3da56cd9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1215-01-01:1":{"b": ["Simon de Montfort enters Toulouse", "3d0c7528"], "d": ["Simon de Montfort, the commander of the Albigensian Crusade, occupied Toulouse in 1215; he was killed in 1218 while besieging the city.", "b0855bb1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1225-01-13:0":{"b": ["Jalal al-Din Khwarazmshah campaigned against Georgia and captured Dvin", "f21c4c7c"], "d": ["Having obtained no result from his diplomatic efforts, Jalal al-Din Khwarazmshah captured Dvin in 622/1225; he also took the cities of Kerbi and Zun and returned to Azerbaijan.", "87f881e9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1226-01-02:0":{"b": ["Jalal al-Din Khwarazmshah reconquered Kars and its surroundings", "eebde7b0"], "d": ["Jalal al-Din Khwarazmshah's reconquest of Kars and its surroundings (623/1226), when the region was in the hands of the Georgians, aroused rejoicing in the Islamic world; after his death the city again passed into the hands of the Georgians.", "18efe000"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1227-04-01:0":{"b": ["Jalal al-Din Khwarazmshah conquered Tiflis", "f7c62046"], "d": ["Jalal al-Din Khwarazmshah, who set out on a Georgian campaign again the next year, conquered Tiflis in Rabi II 624 / April 1227; in the same year he besieged Ani and Kars.", "8ae90728"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1228-01-01:0":{"b": ["The Livonian Brothers of the Sword took Tallinn (from Denmark)", "8661af11"], "d": ["According to Treccani, Tallinn was taken in 1228 by the Order of the Brothers of the Sword and returned to the Danes in 1237.", "dba8cd73"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1228-06-29:0":{"b": ["Abu Zakariya Yahya al-Hafsi entered Tunis", "1d660546"], "d": ["Abu Zakariya, brother of Abu Muhammad Abdallah, the Almohad governor of Ifriqiya, entered Tunis on 24 Rajab 625 (29 June 1228); he gained control of the whole of Ifriqiya.", "92c01e17"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1229-11-20:0":{"b": ["Jalal al-Din Khwarazmshah defeated the Georgian-Armenian-Kipchak alliance near Lake Betak and entered Tiflis", "3fba9d59"], "d": ["Jalal al-Din, who was busy with the siege of Ahlat, learned from his vizier Sharaf al-Mulk that the Georgians were preparing to seize Tiflis; he confronted the allies, made up of Georgians, Armenians, and Kipchaks, near Lake Betak, neutralized the Kipchaks by diplomatic means, routed the Georgian army, and entered Tiflis (627/1229).", "828214cb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1231-01-01:0":{"b": ["The Mongols entered Georgia; Mongol administration was established in Tiflis", "5094244c"], "d": ["The Mongols entered Georgia in 1231; Queen Rusudan asked Pope Gregory IX for help and, obtaining no result, was forced to leave Tiflis. Mongol administration was established in Tiflis in 1231.", "2bda86aa"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1239-01-01:0":{"b": ["Danylo took Kiev and left the voivode Dmytro in charge", "64f0ec8f"], "d": ["In 1239 Danylo took Kiev, which had previously been in his sphere of influence, and appointed the voivode Dmytro as governor; a year later the Mongols would destroy the city.", "98ef76da"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1240-12-01:0":{"b": ["Batu Khan took and sacked Kiev; the end of Kievan Rus'", "51663baf"], "d": ["In December 1240 the Mongol-Tatar army of Batu Khan captured Kiev and massacred its population; Kiev, Volodymyr, and Halych were destroyed. Southern Russia was incorporated into the Mongol Empire (the Golden Horde). This event is regarded as the effective end of Kievan Rus'.", "c56cff05"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1243-04-02:0":{"b": ["Murcia surrendered to the Castilians", "54dab50b"], "d": ["Murcia, besieged in 1241, unable to obtain help from outside, surrendered within the framework of a treaty on 10 Shawwal 640 (2 April 1243).", "9d5993bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1244-04-19:0":{"b": ["The Castilians brought Murcia back under their rule after a revolt", "99abbc2c"], "d": ["The people of Murcia expelled the invaders a year later and declared allegiance to the Nasrids; the Castilians retook the city on 9 Dhu al-Qa'da 641 (19 April 1244).", "3c459339"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1244-10-20:0":{"b": ["Jerusalem was retaken from the Crusaders after the battle near Gaza (16 Jumada I 642).", "4f93e7d6"], "d": ["Jerusalem was retaken from the Crusaders after the battle near Gaza (16 Jumada I 642).", "4f93e7d6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1247-01-01:0":{"b": ["The viscounties of Carcassonne and Béziers are confiscated by the crown", "30bc26c8"], "d": ["The viscounty of Carcassonne (together with Béziers) was confiscated by the king in 1247 on account of the role played by Viscount Raymond Roger against Simon de Montfort in the Albigensian Crusade.", "65e41a74"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1247-01-01:1":{"b": ["al-Salih Ayyub retook Tiberias from the Crusaders", "367d8950"], "d": ["Tiberias was among the places that Imad al-Din Isma'il had left to the Crusaders before 1244; Sultan Ayyub retook Tiberias from the Crusaders in 1247.", "0698a41e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1248-04-26:0":{"b": ["Ferdinand III took Seville after a siege of eighteen months", "51d47adc"], "d": ["After years of wars and a siege of eighteen months, King Ferdinand III of Castile captured Seville (646/1248); some 400,000 people were forced to leave the region, and the Great Mosque was converted into a church.", "8b3923b7"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1248-04-26:1":{"b": ["The Marinids took Fez, Salé, and Taza", "72873723"], "d": ["The Marinids took Fez, Salé, and Taza from the Almohads in 646 (1248); between 1250 and 1255 the greater part of the Maghrib al-Aqsa passed out of Almohad hands.", "18b1696f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1251-03-26:0":{"b": ["The Marinids took Rabat and Salé", "f30ab4c7"], "d": ["The Marinid ruler Abu Yahya Abu Bakr b. Abd al-Haqq captured Rabat and Salé in 649 (1251).", "5d34514a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1262-01-01:0":{"b": ["Byzantium recovered the south of the Morea: Monemvasia, Mistra, Maina, and Geraki", "38ca5412"], "d": ["Villehardouin, captured at Pelagonia, ceded the fortresses of Monemvasia, Mistra, Maina (Mani), and Geraki to Byzantium in order to be freed; Byzantium regained its first permanent territory in the Morea, and Mistra would later become the center of the Despotate of the Morea.", "73396d3a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1273-07-18:0":{"b": ["The Marinids took Ceuta from the jurist al-Azafi", "68a6624d"], "d": ["After Tangier, Abu Yusuf captured Ceuta, which was under the administration of the jurist Abu al-Qasim al-Azafi; he thereby gained the opportunity to cross over to al-Andalus (672/1273–74).", "3a1acbeb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1273-07-18:1":{"b": ["The Marinids took Tangier", "2033c974"], "d": ["Abu Yusuf first captured Tangier in 672 (1273–74).", "65896d78"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1291-01-01:0":{"b": ["The Mamluks conquered Beirut", "da8771ff"], "d": ["Beirut, which had remained in the hands of the Crusaders until 1291, was conquered on this date in the name of the Mamluk Sultan al-Malik al-Ashraf Khalil by the Governor of Damascus, Emir Sanjar Abu Shuja'i.", "9eca78bc"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0534-01-01:0":{"b": ["Byzantium recovered Vandal Africa: Carthage again passed into the hands of the Eastern Romans", "ab2096c0"], "d": ["With the campaign of Justinian I's general Belisarius, North Africa was taken from the Vandals and Carthage again became a Byzantine city. The city would later be the centre of the Exarchate of Africa.", "319ada36"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0568-01-01:0":{"b": ["The Avars entered Pannonia: the Avar Khaganate settled in the Danube basin", "2471607b"], "d": ["After the fall of the Gepid state, the Avars under Bayan settled in Pannonia; the Danube–Tisza basin became the centre of the Avar Khaganate. In 626 the khaganate would besiege Constantinople and, together with the Slavs, launch raids into the Balkans.", "7074a5d1"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0568-04-01:0":{"b": ["Alboin's Lombards assembled to march on Italy (1 April 568)", "677663c6"], "d": ["The Lombards in Pannonia left their homeland to the Avars and assembled on 1 April 568, under Alboin's command, to migrate to Italy with their families and possessions. They crossed the Friuli frontier, took Cividale and destroyed Aquileia.", "11d42338"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0582-01-01:0":{"b": ["Maurice established the Exarchate of Africa: a military-civil administration centred on Carthage", "b4b43203"], "d": ["Maurice gave the magister militum in Africa the title of 'exarchos' and precedence over the civil administration; the emperor's deputy would govern from Carthage against Berber attacks.", "52939fe9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0582-01-01:1":{"b": ["Maurice established the Exarchate of Ravenna: the Byzantine lands in Italy were placed under a military governor", "6039bf5f"], "d": ["Emperor Maurice gave the Byzantine administration in Italy to an 'exarchos' regarded as the emperor's deputy against the Lombards; the centre was Ravenna. This arrangement is considered the first step of the later 'theme' system.", "543f687c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0610-10-05:0":{"b": ["Heraclius overthrew Phocas and ascended the throne", "8868d0c0"], "d": ["Heraclius, son of the exarch of Africa, came to Constantinople with the fleet; Phocas was seized and killed on the morning of 5 October 610, and Heraclius became emperor. His reign is remembered for the Persian war, the Arab conquests and the foundations of the 'theme' order.", "758b6d64"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0626-07-29:0":{"b": ["The Avars and Persians besieged Constantinople", "26f1fc15"], "d": ["The Avar khagan and his vassal tribes encamped before the walls of Constantinople on 29 July 626; the Persian army had also descended on the Asian shore. The city survived the siege through stiff resistance and the success of the fleet.", "f96ea122"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0674-01-01:0":{"b": ["The Umayyad fleet besieged Constantinople by land and sea (674-678)", "6242af3a"], "d": ["After Mu'awiya's fleet seized the Cyzicus peninsula, it began in 674 to besiege Constantinople by land and sea; the assault continued until 678.", "9b10c5be"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0717-03-25:0":{"b": ["Leo III ascended the throne: the Isaurian dynasty began", "a991b678"], "d": ["After the period of anarchy of 685-717, the strategos Leo, of Isaurian origin, became emperor on 25 March 717. Immediately afterwards Constantinople had to prepare for the great Arab siege.", "7b99e68e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0717-08-15:0":{"b": ["Maslama began the siege of Constantinople (15 August 717)", "ff3c52ac"], "d": ["The Umayyad commander Maslama crossed the strait from Abydos and besieged Constantinople on 15 August 717 with an army of about 180,000 men and a great fleet. The Bulgar Khan Tervel helped Byzantium by attacking Arab forces in Thrace.", "1b3e9a30"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0718-08-15:0":{"b": ["The second Arab siege of Constantinople was lifted", "ed916ed1"], "d": ["In the face of famine, cold, epidemic and Bulgar attacks, Maslama withdrew on 15 August 718, exactly one year later, on the order of Caliph Umar II. This success halted the Arab advance in Europe.", "9a305e2f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0782-01-01:0":{"b": ["Irene made peace with Harun al-Rashid: Constantinople was saved from danger", "7fcd8ae6"], "d": ["When the army of the Abbasid commander Harun al-Rashid advanced as far as Chalcedon, Empress Irene signed a peace treaty and the capital was freed from the Arab threat.", "7ffffb25"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0787-09-24:0":{"b": ["The Seventh General (Ecumenical) Council met at Nicaea: iconoclasm was condemned", "124c1212"], "d": ["At the call of Empress Irene, about 350 bishops assembled in the Church of Hagia Sophia (Holy Wisdom) at Nicaea and condemned iconoclasm. This is the last council that the Orthodox Church counts as ecumenical.", "8444f8b3"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0800-12-25:0":{"b": ["Charles was crowned emperor at Rome by the pope; Byzantium did not recognize it", "5ac5f7a9"], "d": ["The Frankish king Charles was proclaimed 'emperor of the Romans' on 25 December 800 by being crowned by Pope Leo III. When Byzantium did not recognize Charles's imperial title, the duality between the Eastern and Western states came clearly into the open.", "dde987c7"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0813-06-22:0":{"b": ["Battle of Versinikia: Michael Rangabe was defeated by Krum", "cc6f63ec"], "d": ["Michael I Rangabe was defeated by the Bulgars at Versinikia near Adrianople on 22 June 813; the defeat had apparently been prepared by the attitude of the Armenian Leo, strategos of the Anatolikon. Krum came before Constantinople in the same year.", "2d3099f5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0814-04-14:0":{"b": ["Khan Krum died: preparations for the siege of Constantinople were left unfinished", "1dde895f"], "d": ["While Krum was preparing a great army equipped with numerous siege engines against Constantinople, he died on 14 April 814 of a sudden rupture of a blood vessel. His son Omurtag made a thirty-year peace with Byzantium.", "e1b684e8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0827-04-02:0":{"b": ["The Andalusian Arabs settled in Crete: the Emirate of Crete was born", "2a7c0adc"], "d": ["The Andalusian Arabs, who had been expelled after the Revolt of the Suburb in Cordoba, came to Crete under the command of Abu Hafs Umar b. Shu'ayb, seized the island gradually and founded the city of Rabdh al-Khandaq (Chandax). The line of Abu Hafs ruled on the island until 961.", "11e895b0"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0860-06-18:0":{"b": ["The Rus appeared before Constantinople for the first time", "43b4ec06"], "d": ["About two hundred Rus ships entered the Bosporus from the Black Sea and attacked Constantinople on 18 June 860; the emperor was on the Arab frontier with his army. A storm scattered the Rus fleet.", "6370f840"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0867-01-01:0":{"b": ["The Aghlabid fleet besieged Dubrovnik; the city was saved by the Byzantine fleet", "9ed0c1d7"], "d": ["A fleet of the Aghlabids, who ruled Sicily, besieged Dubrovnik in 867; the city was saved from a siege lasting fifteen months with the help of the Byzantine fleet. With this victory Byzantium consolidated its superiority in the Adriatic.", "1cbf391c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0904-07-31:0":{"b": ["The Cretan fleet seized and plundered Thessalonica", "d4ce556a"], "d": ["The Arab fleet under the command of Leo of Tripoli, a renegade, took Thessalonica on 31 July 904 after a three-day siege; it returned unpursued with more than 30,000 prisoners and booty. This event showed the weakness of the Byzantine fleet.", "f9cb1530"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0913-01-01:0":{"b": ["The Bulgarian Tsar Simeon came before the walls of Constantinople", "4e338292"], "d": ["Simeon pressed up to the walls of Constantinople with the aim of obtaining the Byzantine crown; the government came to an agreement with him by making heavy concessions, and he was given the title 'Basileus of the Bulgarians'.", "0cce5551"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0924-01-01:0":{"b": ["Simeon besieged Constantinople again", "452b0447"], "d": ["Simeon besieged Constantinople again in 924; the diplomacy of Romanos I averted this danger too.", "90de8672"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0926-01-01:0":{"b": ["Tomislav, King of the Croats, routed the Bulgarian army", "21d8e44f"], "d": ["The Bulgarian Tsar Simeon attacked Croatia, an ally of Byzantium, but his army was defeated and scattered by Tomislav, King of the Croats. This victory consolidated the authority of the Croatian kingdom over the Dalmatian cities.", "60abf25d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0927-05-27:0":{"b": ["Tsar Simeon died: the age of Bulgaria's great wars closed", "ff2c1a5e"], "d": ["Simeon, who was compelled to seek peace through the mediation of the pope, died suddenly on 27 May 927. His death changed the balance in the Balkans; for the next sixty years Bulgaria played no active role in the region.", "3e140fec"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0927-09-08:0":{"b": ["Byzantine-Bulgarian peace: Simeon's son Peter married a Byzantine princess", "5f781f16"], "d": ["With the peace signed in the autumn of 927 after Simeon's death, Simeon's son and successor Peter married Maria Lekapene, granddaughter of Romanos I; Byzantium recognized him as 'emperor of the Bulgarians' and also accepted the independent Bulgarian Patriarchate. A long period of peace began between the two states.", "08bf5989"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0963-08-16:0":{"b": ["Nikephoros Phokas became emperor", "1e752d7a"], "d": ["Nikephoros, proclaimed emperor by the army of Caesarea, entered the capital on 14 August 963; after street fighting with the palace guards he ascended the throne on 16 August. His reign is remembered for the conquests of Crete, Cilicia and Antioch.", "b34380fd"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0969-12-10:0":{"b": ["Nikephoros Phokas was murdered; John Tzimiskes became emperor", "1232f3d1"], "d": ["Six weeks after the conquest of Antioch, in the night of 10-11 December 969, Nikephoros II Phokas was killed in a palace assassination; John Tzimiskes (969-976) succeeded him.", "485e7a85"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0971-04-23:0":{"b": ["Before Dorostolon (Silistra) Tzimiskes defeated Svyatoslav", "692f203b"], "d": ["On 23 April 971, Tzimiskes engaged Svyatoslav's Rus army in a great battle on the plain twelve miles south of Dorostolon; the Rus forces were routed and a siege lasting three months began in the city.", "9a082cf5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0986-08-17:0":{"b": ["Battle of the Gates of Trajan: Basil II suffered a heavy defeat against the Bulgarians", "9060af56"], "d": ["Basil II's march on Serdica (Sofia), because it was badly prepared and his commanders were at odds, ended in a heavy defeat at the Gates of Trajan pass on 17 August 986; the emperor barely escaped.", "7c003379"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1001-01-01:0":{"b": ["Basil II took Sofia", "3006324b"], "d": ["During Basil II's annual campaigns, Byzantium seized Sofia, which was held by the Bulgarian state, in 1001; Vidin, Skopje and other fortresses then fell.", "52c0acb4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1003-01-01:0":{"b": ["Vidin surrendered to Byzantium after a siege of eight months", "4394c5b7"], "d": ["After the collapse of the Bulgarian state, Vidin resisted the Byzantine forces until 1003; it was taken after a siege of eight months. Byzantine rule lasted until 1185.", "7e2d95ee"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1014-07-29:0":{"b": ["Battle of Kleidion: Basil II destroyed the Bulgarian army", "c8375830"], "d": ["On 29 July 1014, Nikephoros Xiphias outflanked the Bulgarian position at the pass of Kleidion ('the Key') in the Belasitsa mountains in the Strymon valley. Samuel escaped to Prilep with the help of his son; about 15,000 captured Bulgarian soldiers were blinded.", "a7b90e39"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1014-10-06:0":{"b": ["Tsar Samuel died", "a71a0c57"], "d": ["On seeing the blinded soldiers of his army defeated at Kleidion, Samuel suffered a seizure and died two days later, on 6 October 1014. The capital of the Western Bulgarian Empire was Ohrid; resistance continued for four more years.", "b75e105a"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1018-01-01:0":{"b": ["All Bulgarian lands were annexed to Byzantium: the First Bulgarian State came to an end", "62e8f992"], "d": ["After Ivan Vladislav was killed before Dyrrhachion, at the beginning of 1018 Basil II accepted at the gates of Ohrid the surrender of the family of the last tsar, and the Bulgarian lands as far as the Danube became entirely a Byzantine province. This situation lasted until 1186-1187.", "7686035c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1018-01-01:1":{"b": ["Ivan Vladislav died before Dyrrhachion", "75e41587"], "d": ["Ivan Vladislav (1015-1018), the Bulgarian tsar who had killed Gavril Radomir and taken the throne, was killed in a futile assault on Dyrrhachion (Dyrrachium). When the news reached Constantinople, Basil II set out on his last campaign, and at the gates of Ohrid the family of the last tsar surrendered.", "38a7f246"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1040-01-01:0":{"b": ["Revolt of Peter Delyan: many fortresses, including Skopje, fell into the hands of the rebels", "7fef5f4f"], "d": ["The discontent that grew when taxes were changed from payment in kind to money turned into a revolt under the leadership of Peter Delyan, a grandson of Samuel. The rebels advanced south from Belgrade and, with the support of the local boyars, took many fortresses, including Skopje.", "86258b6e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1040-01-01:1":{"b": ["Stefan Vojislav began the independence movement in Duklja", "ab16166f"], "d": ["Stefan Vojislav's first revolt in 1036 had been suppressed and he had been taken to Constantinople; upon the revolt of Peter Delyan in Macedonia he fled in 1040 and took the lead of a new liberation movement in Duklja. Although Byzantium suppressed Delyan, it could not renew its authority over Duklja, and the region remained independent for a long time.", "d1357c04"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1042-01-01:0":{"b": ["George Maniakes landed at Taranto as catepan of Italy", "6281a936"], "d": ["George Maniakes, whom Michael V had released from prison and made 'magistros and catepan', arrived at Taranto at the end of April 1042, during the joint rule of Zoe and Theodora; his campaigns against the Norman and Apulian rebels were left unfinished when he was dismissed in September 1042.", "926b3102"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1054-07-20:0":{"b": ["East-West Schism (Great Schism)", "22d54273"], "d": ["With Patriarch Michael Cerularius's severing of ties with Rome, the centuries-old dispute between the churches of Rome and Constantinople turned into a definitive separation.", "6de367fc"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1059-01-01:0":{"b": ["Synod of Melfi: the pope confirmed the Norman conquests", "df9797bd"], "d": ["Nicholas II reversed the Eastern policy and at the Synod of Melfi made an alliance with the Normans and confirmed their conquests. This agreement sanctified the Norman rise that threatened the Byzantine presence in southern Italy.", "456db916"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1071-01-01:0":{"b": ["Bari fell to the Normans: Byzantium lost Italy", "75af6d4d"], "d": ["After a siege lasting three years, Bari, Byzantium's last fortress in southern Italy, surrendered to the Normans of Robert Guiscard; thus Byzantium lost its presence in Italy.", "03196667"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1071-08-26:0":{"b": ["Battle of Manzikert: Alp Arslan defeated the Byzantine army, Romanos IV was captured", "9ed92850"], "d": ["The Turkish forces of Sultan Alp Arslan defeated at Manzikert on 26 August 1071 the Byzantine army, which consisted for the most part of Norman, Frankish, Oghuz and Pecheneg mercenaries. Emperor Romanos IV was captured; the process of the opening of Anatolia to the Turks began.", "d260a768"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1081-04-01:0":{"b": ["Alexios Komnenos entered Constantinople: the Komnenian dynasty began", "2c31c531"], "d": ["The troops of Alexios, whom the military aristocracy had proclaimed emperor, entered Constantinople on 1 April 1081. Alexios's reign (1081-1118) passed amid Norman, Pecheneg and Crusader threats.", "89144267"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1082-01-01:0":{"b": ["Constantine Bodin became ruler of Duklja; he subjugated Raška and Bosnia", "4eff1f06"], "d": ["Constantine Bodin, son of Michael (c. 1050-82, who had received the title of king from Pope Gregory VII and raised the bishopric of Bar to an archbishopric), ascended the throne around 1082 and conquered Raška and Bosnia and placed his own candidates there. Thus Duklja embraced almost all the lands inhabited by the Serbs; the state quickly dissolved through dynastic quarrels.", "813bc53b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1091-01-01:0":{"b": ["Slavonia was joined to Hungary", "35eb29f1"], "d": ["At the end of the eleventh century, Croatian dynastic quarrels led to union with Hungary, and the northern region of Slavonia was partly joined to Hungary (1091).", "4e53ab25"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1118-08-16:0":{"b": ["John II Komnenos was crowned", "255f3655"], "d": ["Amid the death of his father Alexios and court rivalries, John became emperor by being crowned on 16 August 1118. His reign passed in campaigns against the Pechenegs, the Seljuks and Cilicia.", "25043caf"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1122-01-01:0":{"b": ["John II decisively defeated the Pechenegs near Stara Zagora", "3e585237"], "d": ["The Pechenegs, who had advanced as far as Thrace, were decisively defeated by John II Komnenos in 1122; with this victory the western frontier was secured.", "52eb72c6"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1137-01-01:0":{"b": ["John II brought Cilicia under Byzantine rule: Mopsuestia (Misis) was taken", "e09dfcbc"], "d": ["With his campaign of 1137-1138, John II Komnenos brought under obedience the Cilician plain and the Taurus regions held by the Armenian Rubenid principality; Byzantine superiority over Antioch was also partly secured.", "266b1fc5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1159-01-01:0":{"b": ["Manuel Komnenos entered Antioch in ceremony", "6a943bb7"], "d": ["With his Cilician and Syrian campaign of 1158-1159, Manuel Komnenos again demonstrated Byzantine superiority over the Crusader Principality of Antioch; his ceremonial entry into Antioch is regarded as the peak of his rule.", "670785eb"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1171-03-12:0":{"b": ["Manuel Komnenos had all the Venetians in the empire arrested", "0b1087c4"], "d": ["Disturbed by Venice's policy in Italy and Dalmatia, Manuel ordered on 12 March 1171 the arrest of all the Venetians in the empire and the confiscation of their property. Venice responded by sending a fleet.", "01a7fe6d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1172-01-01:0":{"b": ["Manuel defeated Nemanja and took him to Constantinople: the Serbs accepted Byzantine superiority", "85c3545e"], "d": ["When Stefan Nemanja, Grand Župan of Raška (Rascia), rose against Byzantium, Manuel defeated him in 1172 and took him in triumph to Constantinople; he was later released and caused no trouble until Manuel's death.", "dea0829e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1180-01-01:0":{"b": ["Stefan Nemanja made the Serbian state independent", "8df8e6f5"], "d": ["Taking advantage of the confusion created by Manuel's death, Stefan Nemanja made Raška (Rascia) the nucleus and laid the foundation of a great Serbian state that also included Zeta and Hum; he retained the title 'Grand Župan'. His dynasty is called the 'Nemanjić'.", "5d62e581"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1180-09-24:0":{"b": ["Manuel Komnenos died", "ef8d68b9"], "d": ["Manuel I died on 24 September 1180; he had refused to arrange the regency until the last moment. The years 1180-1204 showed that the Eastern Roman Empire had lost the supremacy it had held in the Middle Byzantine period.", "3909f514"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1182-01-01:0":{"b": ["The Latins were massacred in Constantinople; Andronikos Komnenos came to power", "cdf8aa39"], "d": ["With a popular uprising the regency of Manuel's widow ended, the Latin merchants were subjected to massacre, and Andronikos Komnenos rose to power (1182-1185). The massacre increased the West's hostility to Byzantium.", "e1babdc2"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-01-01:0":{"b": ["The Normans seized and plundered Thessalonica", "0389d7b9"], "d": ["The Normans, coming from Sicily and southern Italy, attacked Thessalonica by land and sea in August 1185 with a fleet of 200 ships and an army; the city was dreadfully plundered. In the capital this news hastened the uprising against Andronikos.", "f309d689"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-01-01:1":{"b": ["Revolt of Peter and Asen: the foundation of the Second Bulgarian State around Tarnovo", "fca2ce92"], "d": ["The boyar brothers Peter and Asen rose against Byzantine taxes around Tarnovo; although the emperor retook the lands in 1186, the brothers recovered northern Bulgaria with an army they obtained from the Cumans beyond the Danube, and in 1187 Byzantium was forced to make peace.", "d0471819"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-09-12:0":{"b": ["Isaac II Angelos ascended the throne", "e5f6e2dd"], "d": ["On learning that Thessalonica had been taken by the Normans, the people of Constantinople rose against Andronikos Komnenos and placed Isaac Angelos on the throne on 12 September 1185. The period of the Angelos dynasty (1185-1204) began.", "d2f55a2e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1189-01-01:0":{"b": ["Frederick Barbarossa took Didymoteicho and massacred its people", "d38b78a4"], "d": ["During the Third Crusade, the German Emperor Barbarossa took Didymoteicho in 1189 and massacred all its people (about 1,500) except for women and children.", "e843c9c5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1190-01-01:0":{"b": ["The Bulgarians defeated Isaac Angelos", "ab4b84df"], "d": ["While the Serbian and Bulgarian rulers hoped for support from Barbarossa, who was going to Anatolia, Isaac Angelos was defeated by the Bulgarians near Stara Zagora and barely escaped. The Bulgarians took Sofia and carried the relics of Saint John of Rila to Tarnovo.", "87219877"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1197-01-01:0":{"b": ["Kaloyan ascended the Bulgarian throne", "ad96cfe5"], "d": ["After the murder of Asen (1196) and Peter (1197), their brother Kaloyan (Ioannitsa) ascended the Bulgarian throne in 1197; he ruled until 1207, expanded Bulgaria and established relations with the papacy.", "5adc869f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-04-08:0":{"b": ["Ban Kulin gave an assurance of loyalty to the Catholic faith (Bilino Polje)", "30e1a588"], "d": ["When Kulin, Ban of Bosnia (c. 1180-1204), was accused of sheltering the Patarenes (Bogomils), Pope Innocent III asked the Hungarian king to purge them. On 8 April 1203, in the presence of the papal legate, Kulin gave an assurance of loyalty to Catholic doctrine.", "1bdcf7f6"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-07-17:0":{"b": ["The Crusaders entered Constantinople; Isaac II and Alexios IV were seated on the throne", "e315ae7a"], "d": ["The armies of the Fourth Crusade attacked Constantinople on 17 July 1203 and made Alexios III flee; Isaac II was raised to the throne again together with his son Alexios IV. The promises that Alexios made to the Crusaders could not be fulfilled afterwards.", "6742de22"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-08-01:0":{"b": ["Alexios IV Angelos was crowned as co-emperor", "89f1f57b"], "d": ["Alexios, under the protection of the Crusaders, was crowned as co-emperor with his father Isaac II in Hagia Sophia on 1 August 1203. He could not fulfil the promises he had made to the Crusaders.", "88f53483"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:0":{"b": ["Athens fell into the hands of the Crusaders: Othon de la Roche became lord of Athens", "b38757d9"], "d": ["In the campaign of Boniface, Marquis of Montferrat, the Burgundian Othon de la Roche became lord of Athens at the end of October or in November 1204. Athens became part of Latin Greece as the Duchy of Burgundy (later the Duchy of Athens); the Parthenon was made a Catholic cathedral.", "47e8140e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:1":{"b": ["Negroponte (Euboea) passed to the Latins", "3ac87cb5"], "d": ["In the campaign of Boniface, Marquis of Montferrat, in the autumn of 1204, Latin knights crossed from Boeotia and Attica to the island of Euboea; in the first partition the island was divided between the Venetians and the Crusaders.", "56fb0f97"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:2":{"b": ["Gallipoli came under Latin administration", "e94882ae"], "d": ["After the Fourth Crusade, Gallipoli came under the administration of the Latins (the Venetians and the Latin Empire) in 1204; it would be taken back in 1235 by John Vatatzes.", "1561323c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:3":{"b": ["Michael Angelos founded the Despotate of Epirus; Ioannina became the centre", "053487d5"], "d": ["After the Fourth Crusade, Michael Komnenos Doukas Angelos, a relative of Isaac II and Alexios III, founded an independent Greek state around Arta and Ioannina; the state is the Despotate of Epirus, which would live until 1430. Michael survived at first by relying on diplomacy with Venice and the papacy.", "738fe372"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-02-08:0":{"b": ["Alexios V Murtzouphlos ascended the throne", "1a09c827"], "d": ["With a palace coup Alexios IV and his father Isaac II were deposed, and Murtzouphlos, the son-in-law of Alexios III, became emperor with the title Alexios V. The Crusaders regarded this as a challenge and decided to take the city.", "a18f3330"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-04-13:0":{"b": ["The Fourth Crusade captured Constantinople", "684dcd71"], "d": ["A week after the halting of the first assault on 6 April, the Crusaders and the Venetians entered Constantinople on 13 April 1204; the city was plundered for three days and half of it was destroyed by fires. The Byzantine Empire was broken up; three small Byzantine states emerged at Nicaea, Trebizond and Epirus.", "0faa7103"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-05-16:0":{"b": ["Baldwin, Count of Flanders, was crowned: the Latin Empire was founded", "39f062a5"], "d": ["Eight days after the election, on 16 May 1204, the Crusaders crowned Baldwin, Count of Flanders and Hainaut, as emperor in Hagia Sophia. The Venetian Thomas Morosini was appointed Latin Patriarch, and the imperial lands were divided between the Crusaders and the Venetians.", "c1dcef9e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-11-08:0":{"b": ["Kaloyan received a royal crown at Tarnovo from the papal legate", "791d9635"], "d": ["At the end of his negotiations with Pope Innocent III, Kaloyan was crowned king (rex) at Tarnovo on 8 November 1204 by the papal legate Cardinal Leo with a crown brought from Rome; the next day the archbishop of Tarnovo was consecrated as 'primate'.", "2055a2ef"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1205-04-15:0":{"b": ["Battle of Adrianople: Kaloyan defeated and captured the Latin Emperor Baldwin", "d320c946"], "d": ["During the uprisings that broke out upon the capture of Constantinople by the Latins, the Latin army before Adrianople was routed by the joint Byzantine-Bulgarian forces; Emperor Baldwin was captured and taken to Tarnovo. This defeat was the first great blow to the Latin Empire.", "1af0cda8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1205-11-19:0":{"b": ["Principality of Achaea (the Morea): William of Champlitte was called 'Prince of Achaea'", "ef90dab0"], "d": ["The conquest of the Morea by Geoffrey of Villehardouin and William of Champlitte (the victory at Koundoura) contributed to the passing of most of Greece into the hands of the Crusaders at the beginning of 1205. Innocent III's letter of 19 November 1205 refers to Champlitte with the title 'prince'; thus the Principality of Achaea is documented. Villehardouin took the title of prince before the end of 1209.", "44588e3a"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1206-01-01:0":{"b": ["Kaloyan attacked Didymoteicho twice; the walls were demolished", "5a4dd23b"], "d": ["The Bulgarian army under Tsar Kaloyan invaded Thrace at the beginning of 1206 and attacked Didymoteicho twice; in the second assault the walls of the besieged city were demolished. The defence had been entrusted to the Greek units of Theodore Branas.", "b00f7e1e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1206-08-20:0":{"b": ["Henry of Flanders was crowned Latin Emperor", "ffd08538"], "d": ["Henry, brother and regent of the captive Baldwin, was crowned in Hagia Sophia on 20 August 1206 by the new Latin Patriarch Thomas Morosini. Henry is regarded as the most capable ruler of the Latin Empire.", "350bed68"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1207-01-01:0":{"b": ["Marco Sanudo founded the Duchy of Naxos (Duchy of the Archipelago)", "79faa9e1"], "d": ["Marco Sanudo, nephew of the Venetian Doge Dandolo, landed in the Aegean islands with an adventurous band; seventeen islands surrendered easily, only Naxos resisted, and the duchy founded there in 1207 lasted more than three centuries. Sanudo himself offered his allegiance not to Venice but to the Latin Emperor Henry.", "02fd4630"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1207-10-08:0":{"b": ["Kaloyan died during the siege of Thessalonica", "d5427396"], "d": ["The Bulgarian Tsar Kaloyan died on 8 October 1207, in a manner still unexplained, while making a new assault on Thessalonica. With this death the harsh period of Bulgarian-Latin conflicts closed; the throne of Tarnovo passed to Boril.", "e6029330"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1210-06-20:0":{"b": ["Michael, Despot of Epirus, became subject to the Doges of Venice", "669ad38d"], "d": ["Faced with the threat of the Latin Emperor Henry, Michael Doukas signed an agreement with Doge Pietro Ziani on 20 June 1210, accepting that Venice leave to him and his heirs Epirus, Acarnania and Aetolia; thus he preserved his state as a vassal of Venice.", "5d11e9b1"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1216-06-11:0":{"b": ["The Latin Emperor Henry died at Thessalonica", "929c3cd5"], "d": ["The Latin Emperor Henry died suddenly at Thessalonica on 11 June 1216 before reaching the age of forty; in his reign of ten years he had strengthened the Latin Empire. In July of the same year Pope Innocent III also died; the wind of the Fourth Crusade had died down.", "6070f6e0"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1217-04-09:0":{"b": ["Peter of Courtenay was crowned Latin Emperor at Rome", "f36d8586"], "d": ["Peter of Courtenay, chosen after Henry's death, was crowned by Honorius III on 9 April 1217 at Rome in the church of San Lorenzo; the pope held the ceremony outside the city walls so as not to confuse the titles of the Eastern and Western empires. He then set out for Dyrrachium with Venetian ships.", "98fb2727"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1221-03-25:0":{"b": ["Robert of Courtenay was crowned at Constantinople", "932b6236"], "d": ["After the death of Empress Yolanda in 1219, the Latin throne passed to her second son Robert of Courtenay; Robert was crowned at Constantinople on 25 March 1221 by the new Latin Patriarch Matthew.", "bf2f3298"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1225-01-01:0":{"b": ["The Latin Kingdom of Thessalonica came to an end: Thessalonica passed to Epirus", "1ae95078"], "d": ["The Latin Kingdom of Thessalonica (1205-1225), founded by Boniface, was destroyed when Theodore Angelos, Despot of Epirus, took Thessalonica and assumed the title 'King and Emperor of the Romans'. Theodore founded the Empire of Thessalonica and entered into rivalry with Nicaea for Constantinople.", "fe098325"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1228-01-01:0":{"b": ["Nicomedia (İzmit) again came under Byzantine (Nicaean Empire) rule", "249950f8"], "d": ["Nicomedia (İzmit), which for a long time changed hands between Byzantium and the Latins, came under the rule of the Empire of Nicaea in 1228.", "a051dabd"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1229-01-01:0":{"b": ["John of Brienne was elected Latin Emperor", "df313398"], "d": ["With Robert's death in the Morea (1228) and Baldwin II being a child, John of Brienne, the former King of Jerusalem, was elected to the empire the following year. John heroically defended Constantinople against the Bulgarian-Nicaean siege.", "2316312e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1230-01-01:0":{"b": ["Klokotnitsa: Ivan Asen II defeated and captured Theodore, Despot of Epirus; Didymoteicho came under Bulgarian rule", "514365f5"], "d": ["In April 1230 at Klokotnitsa on the Adrianople-Philippopolis road, the Bulgarian Tsar Ivan Asen II defeated and captured Theodore Angelos; the power of the Empire of Thessalonica was broken, and Bulgaria grew in Thrace and Macedonia. Didymoteicho remained under Bulgarian rule between 1230 and 1246.", "40e19d64"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1235-01-01:0":{"b": ["The Bulgarian Patriarchate was re-established", "2390176f"], "d": ["The Bulgarian Patriarchate was revived in 1235.", "d24362c4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1235-01-01:1":{"b": ["Gallipoli passed into the hands of John III, Emperor of Nicaea", "3687c283"], "d": ["Gallipoli, in Latin hands since 1204, was taken back in 1235 by John (John III Vatatzes, Emperor of Nicaea).", "623f8bea"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1236-01-01:0":{"b": ["Greek and Bulgarian armies besieged Constantinople; the Prince of the Morea, Geoffrey II, saved it", "a07ee4a8"], "d": ["In 1236 Ivan Asen and John Vatatzes besieged Constantinople again; the Latins were at their last gasp, but the Prince of Achaea, Geoffrey II of Villehardouin, hurried from the Morea and joined in the defence of the city, and the siege was lifted.", "2c66c5d9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1241-01-01:0":{"b": ["Ivan Asen II died: the decline of Bulgaria began", "1b1fa198"], "d": ["The Bulgarian Tsar Ivan Asen II died in 1241; in the same year the Tatars attacked the country, and the Bulgarian state gradually weakened because of the quarrels of the boyars.", "6b44149b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1246-01-01:0":{"b": ["Didymoteicho came under Byzantine (Nicaean Empire) administration", "b0220eb0"], "d": ["Didymoteicho, under Bulgarian rule since 1230, came under Byzantine administration in 1246 with the Thracian campaign of John Vatatzes.", "50e64103"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1246-01-01:1":{"b": ["Thessalonica was annexed to the Empire of Nicaea: the Empire of Thessalonica came to an end", "1f9b3c28"], "d": ["In 1246 John Vatatzes crossed into Thrace and seized the lands occupied by the Bulgarians and Thessalonica; the Thessalonian state of Theodore Angelos's sons John and Demetrios was destroyed, and Macedonia again came under Byzantine/Nicaean rule.", "26edc699"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1257-01-01:0":{"b": ["Rostislav took Vidin and assumed the title of Bulgarian tsar", "19935b89"], "d": ["Rostislav, stepson of the Hungarian king, seized Vidin in 1257 and took the title of Bulgarian tsar.", "9e6e94f4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1259-01-01:0":{"b": ["Battle of Pelagonia: Michael Palaiologos defeated the Epirote-Achaean-Sicilian alliance", "eb3a201d"], "d": ["Michael VIII routed the combined army of Sicily, Epirus, Achaea and the Serbian kings on the plain of Pelagonia (western Macedonia); William of Villehardouin, Prince of Achaea, was captured. The victory prepared the end of the Latin Empire.", "18641aca"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1259-01-01:1":{"b": ["Michael VIII Palaiologos was proclaimed emperor at Nicaea", "5875ecef"], "d": ["Michael Palaiologos, regent of the young John IV Laskaris in the Empire of Nicaea, was proclaimed co-emperor on 1 January 1259; the Palaiologan dynasty (1259-1453) thus began.", "3627dde8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-03-13:0":{"b": ["Treaty of Nymphaion: Genoa promised Byzantium a fleet for the recovery of Constantinople", "a094d9f0"], "d": ["By the treaty signed at Nymphaion on 13 March 1261 between Michael VIII and Genoa, the Genoese merchants would become heirs to Venice's former privileges if Constantinople were recovered.", "6b7cc95c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-07-25:0":{"b": ["Nicaean troops recovered Constantinople: the Latin Empire came to an end", "2c768188"], "d": ["On 25 July 1261 Nicaean troops burned the Latin quarter on the shore of the Golden Horn, opened a gate in the wall from the inside and entered the city. Fifty-seven years of Latin rule came to an end, and Byzantium was re-established.", "a7d71b53"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-08-15:0":{"b": ["Michael VIII was crowned in Hagia Sophia", "ff8bdbd5"], "d": ["Michael VIII entered the city through the Golden Gate before the icon of the Hodegetria, marched in procession, and was crowned in Hagia Sophia on 15 August 1261. The Palaiologan dynasty remained in power until the end of the empire.", "8b4dbff9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1265-01-01:0":{"b": ["Michael VIII made Epirus accept Byzantine superiority (Ioannina)", "725f54aa"], "d": ["Michael Palaiologos took part of Macedonia from the Bulgarians in 1264 and, by seizing Ioannina in 1265, made the Despotate of Epirus accept the empire's sovereignty.", "3f3bbd15"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1267-05-24:0":{"b": ["Villehardouin bound the Principality of Achaea to Charles of Anjou (Viterbo)", "3c8a26a9"], "d": ["At Viterbo on 24 May 1267, with the consent of the Latin Emperor Baldwin II, William of Villehardouin, Prince of Achaea, transferred the principality to Charles of Anjou, King of Sicily; William would remain in the principality for life, and his daughter Isabella would marry Charles's son Philip. If no male heir were born, the principality would pass to the Angevin dynasty of Naples; thus the Morea would be protected from being lost to Palaiologos.", "124a7b0f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1272-01-01:0":{"b": ["Charles of Anjou occupied Dyrrachium and the coasts of Epirus", "64aaba29"], "d": ["Charles of Anjou occupied Corfu in 1267 and Dyrrachium and the coasts of Epirus in 1272; he then came to an agreement with the Serbs and Bulgarians. This threat forced Michael VIII into a church union with the papacy.", "98ea3c00"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1272-01-01:1":{"b": ["The rule of Jacob Svetoslav, a Hungarian vassal, at Vidin came to an end", "2cf90f4e"], "d": ["In June 1266 a Hungarian army took Vidin and destroyed the region; Jacob Svetoslav, of Rus origin, remained in power as a vassal of Hungary with the title of Bulgarian tsar until 1272, after which Vidin weakened and did not recover for a long time.", "aeb24b65"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1274-07-06:0":{"b": ["Second Council of Lyon: Byzantium accepted the pope's supremacy", "7603205f"], "d": ["At the ultimatum of Pope Gregory X, the Grand Logothete George Akropolites accepted at Lyon on 6 July 1274, on behalf of the emperor, papal supremacy and the Roman faith. The union broke down in 1281.", "879a4291"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1278-05-01:0":{"b": ["William of Villehardouin died: the Principality of Achaea passed to the Angevins", "e4eac0d2"], "d": ["William, Prince of Achaea, died on 1 May 1278, and by the Viterbo arrangement of 1267 the principality directly belonged to the Angevin dynasty (until 1289). Charles of Anjou added the Prince of Achaea to his titles.", "f789577b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-01-01:0":{"b": ["Before Berat the Byzantine army broke the Angevin siege", "745cab6e"], "d": ["In 1281 before Berat the Byzantine army won a victory against the Angevin forces.", "ccb74513"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-07-03:0":{"b": ["Treaty of Orvieto: Anjou, Venice and the Latin Emperor Philip formed an alliance against Byzantium", "b9000a4a"], "d": ["Under the protection of Pope Martin IV, Charles of Anjou concluded on 3 July 1281 at Orvieto an alliance treaty against Byzantium with Philip (son of Baldwin II), who bore the title of Latin Emperor, and the Republic of Venice. The Sicilian Vespers (1282) left this plan unfinished.", "fe224f07"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-11-18:0":{"b": ["Pope Martin IV excommunicated Michael VIII: the Union of Lyon was broken", "c4569aff"], "d": ["Pope Martin IV, a Frenchman elected on 22 February 1281, under the influence of Charles of Anjou excommunicated Emperor Michael VIII Palaiologos on 18 November 1281; thus the church union of Lyon was broken.", "9a9b275d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1333-01-01:0":{"b": ["The Republic of Dubrovnik purchased Pelješac together with Ston from the Serbian King Dušan", "702474c3"], "d": ["In 1333 Dubrovnik purchased the Pelješac peninsula together with Ston from the Serbian king Stefan Dušan; Ston became the Republic's second city for salt (saltworks).", "53d8f4b7"]},
"OLAYLAR_ORTACAG_BOZKIR:0567-01-01:0":{"b": ["Istemi Yabgu sent an embassy to Byzantium: the Gokturk-Byzantine alliance", "cef38140"], "d": ["Istemi Yabgu, whose relations with the Sasanians had broken down, sent an embassy to Constantinople in 567; this is the first embassy sent from Central Asia to Constantinople. The Byzantines also sent an envoy to Istemi Yabgu's center; the Gokturk-Byzantine alliance put the Sasanians in a difficult position.", "ba370a65"]},
"OLAYLAR_ORTACAG_BOZKIR:0922-05-12:0":{"b": ["The Abbasid embassy reached the camp of the khan of the Volga Bulgars; Almish Khan accepted Islam", "3416fffe"], "d": ["The Bulgar Khan Almish, son of Shilki, sent an envoy to the Caliph al-Muqtadir Billah informing him that he wished to become a Muslim. The delegation headed by Sawsan al-Rassi, which included Ibn Fadlan, reached the khan's camp on the Volga on 12 Muharram 310 (12 May 922); with the khan's formal acceptance of Islam, the Volga Bulgar state became a Muslim state subject to the Abbasid caliphate.", "2bb4aede"]},
"OLAYLAR_ORTACAG_BOZKIR:0965-01-01:0":{"b": ["The Volga Bulgars freed themselves from Khazar domination and became fully independent", "6425140e"], "d": ["When the Khazar Khaganate weakened as a result of Pecheneg and Cuman-Kipchak raids and the heavy blow it suffered from the Rus, the Volga Bulgars won their complete independence in 965.", "be12b363"]},
"OLAYLAR_ORTACAG_BOZKIR:0985-01-01:0":{"b": ["The Principality of Kievan Rus campaigned against the Volga Bulgar land", "66c87db1"], "d": ["The Volga Bulgar land suffered invasion by the Principality of Kievan Rus twice, in 964 and 985; these attacks were rendered ineffective.", "8c0bc16e"]},
"OLAYLAR_ORTACAG_BOZKIR:1006-01-01:0":{"b": ["A trade agreement was signed between the Principality of Kievan Rus and the Volga Bulgars", "50c7bd31"], "d": ["After the campaigns of 964 and 985, the two countries signed a trade agreement in 1006.", "1050f8d0"]},
"OLAYLAR_ORTACAG_BOZKIR:1078-01-01:0":{"b": ["The Kipchaks, together with the rebellious Pechenegs, besieged Adrianople", "b9fbc7ea"], "d": ["In 1078 the Kipchaks, together with the Pechenegs who had rebelled against Byzantium, laid siege to Adrianople; they subsequently raided Byzantium in 1083-1096 and 1109-1114.", "549cafaa"]},
"OLAYLAR_ORTACAG_BOZKIR:1209-01-01:0":{"b": ["The Qocho (Turfan) Uyghur idiqut Barchuq submitted to Genghis Khan", "b39f8607"], "d": ["The Turfan Uyghur state submitted to Genghis Khan in 1209 and continued to exist under Mongol administration until 1368; Barchuq Idiqut served in Genghis's army and in 1211 married Genghis's daughter Al-Altun. The submission took the form of voluntary vassalage.", "2225f854"]},
"OLAYLAR_ORTACAG_BOZKIR:1221-01-01:0":{"b": ["The Mongols took Balkh", "969bd4e3"], "d": ["After taking Herat, Tolui joined Genghis Khan; Genghis Khan spent the summer of 1220 at Nakhshab and seized Termez, and the following year (1221) crossed the Oxus and took Balkh.", "cdb8e36e"]},
"OLAYLAR_ORTACAG_BOZKIR:1221-01-01:1":{"b": ["The Mongols seized Gurganj (Urgench), the capital of Khwarazm", "a84fd33e"], "d": ["After the long siege by Chagatai, Jochi and Ogedei, the moats were filled in and the city was set on fire with naphtha; the population, except for the craftsmen, was massacred, and Shaykh Najm al-Din Kubra was also killed. Genghis Khan gave Khwarazm and Western Siberia to Jochi.", "039f9966"]},
"OLAYLAR_ORTACAG_BOZKIR:1221-01-01:2":{"b": ["Yuri II, Grand Prince of Vladimir, had the fortress of Nizhny Novgorod built", "0e58fe98"], "d": ["The Russian prince Yuri, son of Vsevolod, had the fortress of Nizhny Novgorod (Gorky) built in 1221 as part of Russian pressure on the Volga Bulgar lands.", "bc937f4a"]},
"OLAYLAR_ORTACAG_BOZKIR:1238-01-01:0":{"b": ["The Mongols plundered Moscow", "81cdd316"], "d": ["After many cities were taken in Batu Khan's campaign against the Russian principalities (late 1237), Moscow was plundered in February 1238.", "f298f66e"]},
"OLAYLAR_ORTACAG_BOZKIR:1239-10-18:0":{"b": ["The Mongols plundered Chernigov", "a88faba3"], "d": ["In Batu Khan's campaign against Russia, Chernigov (called 'Chernikov' in the TDV) was plundered in 1239.", "2fda24ee"]},
"OLAYLAR_ORTACAG_BOZKIR:1240-01-01:0":{"b": ["The Mongols seized and destroyed Kiev", "812e4cf8"], "d": ["After the Kipchaks were dispersed, the Mongols descended into the steppes of Ukraine in December 1240, and Kiev, the greatest principality of the region, was seized and destroyed; Batu's armies then plundered Poland, Hungary, Austria and Dalmatia.", "d5c24efa"]},
"OLAYLAR_ORTACAG_BOZKIR:1242-01-01:0":{"b": ["Batu Khan returned from his western campaign and settled in his homeland on the Volga; Sarai, the center of the Golden Horde, was founded", "48b498b4"], "d": ["Taking the news of Ogedei's death as an order to end the campaign, Batu Khan returned to his homeland in 1242 by way of Wallachia and Moldavia and founded his capital Sarai on the left bank of the Volga. Thus the Golden Horde Khanate, the western wing of the Jochid ulus, was established.", "6e98d911"]},
"OLAYLAR_ORTACAG_BOZKIR:1252-08-24:0":{"b": ["The vanguard units of Ket-Buqa Noyan set out from Karakorum on the western campaign", "b9a621af"], "d": ["By decision of the quriltai of Mongke Khan, Hulagu was assigned the tasks of eliminating the Isma'ilis, subjugating the Abbasid caliphate, and seizing Egypt and Syria; the vanguard units of Ket-Buqa Noyan set out on 24 August 1252.", "84326f37"]},
"OLAYLAR_ORTACAG_BOZKIR:1253-04-24:0":{"b": ["Hulagu set out from Karakorum on the campaign to Iran and the Near East", "62a1b34d"], "d": ["Hulagu set out from Karakorum on 24 April 1253, after his vanguard units; the vanguard moved against the Isma'ilis in May 1253.", "e8fb31db"]},
"OLAYLAR_ORTACAG_BOZKIR:1256-11-19:0":{"b": ["The Isma'ili leader Rukn al-Din Khurshah surrendered Alamut to Hulagu", "848fbdb5"], "d": ["Rukn al-Din Khurshah, the leader of the Isma'ilis at Alamut, who could not hold out against the Mongols, surrendered to Hulagu on 19 November 1256; Hulagu razed the fortress and put its people to the sword, and the Isma'ili fortresses in Syria were taken by Otchigin Noyan.", "b5404ed4"]}
});
